INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:acoustical_consultant',true,'PE License # [State Abbreviation]',ARRAY['State Boards of Professional Engineers and Land Surveyors (varies by state)','Institute of Noise Control Engineering (INCE) – BCA Certification','U.S. Green Building Council / GBCI – LEED AP Credential','U.S. Environmental Protection Agency (EPA) – Noise Control Act','Occupational Safety and Health Administration (OSHA) – 29 CFR 1910.95','International Code Council (ICC) – Building Acoustics Code Requirements','U.S. Department of Housing and Urban Development (HUD) – Minimum Property Standards']::text[],ARRAY['guaranteed noise reduction','completely soundproof','OSHA-approved consultant','EPA-certified acoustical engineer','licensed acoustical consultant (where no state acoustics license exists)','certified to eliminate all noise complaints']::text[],ARRAY['Acoustic consulting services performed under PE license where engineering seal is required by state law.','Environmental noise impact assessments do not constitute legal advice; findings may be subject to local agency review.','Expert witness testimony is provided as independent professional opinion and does not guarantee legal outcome.','LEED credit achievement depends on project team compliance with all applicable LEED prerequisites and is subject to GBCI review.','Noise measurements are conducted in accordance with applicable ANSI/ISO standards; results reflect conditions at time of measurement.']::text[],false,false,false,ARRAY['Must not claim governmental endorsement or approval from OSHA, EPA, or ICC unless formally designated.','Must not imply that a noise study guarantees regulatory approval or permit issuance.','Expert witness advertising must not reference case outcomes or client-specific legal results.','PE seal must only be affixed in states where the consultant holds a current active license.','BCA and INCE credentials must not be claimed if certification has lapsed or has not been renewed.']::text[])
