INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:aerated_drinks_supplier',true,'State Distributor License #',ARRAY['U.S. Food and Drug Administration (FDA) — Food Facility Registration under FSMA','USDA Agricultural Marketing Service — National Organic Program','SQF Institute — Safe Quality Food Certification Body','NSF International — Beverage Equipment Certification','FSSC — FSSC 22000 Certification Body','ISO — ISO 22000 Certification Auditors','HMRC — Soft Drinks Industry Levy (UK operations)','State Alcohol and Beverage Control Boards (where distributor licensing applies)']::text[],ARRAY['We guarantee the lowest prices on all carbonated beverages','Our products are certified safe for all health conditions','USDA Organic certified on all product lines','FDA approved beverages']::text[],ARRAY['Product availability subject to minimum order quantities and regional distribution coverage.','Organic certification applies only to designated product lines; not all SKUs are USDA Organic.','Sugar tax (Soft Drinks Industry Levy) compliance is the responsibility of the purchasing business in applicable jurisdictions.','FDA facility registration does not constitute product approval by the FDA.','Food safety certifications are subject to periodic audit and renewal; current certificate dates available upon request.','Custom flavor development timelines and MOQs vary by formulation complexity.']::text[],false,false,false,ARRAY['Must not imply FDA approval of specific beverage products','Must not make unsubstantiated health or medical claims for carbonated beverages','Must not claim ''certified organic'' for product lines not covered by active USDA NOP certificate','Must not guarantee price-matching without published pricing policy','Must comply with FTC guidelines on endorsements and testimonials in B2B marketing','Must disclose sugar content in compliance with 21 CFR Part 101 labeling on all distributed products','Must not advertise sugar tax exemption without verified product formulation analysis']::text[])
