INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:agricultural_cooperative',true,'State Cooperative Charter #',ARRAY['USDA Agricultural Marketing Service','USDA Rural Development','U.S. Commodity Futures Trading Commission (CFTC)','U.S. Environmental Protection Agency (EPA)','Occupational Safety and Health Administration (OSHA)','Internal Revenue Service (IRS) — Subchapter T','State Secretary of State — Cooperative Corporation Division','State Department of Agriculture — Fertilizer and Pesticide Programs','USDA Grain Inspection Packers and Stockyards Administration (GIPSA)']::text[],ARRAY['guaranteed grain price','guaranteed profits for members','FDIC insured','SEC-registered investment','we beat any price','risk-free commodity marketing','IRS-exempt from all taxes','unlimited patronage payout']::text[],ARRAY['Patronage dividends are not guaranteed and are subject to board approval and cooperative earnings each fiscal year.','Per-unit retains and equity revolvement schedules may vary and are governed by cooperative bylaws.','Commodity marketing pools involve market risk; past pool returns do not guarantee future results.','Crop insurance products are subject to federal program rules and policy terms; consult your agent.','This cooperative operates under the Capper-Volstead Act; membership must consist of agricultural producers.','Fertilizer, chemical, and fuel storage facilities operate under EPA and state environmental permits.','Grain storage is subject to USDA Warehouse Act licensing terms and conditions.']::text[],false,false,true,ARRAY['Cannot imply CFTC-registered investment adviser status unless licensed','Cannot advertise guaranteed commodity pricing or pool returns','Cannot use language implying bank deposit insurance (FDIC) for equity accounts','Patronage dividend projections must include material uncertainty disclaimer','Pesticide and fertilizer advertising must comply with EPA label and state ag department rules','Marketing pool enrollment materials may require CFTC disclosure if derivative instruments are used']::text[])
