INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:aluminum_frames_supplier',true,'ISO 9001 Certificate #',ARRAY['ASTM International (ASTM B221 standard)','RoHS Directive (EU) 2011/65/EU and successor 2015/863','OSHA (29 CFR 1910 General Industry — Material Handling and Warehousing)','California OEHHA (Proposition 65 — Safe Drinking Water and Toxic Enforcement Act)','U.S. Department of Transportation (49 CFR — Hazardous Materials and Freight Regulations)']::text[],ARRAY['guaranteed to meet all ASTM standards without documentation','certified to all international standards','no hazardous materials of any kind','lifetime corrosion-free guarantee','fully RoHS compliant — no testing required']::text[],ARRAY['Material certifications (MTRs) available upon request and should be verified by the buyer for each order','California Proposition 65 Warning: This product can expose you to chemicals including aluminum compounds, which are known to the State of California to cause cancer or reproductive harm','RoHS compliance is specific to alloy composition and finish — buyers should request lot-specific documentation','ASTM B221 compliance is based on mill certifications; independent testing is the buyer''s responsibility','DOT regulations apply to bulk freight — consult carrier for hazmat classification of specific alloys and finishes']::text[],false,false,false,ARRAY['Do not claim ISO 9001 certification without current valid certificate number and expiry date displayed','Do not claim ASTM compliance without referencing specific standard designation (e.g. ASTM B221)','Do not use the Aluminum Association logo without current membership verification','Proposition 65 warning must appear on product listings and invoices for California-destined shipments','RoHS compliance claims must specify applicable directive version and lot documentation availability']::text[])
