INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:amateur_theatre',true,'Dramatic Rights License # (per production)',ARRAY['ASCAP (American Society of Composers, Authors and Publishers)','BMI (Broadcast Music, Inc.)','Samuel French / Dramatists Play Service / Music Theatre International (dramatic rights publishers)','Local Fire Marshal (occupancy permits)','U.S. Department of Labor (child labor laws for youth performers)','State Department of Labor (child performer work permit requirements)','Internal Revenue Service (501(c)(3) nonprofit compliance)']::text[],ARRAY['Broadway-quality professional production','Equity actor casting guaranteed','We guarantee your child will be cast','Award-winning performances guaranteed','Fully licensed for all music and scripts (without specifying per-production)']::text[],ARRAY['All dramatic works performed under license from the respective rights holder. Unauthorized reproduction or performance is prohibited.','Music performed under license from ASCAP and/or BMI.','Youth performers under 18 are subject to applicable state child labor and work permit requirements.','Maximum occupancy as determined by local fire marshal. Exceeding posted occupancy limits is prohibited.','This is a nonprofit community theater. Donations may be tax-deductible to the extent permitted by law; consult your tax advisor.']::text[],false,false,false,ARRAY['Must not imply professional or commercial theater status when operating as amateur/community theater','Must not use performer names or likenesses in advertising without written consent','Dramatic rights titles must be advertised only after license is secured from the rights holder','Child performer images in advertising require parental/guardian consent','Must not misrepresent nonprofit status or imply donations are always fully tax-deductible without disclaimer']::text[])
