INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:ammunition_supplier',true,'Federal Firearms License (FFL) #',ARRAY['Bureau of Alcohol, Tobacco, Firearms and Explosives (ATF)','State firearms licensing authorities (varies by state)','California Department of Justice (Prop 63 ammunition background checks)','Sporting Arms and Ammunition Manufacturers Institute (SAAMI) — standards body','U.S. Department of Transportation (hazmat shipping regulations)']::text[],ARRAY['guaranteed to stop any threat','armor-piercing ammo for sale to civilians','no background check required','sell to anyone','untraceable ammunition','cop killer bullets available','no age verification needed','ship anywhere no restrictions']::text[],ARRAY['Age verification required: must be 21+ for handgun ammunition in applicable states','Hollow point and armor-piercing ammunition may be restricted or prohibited in certain states — customer responsible for verifying local laws','All online ammunition purchases subject to applicable state background check laws, including California Proposition 63','Ammunition shipping subject to carrier hazmat fees and state-specific delivery restrictions','Federal Firearms License held on premises — available for customer inspection upon request','We do not sell armor-piercing ammunition as defined under 18 U.S.C. § 922(a)(7) to non-exempt purchasers']::text[],true,false,false,ARRAY['Cannot advertise sale of armor-piercing ammunition to civilians','Must not depict or imply sales to prohibited persons under 18 U.S.C. § 922','Cannot make unsubstantiated lethality or stopping-power superiority claims','Must comply with ATF guidelines on FFL advertising and record-keeping','Social media advertising on Facebook/Instagram subject to platform firearms and ammunition advertising policies — no direct sale CTAs allowed on restricted platforms','California-targeted advertising must reference Prop 63 background check requirement']::text[])
