INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:animal_protection_organization',true,'IRS EIN # | State Charity Registration #',ARRAY['Internal Revenue Service (IRS) — 501(c)(3) compliance and Form 990','State Attorney General Charitable Trust Division — charitable solicitation registration','State Legislature / State Humane Law — humane officer authorization and cruelty statutes','USDA Animal and Plant Health Inspection Service (APHIS) — Animal Welfare Act compliance where applicable','State Ethics Commission — lobbyist registration for advocacy activities']::text[],ARRAY['We guarantee animal cruelty cases will result in prosecution','100% of donations go directly to animals','We are affiliated with the ASPCA/HSUS (without formal documented partnership)','No-kill guaranteed shelter','We are a government agency','Our organization is endorsed by [politician name]']::text[],ARRAY['This organization is a registered 501(c)(3) nonprofit. Donations may be tax-deductible to the extent permitted by law. Please consult a tax advisor.','Annual Form 990 is available for public inspection upon request and on GuideStar/Candid.','Humane law enforcement authority is jurisdiction-specific. Contact local law enforcement for emergencies.','State charitable solicitation registration does not imply endorsement by the state.','Advocacy activities are conducted in compliance with applicable lobbyist registration laws.','Donor and volunteer data is collected and stored in accordance with applicable data privacy regulations.']::text[],false,false,true,ARRAY['Must not imply government agency status or law enforcement authority beyond actual jurisdictional grant','Must not use emotionally manipulative imagery of animal suffering without accompanying factual context per platform policies','Must disclose nonprofit status in fundraising solicitations per state charitable solicitation laws','Must not make unsubstantiated claims about charity ratings or accreditations','Lobbying activity communications must comply with IRS restrictions on 501(c)(3) political activity','Must not imply formal partnership with HSUS, ASPCA, or other national organizations without documented affiliation agreement']::text[])
