INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:animation_studio',false,NULL,ARRAY['SAG-AFTRA (if union voice or performance capture talent is engaged)','U.S. Copyright Office (work-for-hire and IP assignment compliance)','ASCAP / BMI / SESAC / PRO (music sync and performance rights)','U.S. Bureau of Industry and Security (export controls for international co-productions)','California Privacy Protection Agency / FTC (CCPA and data privacy)']::text[],ARRAY['guaranteed viral video','Emmy Award winner (unless formally nominated and won)','Oscar-winning studio (unless formally credited)','We own all rights to your content (contradicts work-for-hire obligation to client)','SAG-AFTRA signatory (unless formally signed)']::text[],ARRAY['All productions involving SAG-AFTRA voice or performance capture talent are subject to applicable union agreements and residual obligations.','Music and sound elements incorporated in delivered works are subject to separate sync licensing agreements; client is responsible for ensuring broadcast clearance.','Intellectual property ownership and work-for-hire terms are governed by the executed production agreement; verbal commitments do not transfer IP rights.','Animations deployed in digital products or websites must meet applicable accessibility standards (WCAG 2.1 AA) where required by platform policy or law.','International co-productions may be subject to U.S. export control regulations; clients are advised to confirm compliance obligations before project commencement.']::text[],false,false,false,ARRAY['Do not claim award recognition (Annie, Clio, Emmy, Cannes Lions) without documented nomination or win','Do not imply SAG-AFTRA signatory status without formal union agreement in place','Do not guarantee broadcast clearance for music without confirmed sync license','Do not represent that animation meets WCAG standards without formal accessibility audit']::text[])
