INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:antique_furniture_restoration_service',true,'State Trade Contractor License #',ARRAY['U.S. Environmental Protection Agency (EPA) – VOC emissions from finishes and chemical strippers','Occupational Safety and Health Administration (OSHA) – Hazard Communication Standard (HazCom)','State business licensing authority for trade contractors','Local environmental authority – lead-based paint and chemical waste disposal','CITES (Convention on International Trade in Endangered Species) – protected timber species','Local fire marshal – solvent and flammable materials storage in workshop']::text[],ARRAY['guaranteed to restore original value','EPA-approved finish','certified antique authentication','restores museum-quality to any piece','fully reversible restoration guaranteed','will not affect auction house valuation','eliminate all evidence of damage','our work is invisible to experts']::text[],ARRAY['All chemical stripping and refinishing products comply with applicable EPA VOC regulations at time of application. Formulas may vary by jurisdiction.','Lead-based paint identified during assessment will be handled and disposed of in accordance with EPA Renovation, Repair and Painting (RRP) Rule and applicable local ordinances.','CITES-regulated timber species (including rosewood, ebony, and certain mahoganies) require documentation prior to import or use. Clients must provide provenance evidence for pieces containing listed species.','Condition reports and provenance documentation prepared by this studio are professional assessments only and do not constitute legally binding valuations or authentication certificates.','Restoration work may affect auction house or insurance valuations. Clients are advised to consult a certified appraiser before and after significant restoration work.','All goods accepted for workshop treatment are covered by our goods-in-transit and in-workshop insurance policy up to stated limits; clients should confirm individual piece values at intake.']::text[],false,false,false,ARRAY['Must not claim authentication or formal valuation authority without a licensed appraiser credential','Must not use ''EPA-approved'' or ''OSHA-certified'' unless specific product or process certification is held','Must not imply museum or heritage body endorsement without documented affiliation','Must comply with FTC guidelines on testimonials; before/after claims must reflect typical results or be individually qualified','Must not advertise use of CITES-listed timber species without confirming compliant sourcing documentation','VOC compliance claims in advertising must specify the regulatory standard met and jurisdiction']::text[])
