INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:aromatherapy_supply_store',true,'State Business License #',ARRAY['U.S. Food and Drug Administration (FDA) — cosmetic labeling under 21 CFR Part 700','U.S. Department of Agriculture (USDA) National Organic Program — organic certification','Federal Trade Commission (FTC) — advertising and health claim substantiation','State Department of Revenue — sales tax collection','Natural Products Association (NPA) — voluntary industry standards','OSHA Hazard Communication Standard — GHS labeling for hazardous botanical materials']::text[],ARRAY['cures anxiety','treats depression','heals wounds','eliminates cancer','FDA approved','clinically proven to treat','replaces prescription medication','guaranteed to relieve','medically certified','kills bacteria proven']::text[],ARRAY['These statements have not been evaluated by the Food and Drug Administration. These products are not intended to diagnose, treat, cure, or prevent any disease.','Essential oils must be diluted with a carrier oil before topical application. Consult a healthcare professional before use during pregnancy or with children.','Some products require child-resistant packaging per CPSC regulations. Keep all essential oils out of reach of children and pets.','GC/MS testing results reflect the tested batch only and do not guarantee uniformity across all future production lots.','USDA Organic certification applies only to designated product lines. Check individual product labels for certification status.']::text[],false,false,false,ARRAY['No unsubstantiated therapeutic or medical benefit claims on product pages, social media, or in-store signage (FTC Act Section 5)','No implied drug claims that would cause an essential oil product to be reclassified as a drug under FDA definition','Organic claims limited to USDA-certified product lines only; general ''all-natural'' claims must not imply organic certification','Ingredient disclosure required on all cosmetic product labels per FDA 21 CFR 701.3','Price advertising for wholesale must not create deceptive impression of consumer retail discounts','Health testimonials must include clear disclaimers that results are not typical and do not constitute medical advice']::text[])
