INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:art_restoration_service',true,'AIC Professional Associate / Fellow Designation',ARRAY['American Institute for Conservation (AIC) — Code of Ethics and Standards of Practice','International Institute for Conservation (IIC)','NAGPRA (Native American Graves Protection and Repatriation Act) — enforced by U.S. Department of the Interior','CITES (Convention on International Trade in Endangered Species) — enforced by U.S. Fish and Wildlife Service','OSHA — Hazard Communication Standard for solvent and chemical handling','IRS — Publication 526 and appraisal documentation requirements for charitable contributions involving restored artwork']::text[],ARRAY['Guaranteed to restore original value','Certified to increase appraisal','Will erase all damage completely','Fully reversible in all cases','Museum-grade results guaranteed','No chemicals used']::text[],ARRAY['All treatment proposals are estimates; final scope may change upon examination.','Conservation treatments are performed in accordance with the AIC Code of Ethics, emphasizing reversibility and minimal intervention.','Handling of objects subject to NAGPRA requires tribal consultation and federal compliance prior to treatment.','Work involving materials containing protected species (ivory, tortoiseshell) requires CITES documentation; client is responsible for provenance verification.','Restoration that alters an artwork''s condition may affect its appraised value; IRS-compliant documentation is recommended for tax-deductible donations.','This studio carries fine art handling insurance; clients should maintain their own fine art coverage during transit.']::text[],false,false,true,ARRAY['Cannot claim AIC Fellow status without current AIC membership verification','Cannot advertise NAGPRA-compliant services without documented tribal consultation procedures','Cannot guarantee valuation outcomes or IRS deduction eligibility','Must not imply CITES-regulated items can be treated without required permits','Advertising of emergency services must reflect actual 24-hour availability']::text[])
