INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:asian_restaurant',true,'Health Permit # | Liquor License #',ARRAY['Local/County Health Department','State Alcoholic Beverage Control (ABC) Board','Local Fire Marshal','ADA Enforcement (U.S. Department of Justice)','OSHA (for kitchen safety)']::text[],ARRAY['healthiest restaurant in the city','100% allergen-free','guaranteed food allergy safe','no risk of cross-contamination','best health score in town','certified organic']::text[],ARRAY['Health department inspection grade must be publicly posted per local ordinance','Allergen information must be disclosed upon request per FDA Food Allergen Labeling requirements','Liquor license number and class must be posted on premises','Alcohol service is restricted to guests 21 years of age or older','Occupancy limits enforced per local fire code']::text[],true,false,false,ARRAY['Cannot claim health department grade superiority without current documented inspection','Cannot advertise alcohol promotions in violation of state ABC advertising rules','Cannot use terms like ''organic'' or ''non-GMO'' without certified supply chain documentation','Must not make unverified allergen-free claims in advertising','Influencer partnerships must include FTC-required disclosure of material relationship']::text[])
