INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:asylum_center',true,'BIA Accreditation # / USCIS-Recognized Organization ID',ARRAY['U.S. Citizenship and Immigration Services (USCIS)','Executive Office for Immigration Review (EOIR) — Board of Immigration Appeals (BIA)','Internal Revenue Service (IRS) — 501(c)(3) compliance','State Attorneys General — Charitable Solicitation Registration','U.S. Department of Health and Human Services — HIPAA (for mental health records)','State Mandatory Reporter Laws — child protective services compliance']::text[],ARRAY['guaranteed asylum approval','we will get your case approved','best chance of winning your asylum case','certified immigration consultant','notario services','immigration consultant — not an attorney']::text[],ARRAY['This organization provides legal assistance through licensed attorneys and BIA-accredited representatives only. Non-attorney staff do not provide legal advice.','Nothing on this website or in our materials constitutes legal advice. Each case is unique and outcomes cannot be guaranteed.','This organization is not a government agency and is not affiliated with USCIS, ICE, or any immigration enforcement body.','Mental health referral services do not establish a provider-patient relationship with this organization. HIPAA-protected records are maintained separately.','This organization complies with all applicable data privacy requirements for vulnerable population client records.','Mandatory reporter obligations: all staff working with minors are required by law to report suspected abuse or neglect.']::text[],false,true,false,ARRAY['May not use testimonials identifying asylum clients without explicit written consent and anonymization protocols','May not imply success rate guarantees or case outcome predictions in advertising','May not describe non-attorney staff as immigration lawyers or legal advisors','Must include organizational disclaimer in all paid advertising indicating non-government affiliation','Social media advertising targeting must not expose client identities or case details']::text[])
