INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:athletic_club',true,'State Business License #',ARRAY['State Health Department (pool and locker facility inspections)','State Attorney General / Consumer Protection Division (health club contract laws)','Occupational Safety and Health Administration (OSHA)','American Red Cross (lifeguard and CPR certification standards)','Americans with Disabilities Act enforcement (DOJ / ADA National Network)','USA Swimming (aquatics program affiliation standards)']::text[],ARRAY['guaranteed weight loss','cure or treat any medical condition','best gym in [city] — guaranteed','results may be typical']::text[],ARRAY['Members have the right to cancel their membership within [state-specified] days per state health club contract law.','Pool and locker facilities are subject to state health department inspection and must meet applicable safety codes.','Personal trainers are certified professionals but services do not constitute medical advice or physical therapy.','ADA accommodations are available upon request; please contact us for specific accessibility needs.','Results from personal training or fitness programs vary by individual and are not guaranteed.']::text[],false,false,false,ARRAY['Cannot claim guaranteed weight loss or specific health outcome results','Cannot imply medical treatment or physical therapy services unless licensed PT is on staff','Must honor state-mandated cancellation window in all membership advertising','Corporate wellness benefit claims must not overstate medical cost savings without substantiation','Pool and aquatics safety claims must align with current inspection and certification status']::text[])
