INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:audio_visual_equipment_supplier',true,'State Low-Voltage / Electrical Contractor License #',ARRAY['State Electrical Licensing Board (jurisdiction-specific)','Federal Communications Commission (FCC) - equipment authorization','National Fire Protection Association (NFPA) - NEC Article 725/800 enforcement via local AHJ','Americans with Disabilities Act (ADA) - Department of Justice assistive listening requirements','Local Building and Permitting Authority (AHJ - Authority Having Jurisdiction)']::text[],ARRAY['guaranteed lowest price on all AV equipment','FCC-approved (products must carry FCC authorization, not the installer)','licensed electrician (unless the entity holds full electrical contractor license)','our systems are fully ADA compliant (compliance is system- and venue-specific)','certified by Crestron (exact dealer tier language must match manufacturer authorization level)']::text[],ARRAY['AV system installation may require local building permits; permit requirements vary by jurisdiction and installation scope.','Assistive listening system ADA compliance depends on venue occupancy load and system configuration; consult applicable ADA Standards for Accessible Design.','FCC equipment authorization applies to specific products as tested; installation of non-authorized RF distribution equipment may violate federal law.','Extended warranty and service contract terms are subject to written agreement; verbal commitments are not binding.','Electrical wiring performed during AV installation is subject to NEC requirements and local code amendments; a licensed electrical contractor must perform or supervise line-voltage work where required by state law.']::text[],false,false,false,ARRAY['Do not claim manufacturer authorization tiers (e.g. Crestron Platinum Dealer) unless currently verified and documented','Do not use comparative superlatives (best, #1, top-rated) without substantiated third-party source','FCC Part 15 and Part 74 equipment must not be advertised for uses outside their authorization scope','Do not advertise products with CE marking only as FCC-authorized for US distribution','Energy Star claims for display products require current certification verification per product SKU']::text[])
