INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:auto_insurance_agency',true,'State Insurance Producer License #',ARRAY['State Department of Insurance (jurisdiction-specific)','National Association of Insurance Commissioners (NAIC) model law framework','Federal Trade Commission (FCRA compliance for credit-based insurance scoring)','Financial Industry Regulatory Authority (FINRA where securities-linked products offered)','Gramm-Leach-Bliley Act enforcement via FTC and state regulators']::text[],ARRAY['guaranteed lowest rate','cheapest insurance guaranteed','we always beat competitors','full coverage protects you from everything','your claim will definitely be approved','guaranteed acceptance regardless of driving record']::text[],ARRAY['Coverage availability and pricing vary by state and individual underwriting factors.','This agency is licensed in [State]. License number available upon request.','Credit-based insurance scoring is used in accordance with applicable state law and the Fair Credit Reporting Act.','SR-22 filing requirements vary by state. Consult your state DMV for specific obligations.','GAP insurance may not cover all situations where loan balance exceeds vehicle value. Review policy terms carefully.','Policy comparisons are provided for informational purposes. Final rates are determined by the issuing carrier.']::text[],false,false,true,ARRAY['Must not imply government affiliation or endorsement','Cannot guarantee specific premium amounts before underwriting','Must disclose carrier identity when advertising specific rates','Credit score use in rating must comply with state opt-out notification requirements','All advertised discounts must reflect actual achievable savings with named carriers','SR-22 advertising must not imply immediate license reinstatement without DMV confirmation']::text[])
