INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:auto_market',true,'State Motor Vehicle Dealer License #',ARRAY['State Department of Motor Vehicles (varies by state)','Federal Trade Commission (FTC) — Used Car Rule','Consumer Financial Protection Bureau (CFPB) — Regulation Z / TILA','Financial Crimes Enforcement Network (FinCEN) — AML / IRS Form 8300','State Attorney General — Lemon Law enforcement']::text[],ARRAY['guaranteed credit approval','no questions asked financing','100% financing guaranteed','best price guaranteed','we beat any dealer']::text[],ARRAY['FTC Used Car Buyers Guide must be displayed on every vehicle offered for sale','All financing subject to credit approval. APR and terms disclosed per Regulation Z.','Cash transactions of $10,000 or more are reported to the IRS as required by federal law.','Odometer disclosure statement required on all vehicles as required by federal law.','Lemon law rights vary by state. Ask your sales representative for applicable state disclosures.','As-is sales disclaim implied warranties where permitted by state law.']::text[],false,false,true,ARRAY['All advertised prices must include all mandatory fees or disclose exclusions clearly','Credit terms advertised must include full TILA trigger term disclosures (APR, term, payment, down payment)','Bait-and-switch advertising of unavailable vehicles is prohibited under FTC guidelines','Dealer must not advertise a vehicle as certified if it does not meet the applicable certification standards','Cash transaction reporting obligations must not be avoided through structuring']::text[])
