INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:aviation_consultant',true,'FAA Certificate # / Credential ID',ARRAY['Federal Aviation Administration (FAA)','National Transportation Safety Board (NTSB) — accident investigation oversight','International Civil Aviation Organization (ICAO) — international standards','U.S. Department of State Directorate of Defense Trade Controls (DDTC) — ITAR','U.S. Department of Commerce Bureau of Industry and Security (BIS) — EAR','National Business Aviation Association (NBAA) — professional standards']::text[],ARRAY['guaranteed FAA certification approval','we guarantee your Part 135 certificate','FAA-approved consultant','NTSB-certified investigator','we guarantee audit success','our advice is legally binding without aviation attorney review']::text[],ARRAY['Consulting advice does not constitute legal counsel; clients should retain qualified aviation attorneys for legal matters.','Consultant scope of services is governed by individual engagement agreements; advice is advisory only.','ITAR/EAR compliance advice does not substitute for export counsel licensed in U.S. export control law.','Results of prior client engagements do not guarantee similar outcomes for future clients.','Consultants providing maintenance advisory must not exceed the scope of authorized repair station activity per 14 CFR Part 145.','Disclosure is required when consultant serves in dual roles for both an operator and a regulatory body.']::text[],false,false,true,ARRAY['Must not imply FAA endorsement or approval of consulting services','Must not use the FAA or NTSB seal, logo, or insignia in advertising','Must comply with FAA Advisory Circular guidelines when describing regulatory services','ITAR-controlled technology and services must not be advertised to foreign nationals without proper export authorization','Must disclose material conflicts of interest in dual-role engagements in all client-facing materials','Must not make unsubstantiated performance claims regarding certification success rates']::text[])
