INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:bag_shop',false,NULL,ARRAY['U.S. Federal Trade Commission (FTC) — Made in USA and product origin labeling','U.S. Department of Justice / U.S. Customs and Border Protection — Trademark Counterfeiting Act enforcement','California Office of Environmental Health Hazard Assessment (OEHHA) — Proposition 65','European Chemicals Agency (ECHA) — REACH Regulation for EU-bound synthetic materials','State sales tax authorities — nexus compliance for online and multi-state retail']::text[],ARRAY['guaranteed authentic','100% genuine leather without documentation','Made in USA without FTC-compliant substantiation','luxury-grade materials without specification','designer-inspired (when implying brand association)','replica or knockoff (as a product descriptor)']::text[],ARRAY['Pre-owned designer bags are authenticated using [authentication method]; authenticity certificates provided at point of sale.','Products sold in California may contain chemicals known to the State of California to cause cancer or reproductive harm — California Proposition 65 Warning.','FTC-compliant product origin disclosures are provided on all items marketed as Made in USA.','Consignment items are sold as-is; consignment terms and seller agreements are available in-store.','REACH compliance documentation is available upon request for synthetic leather products shipped to EU destinations.']::text[],false,false,false,ARRAY['Do not use brand-name designer logos or trademarks in advertising without explicit written authorization from the trademark holder','Do not use the term ''authentic'' for pre-owned goods without providing verifiable authentication documentation','FTC endorsement and testimonial guidelines apply to all customer reviews and influencer partnerships','Prop 65 warnings must appear on California-targeted digital advertising where applicable','Do not imply exclusivity or authorized status with a brand without written authorized retailer agreement on file']::text[])
