INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:band',true,'PRO Registration # (ASCAP/BMI/SESAC)',ARRAY['American Society of Composers, Authors and Publishers (ASCAP)','Broadcast Music Inc. (BMI)','SESAC','American Federation of Musicians (AFM)','State and Local Noise Ordinance Authorities','State Sales Tax Authorities (merchandise sales)']::text[],ARRAY['Officially licensed by [Artist Name]','Endorsed by [Major Artist]','Guaranteed chart-topping performance','Award-winning band (without verified award citation)','Best band in [City] (without verified source)']::text[],ARRAY['Performance subject to signed venue contract and rider fulfillment','ASCAP, BMI, or SESAC licensing responsibility falls on the venue for cover song performances under U.S. copyright law','Sales tax on merchandise collected and remitted per applicable state law','Noise levels subject to local ordinance compliance — venue must confirm decibel limits in advance','Cancellation and deposit terms governed by signed performance agreement']::text[],false,false,false,ARRAY['Cannot claim official endorsement or affiliation with other artists without written authorization','Must not misrepresent cover song performances as original compositions','Cannot advertise unlicensed use of third-party intellectual property in promotional materials','PRO licensing obligations must not be misrepresented as the band''s responsibility when venue-side licensing applies']::text[])
