INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:bar_stool_supplier',false,NULL,ARRAY['U.S. Consumer Product Safety Commission (CPSC)','Business and Institutional Furniture Manufacturers Association (BIFMA)','California Department of Public Health (TB 117-2013)','California Office of Environmental Health Hazard Assessment (Prop 65)','U.S. Access Board (ADA Accessibility Guidelines)']::text[],ARRAY['BIFMA certified','ANSI approved','meets all safety standards','100% safe for all users','fully ADA compliant','Prop 65 safe','no harmful chemicals','guaranteed fireproof','passes all flammability tests']::text[],ARRAY['ANSI/BIFMA X5.1 test results apply to specific tested models only and do not cover all products in our catalog','California Proposition 65 Warning: This product can expose you to chemicals including [chemical name], which is known to the State of California to cause [cancer/reproductive harm]. For more information go to www.P65Warnings.ca.gov','California TB 117-2013 compliance applies to upholstered products; verify applicability for your specific order','ADA counter height guidance is informational only; consult a licensed designer or accessibility consultant for compliance determinations','Weight capacity ratings are model-specific; confirm specifications before commercial deployment']::text[],false,false,false,ARRAY['Do not claim BIFMA certification without current third-party test report on the specific SKU','Do not imply Prop 65 clearance without current disclosure documentation','Do not claim ADA compliance for products without verified accessible design specifications','Do not advertise California TB 117-2013 compliance without testing documentation for the specific fabric and fill combination','CPSC flammability claims must reference the specific standard version tested and the model tested']::text[])
