INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:bar_tabac',true,'Numéro de Licence Débitant de Tabac #',ARRAY['Direction Générale des Douanes et Droits Indirects (DGDDI)','Ministère de l''Intérieur (Licence IV alcool)','Française des Jeux (FDJ) — agrément revendeur','PMU (Pari Mutuel Urbain) — convention partenaire','Direction Générale des Finances Publiques (caisse certifiée)','Autorité Nationale des Jeux (ANJ) — supervision jeux d''argent']::text[],ARRAY['tabac sans danger','cigarettes légères sans risque','jeux garantis gagnants','pariez en toute sécurité sans risque de perte','alcool consommé sans modération','vente de tabac autorisée aux mineurs','e-cigarette totalement sans risque','grattez et gagnez à coup sûr']::text[],ARRAY['Vente de tabac interdite aux mineurs de moins de 18 ans — pièce d''identité exigée','Fumer tue — affichage obligatoire des avertissements sanitaires conformément à la Directive Européenne sur les Produits du Tabac','Jouer comporte des risques : endettement, isolement, dépendance. Appelez le 09 74 75 13 13 (service gratuit)','L''abus d''alcool est dangereux pour la santé. À consommer avec modération. Interdiction de vente d''alcool aux mineurs','La vente de tabac est un monopole d''État — seuls les buralistes agréés sont autorisés à vendre du tabac','Caisse enregistreuse certifiée conforme à la réglementation fiscale française']::text[],true,false,true,ARRAY['Publicité directe pour le tabac interdite par la Loi Évin','Publicité pour les jeux d''argent soumise à l''agrément de l''ANJ','Promotion de l''alcool soumise à la Loi Évin — interdiction de publicité ciblant les mineurs','Affichage des prix du tabac interdit (prix imposés par l''État)','Interdiction de toute promotion comparative sur les produits du tabac','Communication sur les jeux doit inclure le message de jeu responsable']::text[])
