INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:betawi_restaurant',true,'Halal Certificate # (MUI/LPPOM)',ARRAY['Majelis Ulama Indonesia (MUI) — Halal Certification','LPPOM MUI — Institute for Food, Drug and Cosmetics Assessment','Indonesian Ministry of Health — Food Safety and Handler Certification','Local Dinas Kesehatan (District Health Office) — Restaurant Hygiene Inspection','Badan Pengawas Obat dan Makanan (BPOM) — Food and Drug Control Agency']::text[],ARRAY['guaranteed halal without current MUI certificate','100% pork-free without verified halal audit','authentic Betawi recipe certified by government','best Betawi restaurant in Indonesia (unsubstantiated superlative)','no allergens present','safe for all allergies']::text[],ARRAY['Halal certificate issued by MUI/LPPOM; certificate number and expiry date must be displayed on premises and profile','Peanuts are a common ingredient in Betawi dishes including gado-gado and karedok; customers with peanut allergies must be informed','Food prepared in a kitchen that handles tree nuts, seafood, and other common allergens; cross-contamination risk disclosure required','Country and region of origin claims (authentic Betawi cuisine) must reflect actual recipe heritage and chef training','Catering menus subject to ingredient availability; substitutions disclosed in advance']::text[],false,false,false,ARRAY['Do not claim MUI halal certification without displaying current valid certificate number and expiry','Do not use the term halal-certified in advertising unless certificate is active and verifiable','Allergen information must be accessible on both in-person menu and any digital menu linked from profile','Authenticity claims referencing Betawi heritage must be substantiated by chef credentials or family lineage documentation','Health inspection ratings may not be advertised without the current inspection cycle reference']::text[])
