INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:billiards_supply_store',false,NULL,ARRAY['Federal Trade Commission (FTC) — Truth in Advertising Rules','Consumer Product Safety Commission (CPSC) — Table Stability and Materials Safety','State Revenue Departments — Sales Tax Collection Requirements','Federal Trade Commission (FTC) — Magnuson-Moss Warranty Act Enforcement']::text[],ARRAY['guaranteed to improve your game','safest table on the market','lifetime guarantee without conditions','#1 pool table dealer in the country','approved by any governing body without verification','professional-grade without specification','meets all safety standards without citation']::text[],ARRAY['Warranty terms are subject to the conditions outlined in our written warranty document provided at time of purchase, as required under the Magnuson-Moss Warranty Act.','Product claims reflect manufacturer specifications. Actual performance may vary by use, environment, and maintenance.','Sales tax will be applied to all purchases in accordance with applicable state and local regulations.','BCA certification applies to named technicians on staff. Verify current certification status upon scheduling service.']::text[],false,false,false,ARRAY['Cannot claim BCA or manufacturer certification without current valid credential on file','Cannot advertise a product as meeting CPSC standards without verified compliance documentation','Cannot make superlative claims (best, safest, #1) without substantiation per FTC guidelines','Warranty advertisements must reflect actual written warranty terms per Magnuson-Moss Act','Used table descriptions must accurately represent condition; misrepresentation may constitute deceptive trade practice under FTC Act']::text[])
