INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:blood_donation_center',true,'FDA Establishment Registration # | State Blood Bank License # | AABB Accreditation #',ARRAY['U.S. Food and Drug Administration (FDA) — 21 CFR Parts 606 and 640','AABB (formerly American Association of Blood Banks)','Occupational Safety and Health Administration (OSHA) — 29 CFR 1910.1030 Bloodborne Pathogens Standard','State Public Health Department (jurisdiction-specific blood bank licensing authority)','Federal Trade Commission (FTC) — donor incentive program advertising guidelines']::text[],ARRAY['guaranteed safe blood','100% risk-free donation','your donation will save X specific lives','paid blood donation','sell your blood','compensation for blood','we will cure your condition','clinically proven health benefits of donating']::text[],ARRAY['Blood donation eligibility is subject to FDA-mandated health screening at time of donation; eligibility cannot be pre-confirmed online.','Donor incentives are offered in compliance with FTC guidelines and applicable state regulations; incentives do not constitute payment for blood.','All donor health information is protected under HIPAA and applicable state health privacy laws.','This facility is registered with the U.S. FDA as a blood establishment and operates under AABB accreditation standards.','Donor deferral decisions are made by trained staff per FDA-approved protocols and are not subject to appeal at the donation site.']::text[],true,true,false,ARRAY['Must not advertise monetary payment for blood donation in a manner that could be construed as compensation for human blood under FDA guidance','Donor incentive program promotions must comply with FTC truth-in-advertising guidelines and disclose material conditions','Blood shortage urgency claims in advertising must reflect current, verifiable inventory status and must not be used as perpetual marketing claims','Cannot make therapeutic benefit claims to donors (e.g., implying donation cures disease or improves donor health) without substantiation','Staff credential claims in advertising must reflect currently valid, verifiable certifications','Must not use patient outcome guarantees or survival statistics attributable to a specific donation in promotional materials']::text[])
