INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:board_game_club',true,'Food & Beverage Health Permit #',ARRAY['Local Health Department (Food and Beverage Service)','Local Fire Marshal / Building Authority (Occupancy Limits)','State or Local Child Welfare Authority (Youth Program Background Checks)','ADA Enforcement (Physical Premises Accessibility)']::text[],ARRAY['guaranteed to improve your child''s intelligence','clinically proven cognitive benefits','best board game club in the world','no experience necessary — anyone can win our tournaments']::text[],ARRAY['Venue capacity limits are enforced in compliance with local fire and occupancy regulations.','Food and beverage service is conducted under a valid health permit. Permit number available upon request.','Youth program staff have completed background checks as required by applicable local regulations.','This venue is committed to ADA accessibility. Please contact us in advance if you require specific accommodations.']::text[],false,false,false,ARRAY['Do not advertise alcohol service without confirming applicable liquor license is held.','Youth program advertising must not imply unsupervised child drop-off without documented supervision policy.','Occupancy-based event advertising must not promote attendance figures that exceed permitted venue capacity.','Publisher demo events advertised as exclusive must reflect actual contractual exclusivity.']::text[])
