INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:bridal_shop',false,NULL,ARRAY['Federal Trade Commission (FTC) — layaway, deposit, and advertising disclosure requirements','State Consumer Protection Offices — special-order merchandise refund and cancellation laws','U.S. Department of Justice — Americans with Disabilities Act Title III (public accommodations)']::text[],ARRAY['guaranteed lowest price on designer gowns','all sales final (without conspicuous pre-sale disclosure)','no refunds under any circumstances','your deposit is always fully refundable','authorized by [designer] (without current written authorization on file)','in stock and ready to ship in [X days] (without verified inventory confirmation)']::text[],ARRAY['Special-order gowns are made to order and may not be returned or exchanged; deposit terms disclosed in writing prior to purchase','Layaway and deposit policies including forfeiture conditions must be provided to the consumer in writing at time of order per FTC guidelines','Cancellation and refund rights vary by state; consult applicable state consumer protection statute for your jurisdiction','Alteration timelines are estimates; final delivery dates subject to order arrival from manufacturer','Sample sale gowns sold as-is; alteration costs are the buyer''s responsibility','This boutique is a place of public accommodation and must comply with ADA accessibility requirements']::text[],false,false,true,ARRAY['FTC requires clear and conspicuous disclosure of all material deposit and layaway terms in advertising','State unfair and deceptive acts and practices (UDAP) statutes prohibit misleading claims about refund policies or designer authorization status','Price comparisons to competitor or MSRP must be substantiated per FTC Price Guides','Testimonials and endorsements must reflect genuine customer experiences per FTC Endorsement Guides (16 CFR Part 255)','Social media posts featuring real brides must include disclosure if any compensation or free services were provided']::text[])
