INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:buffet_restaurant',true,'Food Service Establishment License #',ARRAY['Local/County Health Department','State Department of Health — Food Safety Division','State Alcoholic Beverage Control Board (if alcohol served)','National Restaurant Association Educational Foundation (ServSafe program authority)']::text[],ARRAY['guaranteed freshest food','100% allergen-free','zero risk of contamination','FDA approved buffet','Michelin starred','no wait ever','unlimited premium seafood always available']::text[],ARRAY['Menu items and availability are subject to change without notice.','Consuming raw or undercooked meats, poultry, seafood, shellfish, or eggs may increase your risk of foodborne illness.','Please inform a staff member of any food allergies before dining.','Alcohol service subject to state licensing laws; valid ID required.','Pricing and hours may vary on holidays and special events.','ADA accommodations available upon request; please contact us in advance.']::text[],false,false,false,ARRAY['Cannot advertise alcohol in jurisdictions requiring separate alcohol advertising permits','Must not make unsubstantiated health or caloric claims about buffet items','Allergen claims must be substantiated and comply with state truth-in-menu laws','Senior and children discount advertising must specify eligible age ranges to avoid deceptive pricing claims','Cannot use misleading pricing in advertisements that omit taxes or mandatory fees']::text[])
