INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:bugatti_dealer',true,'Motor Vehicle Dealer License #',ARRAY['State Motor Vehicle Dealer Licensing Authority (jurisdiction-specific, e.g. DMV or equivalent)','Bugatti Automobiles S.A.S. (franchise agreement compliance)','Financial Industry Regulatory Authority or equivalent (for finance introductions)','Anti-Money Laundering compliance authority (FinCEN in US; HMRC in UK; jurisdiction-specific)','Consumer Financial Protection Bureau or equivalent (for vehicle financing disclosures)','Customs and Border Protection or equivalent (vehicle import and homologation)']::text[],ARRAY['Guaranteed approval for any buyer','Best price guaranteed','No questions asked','We beat any deal','Pre-approved financing for all credit types','Zero percent interest guaranteed']::text[],ARRAY['All vehicle prices quoted exclude taxes, registration, and destination charges','Finance and leasing products are provided through third-party lenders; credit subject to status','Anti-money-laundering identity verification required for all high-value transactions','Vehicle specifications and availability subject to change without notice','Certified pre-owned warranty terms and conditions available on request','Personal data collected in accordance with applicable data protection legislation (GDPR or equivalent)','Dealer is an authorized independent retailer; not a direct representative of Bugatti Automobiles S.A.S. for warranty claims']::text[],false,false,true,ARRAY['Must not imply direct factory pricing or allocation guarantees not authorized by Bugatti Automobiles S.A.S.','Must not use Bugatti trademarks or imagery beyond scope permitted in franchise agreement','All finance-related advertising must include required APR and credit disclaimer language','Anti-money-laundering obligations must not be referenced in a manner that discourages lawful due diligence','Must not make unsubstantiated performance or investment return claims for specific vehicles']::text[])
