INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:business_management_consultant',true,'CMC Designation # | State Advisory License # (where applicable)',ARRAY['Institute of Management Consultants USA (IMC USA)','Project Management Institute (PMI) — PMP credential oversight','Securities and Exchange Commission (SEC) — if providing investment advisory','State Financial Regulatory Authorities — for financial advisory licensing','State Bar Associations — if legal advisory services are offered','AICPA — if CPA and financial reporting advisory is performed']::text[],ARRAY['guaranteed results','we will fix your business','proven to increase revenue by X%','risk-free consulting','we have never had a failed engagement','we guarantee ROI within 90 days']::text[],ARRAY['Past client outcomes do not guarantee future results. Each engagement is unique to the client''s circumstances.','Confidential client information is protected under executed NDA agreements in accordance with IMC USA ethics standards.','This firm is not a licensed law firm or accounting firm. Engagements that require licensed legal or financial advice will be referred to licensed professionals.','SOX compliance advisory is informational only and does not constitute legal or audit opinion. Publicly traded clients should engage qualified external auditors.','Data collected during consulting engagements is handled in accordance with GDPR and CCPA requirements where applicable.']::text[],false,false,true,ARRAY['Cannot claim specific guaranteed financial outcomes or revenue improvements','Cannot imply SEC-registered investment advisor status without registration','Must not use client names or case study details without written consent','Testimonials must reflect genuine client experiences and cannot be fabricated or incentivized','IMC USA code of ethics prohibits advertising that misrepresents qualifications or scope of services','Must disclose any material conflicts of interest in all marketing materials where a referral fee or commission relationship exists']::text[])
