INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:butane_gas_supplier',true,'State Fire Marshal LPG Distributor License #',ARRAY['State Fire Marshal (LPG Distributor Licensing)','U.S. Department of Transportation (DOT) — Hazardous Materials Regulations (49 CFR)','National Fire Protection Association (NFPA) — NFPA 58 Liquefied Petroleum Gas Code','U.S. Environmental Protection Agency (EPA) — VOC Emissions Regulations','Occupational Safety and Health Administration (OSHA) — 29 CFR 1910.110']::text[],ARRAY['guaranteed lowest price on gas','100% safe — no hazards','no regulations apply to small cylinder sales','unlimited liability coverage','EPA exempt supplier','OSHA compliant without inspection','same as natural gas']::text[],ARRAY['Butane and LPG are flammable gases. Always follow NFPA 58 storage and handling guidelines.','Cylinder transport and delivery vehicles are subject to DOT hazardous materials regulations.','Cylinder requalification is required under DOT SP 14743; expired cylinders cannot be refilled.','This business operates under a State Fire Marshal LPG Distributor License. License number available upon request.','Emergency delivery availability may vary by location and weather conditions.']::text[],false,false,false,ARRAY['Cannot claim ''government-approved'' without citing specific certification','Must not imply cylinders are exempt from DOT requalification requirements','Promotional pricing must disclose contract terms and delivery minimums','Cannot advertise emergency delivery without genuine 24/7 operational capability','VOC emissions claims must align with current EPA compliance status']::text[])
