INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:camp',true,'State Childcare License #',ARRAY['State Department of Health and Human Services (varies by state)','State Department of Social Services / Child and Family Services (varies by state)','American Camp Association (voluntary accrediting body)','State Fire Marshal (facility inspections)','Local Health Department (food safety and sanitation)','U.S. Department of Justice — ADA Title III (disability accommodations)']::text[],ARRAY['guaranteed safe environment','100% accident-free','we never have incidents','fully immune from liability','certified therapists on staff (unless licensed clinicians are actually employed)','state-approved curriculum (without documented approval)']::text[],ARRAY['This facility is licensed by [State Agency Name]. License number available upon request.','All staff have completed background checks in accordance with state requirements.','Our camp is accredited by the American Camp Association. Accreditation does not guarantee the prevention of all accidents or incidents.','Parents/guardians should review our health and medication administration policies prior to enrollment.','ADA accommodations are available; please contact us to discuss your child''s specific needs before enrollment.','Financial assistance programs are subject to availability and eligibility requirements.']::text[],false,false,false,ARRAY['May not claim accreditation not currently held or expired','May not guarantee child safety outcomes','Must not imply state endorsement beyond holding a valid license','Staff qualification claims (e.g., ''all staff are certified'') must be verifiable and current','Testimonials from parents must include consent and cannot be fabricated or incentivized','Scholarship or financial aid claims must reflect actual available funding']::text[])
