INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:car_inspection_station',true,'State DMV Authorized Inspection Station #',ARRAY['State Department of Motor Vehicles (DMV) or equivalent state authority','U.S. Environmental Protection Agency (EPA) — Clean Air Act emissions testing','Bureau of Automotive Repair (BAR) — California and applicable states','American Association of Motor Vehicle Administrators (AAMVA)']::text[],ARRAY['Guaranteed to pass inspection','We can help you pass without fixing your car','Best smog check — we pass everyone','Skip the line with our no-fail policy','We work around the OBD monitors','Inspection passed, no repairs needed']::text[],ARRAY['This station is authorized by the state DMV to perform official vehicle inspections. Results are final and reported to the state.','Inspection fees are set or capped by state regulation. Additional repair costs are separate and not included in the inspection fee.','A failed inspection report is an official state document. Tampering with or falsifying inspection records is a criminal offense.','OBD-II readiness monitors must meet state thresholds; customers are advised to complete a drive cycle after repairs before presenting for reinspection.','Inspection stickers and certificates are valid only for the period specified by state law. Operating a vehicle with an expired certificate may result in fines.']::text[],false,false,false,ARRAY['Cannot advertise guaranteed pass rates or outcomes','Cannot offer incentives contingent on passing inspection outcome','Fee advertising must reflect state-mandated maximum or actual fee without deceptive add-ons','Cannot imply that emissions equipment tampering or OBD bypass is available','STAR-certified station status (CA) must only be claimed if currently certified by BAR','Must not misrepresent station authorization status or credentials in advertising']::text[])
