INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:chamber_of_handicrafts',true,'Trade Association Registration #',ARRAY['National Ministry of Trade or Industry (jurisdiction-specific)','National Ministry of Culture (where cultural heritage mandate applies)','World Crafts Council (international standards body)','UNESCO (for ICH partnership obligations)','National Intellectual Property Office (for collective mark and GI guidance)','National Labor Standards Authority (for apprenticeship program compliance)']::text[],ARRAY['Guaranteed certification approval','Certified by UNESCO (unless formally designated)','Government-endorsed products (without specific official backing)','Official handmade guarantee (without inspection evidence)','Best artisan products in the country','All craft businesses automatically qualify for grants']::text[],ARRAY['Certification is subject to product inspection and quality standards assessment','Grant assistance does not guarantee funding approval; the chamber facilitates applications only','Apprenticeship programs are subject to national labor law compliance requirements','Intellectual property guidance is advisory; members should consult a qualified IP attorney for legal advice','Chamber membership does not constitute an endorsement of individual artisan products without certification','Heritage designation claims must reference the specific recognized authority granting the designation']::text[],false,false,true,ARRAY['Must not claim government agency status unless formally constituted as one','Must not guarantee export success or market access outcomes','Must not misrepresent UNESCO or World Crafts Council affiliation beyond formally documented scope','Funding and grant advertising must include disclaimer that assistance is facilitative not guaranteed','Certification mark usage in advertising must be limited to currently valid certified products only','Must not use member testimonials implying universal outcomes']::text[])
