INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:chemical_exporter',true,'BIS Export License # / ITAR Registration # / EPA TSCA Registration #',ARRAY['Bureau of Industry and Security BIS — Export Administration Regulations EAR','Directorate of Defense Trade Controls DDTC — ITAR','Environmental Protection Agency EPA — TSCA Toxic Substances Control Act','Occupational Safety and Health Administration OSHA — Hazard Communication Standard 29 CFR 1910.1200','International Air Transport Association IATA — Dangerous Goods Regulations','International Maritime Organization IMO — IMDG Code','European Chemicals Agency ECHA — EU REACH Regulation EC 1907 2006','United Nations Committee of Experts on the Transport of Dangerous Goods — UN Model Regulations']::text[],ARRAY['100% safe for all environments','guaranteed customs clearance','no export license required','fully exempt from EAR controls','REACH pre-approved','TSCA exempt for all applications','no hazardous properties','compliant in all jurisdictions without verification']::text[],ARRAY['Export of controlled chemicals is subject to US Export Administration Regulations and may require a license from the Bureau of Industry and Security','ITAR-controlled dual-use chemicals require State Department registration and export authorization','All chemical shipments must comply with IATA Dangerous Goods Regulations for air freight or IMDG Code for sea freight','REACH compliance obligations apply to importers and manufacturers placing chemicals on the EU market; consult your regulatory representative','Safety Data Sheets must be prepared in accordance with OSHA 29 CFR 1910.1200 and GHS requirements','EPA TSCA pre-manufacture or significant new use notifications may be required for new chemical substances','All export classifications are subject to change; customers are responsible for confirming ECCN and licensing requirements at time of shipment']::text[],false,false,true,ARRAY['May not claim exemption from export control classifications without verified ECCN screening','May not advertise guaranteed customs clearance or duty-free status without customs authority confirmation','Must not misrepresent REACH or TSCA registration status in marketing materials','Cannot advertise dual-use chemical availability to embargoed countries or denied parties','Trade finance advertising must comply with applicable banking and anti-money-laundering regulations']::text[])
