INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:chemical_wholesaler',true,'DOT Hazmat Safety Permit # / EPA Import ID # / FDA Facility Registration #',ARRAY['U.S. Department of Transportation (DOT) — Pipeline and Hazardous Materials Safety Administration (PHMSA)','U.S. Environmental Protection Agency (EPA) — TSCA and RCRA programs','U.S. Occupational Safety and Health Administration (OSHA) — Hazard Communication Standard 29 CFR 1910.1200','U.S. Food and Drug Administration (FDA) — facility registration for food/pharma-grade chemicals','State Fire Marshal offices — flammable and oxidizer storage permits','IATA Dangerous Goods Board — air freight of dangerous goods','International Maritime Organization (IMO) — IMDG Code for sea freight']::text[],ARRAY['guaranteed lowest chemical prices','approved for all uses','safe to handle without PPE','no special storage required','fully OSHA compliant for all chemicals','all chemicals are non-hazardous','we handle any waste stream','same as pharmaceutical grade']::text[],ARRAY['All chemical products are sold for industrial and commercial use only; end-user is responsible for verifying suitability for specific application.','Safety Data Sheets (SDS) are provided with every shipment in compliance with OSHA 29 CFR 1910.1200; buyers are responsible for training workers on chemical hazards.','Transportation of hazardous materials is conducted in compliance with DOT 49 CFR Parts 171-180; customers must comply with applicable receiving site regulations.','TSCA-regulated substances are imported and distributed in compliance with EPA requirements; customers must confirm their own TSCA compliance obligations.','FDA-registered food-grade or pharmaceutical-grade chemicals require end-user verification of compliance with applicable FDA regulations.','Storage of chemicals at customer facilities is subject to local fire marshal, OSHA, and EPA requirements; consult facility EHS officer before accepting delivery.']::text[],false,false,false,ARRAY['Cannot claim a chemical is approved by FDA, EPA, or OSHA for a specific use without documented regulatory basis','Cannot advertise hazardous chemicals without including relevant safety handling language','Cannot claim DOT compliance for the customer''s facility — compliance applies to distributor''s transport operations only','Cannot use the term ''pharmaceutical grade'' or ''food grade'' without verifiable COA and regulatory registration backing the claim','Cannot advertise disposal services for RCRA hazardous waste without a valid EPA hazardous waste transporter ID','Must not represent spot market availability as guaranteed stock without current inventory verification']::text[])
