INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:chinese_medicine_clinic',true,'State Acupuncture License #',ARRAY['National Certification Commission for Acupuncture and Oriental Medicine (NCCAOM)','State Medical Board or State Acupuncture Board (jurisdiction-specific)','Council of Colleges of Acupuncture and Oriental Medicine (CCAOM) — CNT standards','Accreditation Commission for Acupuncture and Oriental Medicine (ACAOM)','U.S. Food and Drug Administration (FDA) — herbal supplement regulations','U.S. Department of Health and Human Services — HIPAA enforcement']::text[],ARRAY['cures cancer','treats or cures any disease','guaranteed results','FDA-approved treatment','eliminates [disease]','permanent cure','medically proven to treat','replaces your doctor']::text[],ARRAY['Acupuncture and herbal medicine are complementary therapies and do not replace diagnosis or treatment by a licensed medical physician.','Herbal supplement recommendations are not intended to diagnose, treat, cure, or prevent any disease, per FDA dietary supplement regulations.','Results vary. Individual outcomes from acupuncture or herbal medicine are not guaranteed.','This clinic complies with HIPAA. Your health information is protected and will not be shared without your written consent.','Informed consent is required prior to initiating any treatment. Please review and sign your intake forms before your first session.','State acupuncture license number is available upon request and on file with the state licensing board.']::text[],false,true,false,ARRAY['Cannot claim acupuncture or herbal medicine treats, cures, or prevents specific diseases per FTC and FDA guidelines','Cannot use patient testimonials that imply guaranteed outcomes or typical results without appropriate disclaimers','Fertility acupuncture marketing must not promise pregnancy or IVF success rate improvements without evidence-based qualified language','Oncology acupuncture advertising must include disclaimer that it is supportive/complementary care only, not cancer treatment','Herbal product marketing must comply with FDA dietary supplement labeling and advertising rules (no disease claims)','Before-and-after images for cosmetic acupuncture must be accompanied by disclosure that results vary']::text[])
