INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:civil_law_attorney',true,'State Bar License #',ARRAY['State Bar Association (jurisdiction-specific)','American Bar Association (Model Rules of Professional Conduct)','State Supreme Court (attorney discipline authority)']::text[],ARRAY['guaranteed results','we always win','best lawyer in [state]','no fees ever','we guarantee a settlement','results guaranteed','certified specialist (without actual board certification)','free legal advice (when only consultation is free)']::text[],ARRAY['Past results do not guarantee a future outcome','This website is for informational purposes only and does not constitute legal advice','Attorney advertising — prior results do not guarantee a similar outcome','Contingency fee arrangements are subject to a written fee agreement','No attorney-client relationship is formed without a signed engagement agreement']::text[],false,false,false,ARRAY['State bar advertising rules prohibit false or misleading statements about attorney qualifications or case outcomes','Testimonials and endorsements must comply with state bar rules and include required disclaimers','Attorney must not claim specialization unless board-certified by a recognized authority','AV Preeminent and Super Lawyers designations must be accurately represented per their respective usage policies','Contingency fee advertising must disclose that client may be responsible for costs even if no recovery']::text[])
