INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:clothes_market',true,'Market Operator License # / Municipal Vendor Permit #',ARRAY['Local Municipal Authority / City or County Business Licensing Office','State Department of Revenue (Sales Tax Compliance)','Federal Trade Commission (FTC Fiber Content and Care Labeling Rules)','Local Health and Safety Authority (Open-Air Market Regulations)']::text[],ARRAY['Guaranteed lowest prices in the city','All items are authentic designer goods','All secondhand items are certified clean and sanitized','No returns ever under any circumstances','Tax-free shopping']::text[],ARRAY['All new garments sold must comply with FTC fiber content and care instruction labeling requirements','Vendors are responsible for collecting and remitting applicable state and local sales tax on retail transactions','Return and exchange policies vary by individual vendor stall — shoppers should confirm policies before purchase','This market operates under a valid municipal vendor permit and market operator license issued by the local authority','Health and safety conditions for open-air market operations are maintained in accordance with local authority standards']::text[],false,false,false,ARRAY['Must not claim exclusive authenticity of designer or branded secondhand goods without verification','Must not advertise prices as tax-free if sales tax is legally applicable','Must not use health or safety superlatives (e.g. ''the cleanest market'') without documented certification','Vendor booth rental advertising must clearly state any pitch fees, conditions, or minimum trading commitments']::text[])
