INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:community_health_center',true,'HRSA Section 330 Grant # | State Health Facility License #',ARRAY['Health Resources and Services Administration (HRSA)','U.S. Department of Health and Human Services Office of Inspector General (OIG)','Substance Abuse and Mental Health Services Administration (SAMHSA)','Centers for Medicare and Medicaid Services (CMS)','State Department of Health','Drug Enforcement Administration (DEA) for MAT prescribers','Health Resources and Services Administration 340B Program']::text[],ARRAY['guaranteed cure','best doctors in the city','free healthcare for everyone','no cost for all services','we treat emergencies','accept all insurance unconditionally','HIPAA-free zone','experimental treatments available without consent']::text[],ARRAY['Sliding fee scale discounts are based on household income and family size. Proof of income may be required. No patient is turned away due to inability to pay.','This health center is a HIPAA-covered entity. All patient health information is protected under the HIPAA Privacy and Security Rules.','This health center receives federal funding under Section 330 of the Public Health Service Act and is subject to HRSA Health Center Program requirements.','Federal Tort Claims Act (FTCA) malpractice coverage applies to this health center and its covered employees and contractors as deemed by HRSA.','340B Drug Pricing Program: Discounted medications are available to eligible patients. 340B pricing is subject to federal eligibility requirements and cannot be combined with all payer types.','This facility is licensed by the State Department of Health and subject to state inspection and compliance standards.']::text[],false,true,true,ARRAY['Cannot advertise specific prescription medications in ways that imply 340B discounts are universally available to all payers','Cannot claim FTCA coverage extends to non-deemed contractors or volunteers without verification','Cannot imply services are free for all patients — sliding fee scale eligibility is income-based','Cannot use Joint Commission or NCQA logos without current, active accreditation status','Cannot advertise FQHC status without current HRSA designation; Look-Alike designation must be clearly distinguished from full FQHC status','MAT and buprenorphine advertising must comply with DEA and SAMHSA prescribing regulations and cannot guarantee treatment outcomes','Cannot imply Medicaid enrollment assistance guarantees coverage approval']::text[])
