INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:countertop_contractor',true,'State Contractor License #',ARRAY['State Contractor Licensing Board (jurisdiction-specific, e.g., CSLB in California, DPOR in Virginia)','U.S. Environmental Protection Agency (EPA) — Lead Renovation, Repair and Painting (RRP) Rule','OSHA — Occupational Safety and Health Administration (silica dust and job site safety)','Local Building and Permitting Authorities']::text[],ARRAY['guaranteed lowest price','licensed in all states','no permit required','completely safe silica-free fabrication','EPA certified (without specifying lead-safe RRP credential)','we beat any competitor quote']::text[],ARRAY['Contractor licensing requirements vary by state. Verify current license status with your state licensing board before contracting.','EPA Lead-Safe Certification is required when performing renovation work in homes, child care facilities, or schools built before 1978.','Stone fabrication operations that disturb silica-containing materials must comply with OSHA 29 CFR 1926.1153 silica dust exposure standards.','Local building permits may be required for countertop projects involving structural cabinet or plumbing modifications. Check with your local jurisdiction.','Stone waste and slab offcuts must be disposed of in accordance with local environmental and solid waste regulations.']::text[],false,false,false,ARRAY['Do not claim manufacturer certification without active verified status from the named brand','Do not advertise EPA Lead-Safe Certification without displaying valid credential ID and expiration','State contractor license number must appear on all advertising materials in jurisdictions that require it (e.g., California, Florida, Virginia)','OSHA certifications must not be presented as government endorsements of the business','BBB rating and accreditation must reflect current verified status only']::text[])
