INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:crane_service',true,'State Contractor License # | NCCCO Operator ID #',ARRAY['Occupational Safety and Health Administration (OSHA) — 29 CFR 1926.1400','National Commission for the Certification of Crane Operators (NCCCO)','American Society of Mechanical Engineers (ASME) — B30.5 Standard','State Contractor Licensing Boards (jurisdiction-specific)','Local Department of Transportation (road closure and pick permits)']::text[],ARRAY['guaranteed safe lift','OSHA approved','fully OSHA certified company','risk-free crane operation','no lift is too dangerous','we never have accidents','ASME certified crane service','government certified']::text[],ARRAY['All crane operations are performed in accordance with OSHA 29 CFR 1926.1400 and ASME B30.5 standards.','Crane operators hold current NCCCO certification; credentials available upon request.','Critical lifts require an engineered lift plan; consult our team prior to scheduling.','Load capacities shown are maximum rated; actual capacity depends on boom length, radius, and configuration per load chart.','All road closure and over-public-area picks require applicable local permits; lead times vary by jurisdiction.','Insurance certificates including general liability and riggers liability available upon request for contractor prequalification.']::text[],false,false,false,ARRAY['Do not claim OSHA certification of the company (only individuals hold OSHA cards)','Do not advertise specific rated capacities without referencing load chart and configuration conditions','Do not guarantee permit approval timelines as these are controlled by third-party authorities','Do not use ''ASME certified'' as a company-level claim — ASME issues standards not company certifications','Avoid absolute safety claims that cannot be substantiated per FTC guidelines']::text[])
