INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:credit_counseling_service',true,'State Credit Counseling Agency License #',ARRAY['Federal Trade Commission (FTC) — Credit Repair Organizations Act and Telemarketing Sales Rule enforcement','U.S. Department of Housing and Urban Development (HUD) — Housing Counseling Program approval and oversight','National Foundation for Credit Counseling (NFCC) — member agency standards and ethics','State financial regulatory agencies (varies by state; e.g., state banking department or attorney general consumer protection division)','IRS — 501(c)(3) nonprofit tax-exempt status requirements']::text[],ARRAY['We can repair your credit','Guaranteed results','We will eliminate your debt','Remove accurate negative information from your credit report','Credit score improvement guaranteed','We can stop all collection calls immediately','Debt forgiveness guaranteed','No fees ever']::text[],ARRAY['Credit counseling services do not guarantee creditor participation in any debt management plan.','Enrollment in a debt management plan may affect your ability to obtain new credit during the plan period.','This agency is a nonprofit organization. Fees, if any, are disclosed in advance and are based on ability to pay.','Housing counseling services are provided through HUD-approved agencies. HUD approval does not constitute government endorsement of the agency''s views or activities.','This agency is not a credit repair organization and does not promise to improve your credit score.','Bankruptcy counseling services meet federal requirements under 11 U.S.C. § 111 for pre-filing counseling and debtor education.']::text[],false,false,true,ARRAY['Cannot charge advance fees before services are rendered under FTC Telemarketing Sales Rule','Cannot claim to be a government agency or imply government endorsement','Cannot guarantee specific credit score improvements or debt elimination outcomes','Cannot use deceptive pricing that obscures mandatory fees','Must disclose nonprofit status in advertising if tax-exempt status is used as a marketing claim','HUD-approved agencies must comply with HUD fair housing and nondiscrimination advertising requirements']::text[])
