INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:creperie',true,'Food Service Permit # / Health Department License #',ARRAY['Local County or Municipal Health Department','State Department of Health — Food Safety Division','Local Fire Marshal (for open-flame tableside flambé permit)','OSHA (general food service workplace safety)','ADA — Americans with Disabilities Act (customer-facing area compliance)']::text[],ARRAY['100% allergen-free','Completely safe for all allergies','Certified gluten-free kitchen','No risk of cross-contamination','Our Nutella crepes contain no allergens']::text[],ARRAY['This establishment handles gluten, dairy, eggs, and tree nuts including Nutella which contains hazelnuts. Guests with allergies should inform staff before ordering.','Tableside flambé service involves an open flame. Please notify staff of any concerns.','Gluten-free crepe options are prepared with buckwheat flour; however, cross-contact with gluten-containing ingredients may occur in shared kitchen environments.','Food handler certifications are maintained by all staff in compliance with local health department requirements.','Menu items and seasonal specials are subject to change based on ingredient availability.']::text[],false,false,false,ARRAY['Must not claim absolute allergen-free status without certified dedicated kitchen','Flambé service must not be advertised without confirming open-flame permit is current','Gluten-free claims must be qualified with cross-contamination disclosure','Health inspection grade must reflect current posted grade and not be misrepresented','Seasonal specials must be clearly marked as limited availability to avoid bait-and-switch claims']::text[])
