INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:cuban_restaurant',true,'State Food Service Establishment License #',ARRAY['Florida Department of Business and Professional Regulation — Division of Hotels and Restaurants','Florida Division of Alcoholic Beverages and Tobacco','State and Local Health Department — Food Establishment Inspection Program','U.S. Department of Justice — ADA Compliance for Public Accommodations']::text[],ARRAY['guaranteed food safety','state-approved recipes','health department approved menu','licensed to serve any alcohol without restriction','certified organic without verified certification','award-winning without documented award','best Cuban restaurant in the country without verified ranking']::text[],ARRAY['Food service establishment licensed and inspected by the Florida Department of Business and Professional Regulation','Alcohol service requires valid state liquor license; management reserves the right to request ID','Health inspection grade posted as required by local ordinance','Sales tax applied to all food and beverage sales per Florida law','ADA-accessible seating and facilities available; contact us for specific accommodation needs']::text[],true,false,false,ARRAY['Alcohol advertising must comply with Florida Statutes Chapter 561 and ABT regulations','No implied health claims about food without substantiation','Live music events subject to local noise ordinance and entertainment permit requirements','Catering contracts must include itemized pricing and deposit terms per Florida consumer protection guidelines']::text[])
