INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:cupcake_shop',true,'State Food Establishment License #',ARRAY['State Department of Agriculture or Department of Health (varies by state)','County or Municipal Health Department','FDA (Food Allergen Labeling and Consumer Protection Act)','National Restaurant Association Educational Foundation (ServSafe)']::text[],ARRAY['certified organic (without USDA certification)','allergen-free (absolute claim — must say ''allergen-friendly'' or name specific allergens avoided)','guaranteed safe for all allergies','no risk of cross-contamination','approved by the FDA','dietitian-recommended','medically safe for celiacs']::text[],ARRAY['Products are prepared in a facility that also processes common allergens including gluten, nuts, dairy, and eggs.','Gluten-free items are prepared with dedicated equipment but are not produced in a certified gluten-free facility.','Custom order deposits are non-refundable after order confirmation.','Sales tax is applied to all food item purchases in accordance with state regulations.']::text[],false,false,false,ARRAY['Cannot claim ''certified gluten-free'' without third-party facility certification','Cannot use ''organic'' in product names without USDA Organic certification','Must disclose major allergens on all in-store and online menus per FDA guidelines','Cottage food operations face state-specific advertising and sales channel restrictions','Sales tax disclosure required on all pricing if shown publicly']::text[])
