INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:customs_broker',true,'CBP Customs Broker License # (19 CFR Part 111)',ARRAY['U.S. Customs and Border Protection (CBP) — Title 19 USC and 19 CFR Part 111','Office of Foreign Assets Control (OFAC) — sanctions screening obligations','Bureau of Industry and Security (BIS) — Export Administration Regulations (EAR) for dual-use goods','FDA — Prior Notice requirements for food, drug, and device imports','USDA APHIS — import permits and phytosanitary certificate requirements','FinCEN — Anti-Money Laundering obligations for broker trust accounts']::text[],ARRAY['Guaranteed customs clearance','We guarantee no CBP inspections','Duty-free guaranteed','Lowest duties guaranteed','We can clear anything through customs','CBP-approved broker (implies exclusive endorsement)']::text[],ARRAY['CBP customs broker license number must be displayed; individual broker license required under 19 CFR Part 111','Customs brokerage services do not constitute legal advice; clients with penalty or enforcement matters should consult a licensed customs attorney','OFAC sanctions screening is the importer''s legal obligation; broker-facilitated screening does not transfer legal liability','Duty rates are subject to change by Presidential proclamation, CBP ruling, or Congressional action; quoted rates are estimates only','ISF penalties of up to $5,000 per violation may be assessed by CBP for late or inaccurate filings','Antidumping and countervailing duty deposits are subject to annual administrative review and may result in retroactive assessment above deposit rates']::text[],false,false,true,ARRAY['Must not claim exclusive or preferred status with CBP or any government agency','Must not guarantee specific duty rates, clearance times, or CBP examination outcomes','Must not use testimonials that imply guaranteed results in customs enforcement matters','Must comply with FTC endorsement guidelines for any client testimonials or case studies published','AML-regulated trust accounts must not be advertised in ways that suggest asset protection or financial advisory services']::text[])
