INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:daihatsu_dealer',true,'State Motor Vehicle Dealer License #',ARRAY['State Department of Motor Vehicles (jurisdiction-specific)','Federal Trade Commission (FTC) — Used Car Rule and TILA','National Highway Traffic Safety Administration (NHTSA) — recall compliance','State Attorney General — Lemon Law enforcement']::text[],ARRAY['guaranteed financing regardless of credit','no lemon vehicles','better than MSRP','factory-direct pricing','certified by Daihatsu (without active franchise authorization)','as-is with full warranty']::text[],ARRAY['FTC Buyers Guide must be displayed on all used vehicles offered for sale','Truth-in-Lending Act (TILA) disclosures required on all financing agreements','Lemon Law rights disclosure required per applicable jurisdiction','All advertised prices exclude taxes, title, license, and dealer fees unless stated','Emissions compliance certification required for all vehicles sold where mandated','Customer financial data handled under applicable data privacy regulations']::text[],false,false,true,ARRAY['APR and financing terms must comply with TILA Regulation Z disclosure requirements','Used vehicle ads must include FTC Buyers Guide availability notice','No bait-and-switch pricing — advertised vehicles must be available at stated price','Certified Pre-Owned claims must reflect actual manufacturer or dealer CPO program criteria','Fuel economy or emissions claims must reference official test results where applicable']::text[])
