INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:department_of_transportation',true,'State Transportation Agency Authorization — [State] Code § [XX]',ARRAY['Federal Highway Administration (FHWA)','Federal Motor Carrier Safety Administration (FMCSA)','Federal Transit Administration (FTA)','U.S. Department of Transportation (USDOT)','State Legislature (Motor Vehicle Code Authority)','Office of Inspector General — USDOT']::text[],ARRAY['guaranteed approval for commercial permits','fastest DMV in the state','we can waive your reinstatement fee','no wait times guaranteed','we process faster than federal law requires','license issued same day guaranteed']::text[],ARRAY['Fees and requirements are set by state statute and subject to change without notice.','This office complies with Title VI of the Civil Rights Act of 1964; discrimination complaints may be filed with FHWA Office of Civil Rights.','NEPA environmental reviews are subject to federal timelines and interagency coordination requirements.','ADA accommodations are available upon request at all public facilities.','Commercial vehicle permit conditions are governed by applicable state and federal law including FMCSA regulations.','Driver license and vehicle registration information is protected under state motor vehicle records privacy law (DPPA).']::text[],false,false,false,ARRAY['May not imply faster processing than mandated statutory or regulatory timelines','May not advertise fee waivers not authorized by statute','Must include non-discrimination notice (Title VI) in all public-facing program materials','FHWA-funded program materials must include required federal funding acknowledgment language','Cannot use federal funds for political advertising or partisan content','All public notices for NEPA projects must meet Federal Register and state notice requirements']::text[])
