INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:domestic_airport',true,'FAA Airport Operating Certificate #',ARRAY['Federal Aviation Administration (FAA)','Transportation Security Administration (TSA)','U.S. Customs and Border Protection (CBP)','U.S. Department of Transportation (DOT)','Occupational Safety and Health Administration (OSHA)','Americans with Disabilities Act – DOT Title II Enforcement','Environmental Protection Agency (EPA) – aircraft noise and emissions','State Aviation Authority (jurisdiction-specific)']::text[],ARRAY['guaranteed on-time flights','100% security guaranteed','safest airport in America','no wait times at security','approved by TSA','government-endorsed parking','fully ADA compliant with no exceptions','risk-free travel']::text[],ARRAY['Flight schedules and gate assignments are subject to change by operating airlines without notice.','TSA security wait times are estimates only and may vary significantly by date and time.','Parking availability is not guaranteed; reservations recommended during peak travel periods.','Accessibility accommodation requests should be made at least 48 hours in advance through your airline.','Passenger facility charges are regulated by the FAA and included in airline ticket prices.','Airport operations are subject to FAA, TSA, and DOT regulatory requirements which supersede any airport-published information.']::text[],false,false,false,ARRAY['Must not imply government endorsement of commercial concessions or parking vendors','Must not claim security superiority over other airports without verifiable FAA/TSA data','Must not advertise specific airline schedules as guaranteed without airline authorization','Must comply with FAA grant assurances prohibiting unjust discrimination in advertising','Environmental claims (e.g. carbon neutral) must be substantiated under FTC Green Guides','Must not use TSA, CBP, or FAA logos or seals without explicit agency authorization']::text[])
