INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:donut_shop',true,'Food Establishment Permit #',ARRAY['State Department of Agriculture or State Food Safety Division','Local Health Department','U.S. Food and Drug Administration (FDA) — allergen labeling','Local Zoning and Planning Department','Local Wastewater or Environmental Compliance Authority']::text[],ARRAY['100% allergen-free','guaranteed safe for all allergies','no risk of cross-contamination','certified organic (without valid certification)','made in a nut-free facility (without verified certification)','approved by the FDA']::text[],ARRAY['Menu items may contain or come into contact with common allergens including wheat, dairy, eggs, soy, tree nuts, and peanuts. Please inform staff of dietary restrictions.','Gluten-free options are prepared in a shared kitchen environment. Not recommended for those with celiac disease unless cross-contact protocols are confirmed.','Health inspection scores are posted on-site as required by local law.','Custom and bulk order lead times apply. Contact us for availability.']::text[],false,false,false,ARRAY['Must not make unsubstantiated health claims about any donut product','Must not claim products are allergen-free without documented protocols','Must comply with FTC guidelines on endorsements and testimonials in social media marketing','Must not use the term ''certified organic'' without valid USDA certification','Nutritional claims must comply with FDA labeling standards if printed on packaging']::text[])
