INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:dressmaker',true,'Local Business License #',ARRAY['State and Local Business Licensing Authority','FTC (Federal Trade Commission) — Textile Fiber Products Identification Act','State Consumer Protection Offices (deposit and refund policy enforcement)','ADA — Americans with Disabilities Act (studio accessibility where applicable)']::text[],ARRAY['guaranteed perfect fit on first try','couture quality at boutique prices','we replicate any designer dress exactly','all deposits fully refundable','certified by Paris fashion houses','FDA approved materials']::text[],ARRAY['Custom garments require multiple fittings; final fit cannot be guaranteed until all scheduled fittings are completed.','Deposits are non-refundable once fabric has been cut or ordered, per the studio''s stated refund policy.','Fabric availability and dye lots may vary; swatches provided at consultation are approximate.','Custom timelines are estimates; rush fees apply for expedited construction requests.','All textile fiber content is disclosed on garment labels in compliance with FTC Textile Fiber Products Identification Act.']::text[],false,false,false,ARRAY['Must not use the term ''couture'' unless techniques meet legitimate haute couture construction standards','Must not claim to be an official representative of any named fashion house or designer','Deposit and refund policies must be clearly disclosed in writing before any payment is accepted','FTC Textile Fiber Products Identification Act requires fiber content labeling on all finished garments sold','Consumer protection laws require written contracts for custom garment commissions above applicable state thresholds']::text[])
