INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:drive_in_movie_theater',true,'State Amusement & Entertainment License #',ARRAY['State Department of Revenue / Business Licensing Division','Local Municipal Zoning and Planning Authority','State or County Health Department (Food Service Permits)','Motion Picture Association (MPAA) Film Licensing','Local Fire Marshal / Office of Emergency Management','U.S. Department of Justice (ADA Compliance)']::text[],ARRAY['unlimited movies for free','no permits required','exempt from noise ordinances','ADA not required for outdoor venues','unrestricted outdoor broadcast','MPAA license not needed for drive-ins']::text[],ARRAY['Film screenings are subject to MPAA licensing agreements and distributor availability.','Showtimes are dusk-dependent and subject to change due to weather or technical issues.','All food and beverage operations are conducted under valid county food handler permits.','Patrons are responsible for ensuring their vehicle audio system can receive FM broadcasts; rental units available.','ADA-accessible restrooms, viewing areas, and parking are available on site in compliance with applicable regulations.','Noise levels are managed in compliance with local ordinances; FM broadcast is the primary audio delivery method.']::text[],false,false,false,ARRAY['Do not advertise specific film titles without confirming active MPAA distribution license for current engagement.','Do not guarantee first-run exclusivity without distributor confirmation.','Food and concession promotions must comply with local health department advertising guidelines.','Event capacity claims must not exceed fire marshal-approved maximum occupancy.','Alcohol sales (if offered) must comply with state liquor authority advertising restrictions.']::text[])
