INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:electronics_repair_shop',true,'State Business License #',ARRAY['U.S. Federal Trade Commission (FTC) — Right to Repair guidance','California Bureau of Electronic and Appliance Repair (BEAR) — state repair shop licensing','U.S. Environmental Protection Agency (EPA) — e-waste and hazardous materials disposal','Federal Communications Commission (FCC) — device modification and RF compliance','Apple Inc. AASP Program Compliance — authorized service terms','Samsung Authorized Service Program Compliance']::text[],ARRAY['We permanently fix all devices','100% data recovery guaranteed','Repair will not affect your manufacturer warranty','We are Apple-certified (if AASP not held)','Cheaper than the Apple Store (without substantiation)','Government-certified repair shop']::text[],ARRAY['Third-party repair may affect manufacturer warranty; however, under the Magnuson-Moss Warranty Act, manufacturers cannot void warranties solely because of third-party repair.','Data recovery outcomes cannot be guaranteed and depend on the extent of device damage.','Aftermarket parts are not manufactured by the original device maker; OEM parts are available upon request and may affect pricing.','E-waste and replaced components are disposed of in compliance with EPA regulations. Ask for our e-waste disposal documentation.','California customers: this shop complies with SB 244 right-to-repair requirements including availability of parts and repair documentation.','FCC notice: device modifications that affect radio frequency emissions are performed only in compliance with applicable FCC regulations.']::text[],false,false,false,ARRAY['Do not claim Apple, Samsung, or Microsoft authorization without current active credential verification','Do not guarantee data recovery success rates in advertising','Do not imply manufacturer endorsement without verified authorized status','Repair warranty claims in advertising must match actual written warranty terms offered','E-waste disposal claims must be substantiated by documented recycler partnerships','Price comparisons to manufacturer repair programs must be current, accurate, and verifiable']::text[])
