INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:event_technology_service',false,NULL,ARRAY['Payment Card Industry Security Standards Council (PCI SSC) — PCI DSS','International Organization for Standardization (ISO) — ISO 27001','AICPA — SOC 2 Type II','U.S. Department of Justice — ADA Title III Digital Accessibility','European Data Protection Board (EDPB) — GDPR','California Attorney General — CCPA']::text[],ARRAY['100% secure platform','guaranteed uptime','we never share your data','HIPAA compliant event platform','fully anonymous attendee data','complete data deletion guaranteed within 24 hours']::text[],ARRAY['Attendee data collected during event registration is processed in accordance with our Privacy Policy and applicable data protection laws including GDPR and CCPA.','PCI DSS compliance applies to payment card data processed through integrated ticketing modules; scope may vary by implementation.','SOC 2 Type II certification covers our cloud infrastructure as defined in our audit scope document available upon request.','ADA accessibility compliance applies to platform features as described in our Voluntary Product Accessibility Template (VPAT); custom implementations may require additional client-side review.','Live streaming and recording of events may be subject to participant consent requirements under applicable state and federal law.']::text[],false,false,true,ARRAY['Must not claim regulatory approval from bodies that do not certify event technology platforms','Must not imply that PCI DSS certification covers all client payment processing environments without scope qualification','Must not advertise GDPR compliance as eliminating all data transfer restrictions without proper Standard Contractual Clauses disclosure','Must not claim ''government certified'' security without specifying the exact certification and issuing body','Must disclose data storage jurisdiction when advertising to EU event organizers']::text[])
