INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:faculty_of_science',true,'Regional Accreditation — [Accreditor Name] Accredited Institution',ARRAY['Higher Learning Commission (HLC)','Southern Association of Colleges and Schools Commission on Colleges (SACSCOC)','Middle States Commission on Higher Education (MSCHE)','New England Commission of Higher Education (NECHE)','National Science Foundation (NSF) — Grant Compliance','National Institutes of Health (NIH) — Grant Compliance Office','Occupational Safety and Health Administration (OSHA) — Laboratory Safety','Institutional Biosafety Committee (IBC)','Institutional Animal Care and Use Committee (IACUC)','American Chemical Society (ACS) — Approved Chemistry Programs','ABET — Engineering and Applied Science Program Accreditation']::text[],ARRAY['guaranteed admission','guaranteed job placement','highest-ranked science program','#1 in the country','cure for disease','guaranteed research funding for all students','no prerequisites required for graduate admission']::text[],ARRAY['Program outcomes vary by individual student effort, background, and field of study.','Research involving biological agents is conducted under IBC-approved protocols in accordance with federal biosafety guidelines.','Animal research is conducted under IACUC-approved protocols in compliance with the Animal Welfare Act.','Federal grant compliance is maintained in accordance with NIH Grants Policy Statement and NSF Award and Administration Guide.','Laboratory activities involving hazardous chemicals are conducted under OSHA 29 CFR 1910.1450 (Occupational Exposure to Hazardous Chemicals in Laboratories).','Accreditation status is subject to periodic review by the relevant regional accrediting body.','Tuition, fees, and financial aid are determined by the parent institution and are subject to change.']::text[],false,false,false,ARRAY['Must not claim accreditation status not currently held or under review','Must not guarantee employment outcomes or specific salary ranges for graduates','Must not misrepresent research rankings or publication counts','Federal grant acknowledgment required in all publications and communications citing NSF or NIH supported work','Must not imply government endorsement of research findings beyond the grant award itself','Marketing materials must accurately reflect program availability and current enrollment status']::text[])
