INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:fire_protection_consultant',true,'State PE License # (Fire Protection Engineering)',ARRAY['State Boards of Professional Engineers and Land Surveyors (jurisdiction-specific)','National Council of Examiners for Engineering and Surveying (NCEES)','NFPA (National Fire Protection Association) — CFPS credentialing','NICET (National Institute for Certification in Engineering Technologies)','International Code Council (ICC) — plans examiner and fire inspector credentials','OSHA — 29 CFR 1910.38 emergency action plan compliance','Authority Having Jurisdiction (AHJ) — local fire marshal and building official']::text[],ARRAY['guarantees code approval','AHJ will approve','eliminates all fire risk','fully fire-proof','certified to eliminate liability','approved by the fire marshal']::text[],ARRAY['PE-stamped documents required by law in applicable states — confirm requirements with your state engineering board before construction submission.','Fire protection consulting does not substitute for required permits, inspections, or approvals from the Authority Having Jurisdiction.','Performance-based design alternatives require AHJ acceptance and may require third-party peer review under applicable codes.','Expert witness services do not constitute legal advice; retain qualified legal counsel for all litigation matters.','OSHA emergency action plan requirements may vary; consult applicable 29 CFR standards and state-plan state rules.']::text[],false,false,false,ARRAY['Do not claim PE licensure in states where the individual is not currently licensed','Do not imply guaranteed plan approval outcomes from AHJ','Do not advertise specific insurance premium savings amounts without documented case data','Do not market fire investigation services as producing predetermined cause determinations','SFPE and NFPA designations must be used in accordance with respective organization''s member advertising guidelines']::text[])
