INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:fire_protection_equipment_supplier',true,'State Fire Marshal Supplier Approval #',ARRAY['State Fire Marshal Offices (jurisdiction-specific)','Occupational Safety and Health Administration (OSHA)','National Fire Protection Association (NFPA) — standards authority','U.S. Environmental Protection Agency (EPA) SNAP Program','U.S. Department of Transportation (DOT) — compressed gas cylinder transport','Underwriters Laboratories (UL) — product listing authority']::text[],ARRAY['guaranteed to pass fire inspection','eliminates all fire risk','approved by all fire marshals','certified fire protection service','we install and service all systems','legally compliant in all jurisdictions','halon-equivalent performance guaranteed','replaces required sprinkler systems']::text[],ARRAY['Products sold are for installation and service by licensed fire protection contractors where required by local jurisdiction.','UL Listed designations apply to specific product models as listed on UL.com — verify listing status before purchase.','Compliance with NFPA 10, OSHA 29 CFR 1910.157, and state fire marshal requirements is the responsibility of the purchasing contractor or facility owner.','EPA SNAP program compliance for halon alternatives must be verified per specific application and jurisdiction.','DOT regulations apply to transport of compressed gas cylinders — buyer is responsible for compliance with 49 CFR requirements.','Foam concentrates containing PFAS may be subject to state and federal environmental regulations — consult applicable law before purchase.']::text[],false,false,false,ARRAY['Cannot claim products will guarantee passing a fire inspection','Cannot imply distributor authorization equals installation or service licensing','Cannot advertise halon (CFC-based) products for new system use in violation of EPA Clean Air Act','Must not claim UL listing for products not individually verified on UL product iQ database','Cannot imply OSHA compliance is achieved solely through product purchase without proper installation and maintenance','Foam concentrate advertising must disclose PFAS content or PFAS-free status where required by state law']::text[])
