INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:firearms_academy',true,'State Firearms Instructor License #',ARRAY['Bureau of Alcohol, Tobacco, Firearms and Explosives (ATF)','State Attorney General or State Police (CCW permit course approval authority, jurisdiction-specific)','National Rifle Association (NRA) — Instructor and Training Counselor certification standards','USCCA (United States Concealed Carry Association) — Instructor certification requirements','Occupational Safety and Health Administration (OSHA) — range safety for commercial facilities','Americans with Disabilities Act (ADA) — facility accessibility requirements']::text[],ARRAY['guaranteed to pass your CCW exam','100% safe — no accidents ever','we teach you how to shoot to kill','our training makes you immune from prosecution','fully legal to carry anywhere after this course','we guarantee state approval of your application']::text[],ARRAY['This course does not guarantee issuance of a concealed carry permit. Permit approval is at the sole discretion of the issuing state authority.','Students must meet all state eligibility requirements including background check clearance prior to permit application.','Firearms training involves inherent risks. All participants must comply with range safety rules at all times.','This academy does not provide legal advice. Consult a licensed attorney for questions about use-of-force laws in your jurisdiction.','Youth program participants must meet minimum age requirements and have written parental or guardian consent.','ATF regulations prohibit certain persons from possessing firearms. It is the student''s responsibility to confirm legal eligibility before enrolling.']::text[],true,false,false,ARRAY['Cannot advertise guaranteed CCW permit issuance outcomes','Cannot make claims implying immunity from criminal prosecution after training','Must not use imagery or copy that glorifies offensive or unlawful use of firearms','NRA and USCCA trademarks and branding may only be used by currently credentialed affiliated instructors','Cannot advertise services to prohibited persons under 18 U.S.C. § 922','State-specific CCW advertising requirements may apply — verify with state issuing authority before running ads']::text[])
