INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:free_parking_lot',true,'Municipal Lot Operator License #',ARRAY['Local Municipal Zoning and Planning Authority','Local Fire Marshal / Fire Prevention Bureau','U.S. Access Board (ADA Standards for Accessible Design)','State Environmental Agency / EPA NPDES Stormwater Program']::text[],ARRAY['guaranteed spot available','always open 24/7','fully ADA compliant without verification','no towing ever','unlimited overnight parking always permitted','zero liability for vehicle damage','safest lot in the city']::text[],ARRAY['Parking availability may vary during peak hours and special events','ADA stall use requires a valid accessible parking placard or plate','Overnight parking allowance subject to municipal code and posted signage','This facility complies with ADA Standards for Accessible Design; report accessibility concerns to lot management','Towing enforced for unauthorized vehicles; contact posted tow company for retrieval','Fire lanes must remain clear at all times per local fire codes; violation subject to tow and fine']::text[],false,false,false,ARRAY['Do not advertise guaranteed parking availability during event periods without real-time data','Do not use ''free'' to imply unlimited duration without disclosing any posted time limits','ADA claims must reflect current verified stall count and signage — do not overstate accessibility features','Snow removal and winter maintenance claims must reflect seasonal service availability only','Security claims (cameras, lighting) must reflect actual installed infrastructure — do not imply 24/7 monitoring without verification']::text[])
