INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:fried_chicken_takeaway',true,'Food Service Permit #',ARRAY['Local Health Department (jurisdiction-specific)','FDA (Food and Drug Administration) — menu labelling and food temperature safety','State Food Safety Regulatory Authority — food handler certification','Local Fire Marshal and Building Department — grease trap and ventilation compliance']::text[],ARRAY['Healthiest fried chicken','Certified organic (unless independently verified)','Guaranteed Grade A (without current inspection documentation)','Zero allergen risk','Completely gluten-free kitchen (without verified dedicated fryer protocol)','Better than any competitor']::text[],ARRAY['Menu items are prepared in a kitchen that handles common allergens including wheat, dairy, and eggs — customers with allergies should inform staff before ordering','Hot food items are held at or above 140°F per FDA food safety requirements','Nutrition information is available upon request and posted per applicable menu labelling regulations','Catering orders require minimum advance notice — please enquire for lead time requirements']::text[],false,false,false,ARRAY['Health claims about fried food must not imply clinical or medical benefit','Calorie or nutrition claims must match published and verified menu data','Promotional pricing must include applicable terms, expiry dates, and any minimum purchase conditions','Allergen-free claims require verified dedicated preparation protocols before use in advertising']::text[])
