INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:furniture_accessories',false,NULL,ARRAY['U.S. Consumer Product Safety Commission (CPSC)','Federal Trade Commission (FTC)','California Office of Environmental Health Hazard Assessment (OEHHA) — Proposition 65','U.S. Customs and Border Protection (CBP)']::text[],ARRAY['guaranteed non-toxic','completely safe for all children','100% flame resistant','certified organic without third-party verification','Made in USA without meeting FTC standard','no harmful chemicals']::text[],ARRAY['Soft furnishings meet applicable flammability standards per 16 CFR 1610; see product label for details.','Some products may contain chemicals known to the State of California to cause cancer or reproductive harm. For more information visit www.P65Warnings.ca.gov.','Products labeled Made in USA comply with FTC guidelines; imported products are subject to applicable customs and import duties.','Product safety information is available upon request for all carried items.']::text[],false,false,false,ARRAY['Do not claim CPSC certification without documented third-party testing','Do not use ''non-toxic'' or ''chemical-free'' without substantiated test data','Do not claim Made in USA without meeting FTC all-or-virtually-all domestic content standard','Do not omit Prop 65 warning on applicable products sold in California','Flammability claims must reference the specific standard met']::text[])
