INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:furniture_rental_service',true,'State Business License #',ARRAY['Federal Trade Commission (FTC) — Rental Purchase Agreement Rule','Consumer Financial Protection Bureau (CFPB)','State Attorneys General — Consumer Protection Divisions','State Rent-to-Own / Lease-Purchase Regulatory Agencies']::text[],ARRAY['own it now with no extra cost','zero interest financing','free ownership after payments','guaranteed lowest price rental','no fees ever','unlimited damage coverage included free']::text[],ARRAY['Rent-to-own and lease-purchase agreements are not the same as credit sales. Total cost of ownership may exceed retail price. See agreement for full terms.','This is a rental agreement, not a purchase agreement, unless expressly stated. Early buyout prices are disclosed at time of agreement.','Damage waiver is not insurance. It does not cover theft, intentional damage, or loss. See waiver terms for coverage details.','State-specific rent-to-own disclosure required prior to signing agreement per applicable state consumer protection statutes.','Truth in Lending Act / Regulation Z disclosures provided where lease-purchase agreements qualify as credit transactions.']::text[],false,false,true,ARRAY['Cannot advertise ''ownership'' without disclosing total rent-to-own cost and payment schedule','Must not imply a rental is a credit or financing arrangement unless TILA disclosures are provided','Cannot use ''no credit check'' language that implies guaranteed approval without disclosing all fees','State-specific fee cap rules must be reflected in all advertised pricing for rent-to-own programs','FTC Rule on Rental-Purchase Agreements requires clear disclosure of cash price, total rent-to-own cost, and rental payment terms in advertising']::text[])
