INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:garbage_dump',true,'State Solid Waste Facility Permit #',ARRAY['U.S. Environmental Protection Agency — RCRA Subtitle D Program','State Environmental Quality or Solid Waste Agency (jurisdiction-specific)','EPA Region Office — Clean Air Act Subpart WWW Landfill Gas Rule','State Air Quality Management District','Local Zoning and Planning Authority — Conditional Use Permit','OSHA — Occupational Safety and Health Administration']::text[],ARRAY['We accept all types of waste','Dump anything here','No restrictions on what you can bring','Guaranteed same-day disposal for all materials','We handle hazardous waste of any kind','No environmental impact from our operations']::text[],ARRAY['This facility operates under a state-issued solid waste facility permit. Permit number and expiration date available upon request.','Not all waste types are accepted. Prohibited materials include untreated medical waste, radioactive materials, and materials regulated as hazardous waste under RCRA Subtitle C.','Tipping fees are subject to change. Current rate schedules are posted at the scale house and on the facility website.','Hazardous household waste (HHW) is accepted only during scheduled drop-off events or designated HHW program hours. Quantities may be limited.','This facility is subject to EPA Subtitle D groundwater monitoring requirements. Results are available through the state environmental agency.','Landfill gas management at this facility complies with EPA Clean Air Act regulations.']::text[],false,false,false,ARRAY['Cannot claim ''zero emissions'' or ''zero environmental impact'' without verified certification','Cannot advertise acceptance of RCRA-regulated hazardous waste without a separate Subtitle C permit','Cannot imply unlimited or unrestricted commercial waste acceptance without confirming permit capacity','Must not use language implying a Superfund or remediation service without licensed authorization','Fee advertising must reflect current posted rates; no bait-and-switch rate structures']::text[])
