INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:garden_center',false,NULL,ARRAY['Animal and Plant Health Agency (APHA) — Plant Health Order enforcement','Trading Standards — Consumer Rights Act 2015 and pricing compliance','Health and Safety Executive (HSE) — REACH regulation for chemical products','Department for Environment Food and Rural Affairs (DEFRA) — Invasive Alien Species Order','Plant Healthy Certification Scheme (voluntary but industry-recognised)']::text[],ARRAY['guaranteed to grow','certified pest-free','100% safe for all wildlife','fully invasive-species-free stock']::text[],ARRAY['Certain plant species are restricted under the Invasive Alien Species (Enforcement and Permitting) Order 2019 and cannot be sold or planted in the wild','Garden chemical products are sold subject to REACH regulation compliance — always read the label before use','Plant health conditions may apply to imported species under the Plant Health Order — ask staff for provenance information','Returns are subject to the Consumer Rights Act 2015 — plants must be of satisfactory quality at point of sale','Prices displayed in store comply with Trading Standards requirements — promotional terms and conditions apply']::text[],false,false,false,ARRAY['Must not claim plants are guaranteed to survive after purchase beyond statutory rights','Must not advertise restricted invasive species for unrestricted sale','Chemical product advertising must comply with HSE and REACH labelling requirements','Pricing promotions must comply with Trading Standards guidance on misleading price indications','Environmental claims (e.g. ''eco-friendly'', ''sustainable'') must be substantiated and not misleading under CAP Code rules']::text[])
