INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:gay_sauna',true,'Adult Entertainment Licence #',ARRAY['Local Government Licensing Authority (jurisdiction-specific)','Municipal or County Health Department','Fire and Rescue Authority','LGBTQ Business Licensing Division (where applicable)']::text[],ARRAY['guaranteed safe sex','100% STI-free','no risk of infection','approved by health authorities as disease-free','fully legal with no restrictions','medical treatment available on-site','cure for HIV','FDA-approved wellness facility']::text[],ARRAY['Entry restricted to adults aged 18 years and over. Valid government-issued photo ID required.','Age verification will be conducted at entry. No exceptions.','Safe sex supplies are available on-site. Patrons are encouraged to practise safer sex.','This venue complies with all applicable adult entertainment licensing and health department regulations.','HIV and STI prevention information is available at reception. Patrons are encouraged to access regular testing.','Occupancy is subject to fire safety limits. Management reserves the right to restrict entry.','This is a private members'' venue. Management reserves the right of admission.']::text[],true,false,false,ARRAY['Must not display explicit sexual imagery in publicly visible advertising','Must not make health claims implying the venue eliminates risk of STI transmission','Must not advertise to persons under 18','Must comply with platform-specific adult content policies (Google Ads, Meta) — explicit services may be prohibited on mainstream platforms','Must include age-restriction notice in all digital advertising','Must not use language implying sexual services are for sale','Safe sex messaging must be accurate and consistent with current public health guidelines']::text[])
