INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:golf_driving_range',true,'Local Business License #',ARRAY['Municipal or County Zoning and Planning Department','Local Building and Safety Department (netting and barrier codes)','State Department of Labor (employment classification for part-time staff)','Americans with Disabilities Act (ADA) — U.S. Access Board standards']::text[],ARRAY['Guaranteed to lower your score','Certified by the PGA Tour','Official PGA Tour practice facility','Results guaranteed in X lessons','Endorsed by [named Tour player] unless contracted and disclosed','Best in the country']::text[],ARRAY['Launch monitor data is for instructional purposes only and may vary from on-course conditions','Liability waiver required for participation in lessons and group clinics','Facility netting and barriers comply with applicable local building codes; participants assume standard recreational risk','Range tokens and prepaid packages are non-refundable after activation','ADA accommodations available upon request — contact facility in advance for specific needs']::text[],false,false,false,ARRAY['Cannot claim PGA Tour official affiliation without licensing agreement','Instructor credential claims (PGA, TPI, USGTF) must be current and verifiable for each named individual','Trackman and Foresight Sports brand names require compliance with respective trademark usage policies','Manufacturer fitting certifications (Callaway, TaylorMade, Titleist) must reflect current authorized partner status','Testimonials and endorsements must comply with FTC endorsement guidelines']::text[])
