INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:government_ration_shop',true,'State FPS License No.',ARRAY['Ministry of Consumer Affairs Food and Public Distribution Government of India','State Food and Civil Supplies Department','Food Corporation of India','District Supply Officer','TPDS Vigilance Committee']::text[],ARRAY['Guaranteed extra quota available','Buy additional rations for cash','Premium quality grain at higher price','Ration available without Aadhaar verification','Stock always available regardless of government allocation','We sell beyond your official entitlement','No biometric needed here']::text[],ARRAY['Commodity prices are fixed by the Central Government and state government; no additional charges permitted','Distribution is subject to government allocation and monthly quota availability','Biometric authentication via Aadhaar is mandatory for commodity collection','Beneficiaries are entitled to a transaction slip for each pickup','Grievances may be filed at the state toll-free helpline or state food portal','One Nation One Ration Card portability is available subject to POS connectivity']::text[],false,false,false,ARRAY['Cannot advertise commodity availability beyond government-sanctioned quota','Cannot solicit beneficiaries from other FPS shops','Cannot charge handling or service fees beyond Central Issue Price','Cannot claim preferred stock quality over other government shops','All public communications must align with state food department guidelines']::text[])
