INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:grill_store',true,'State Contractor License # (Gas Line Installation) | State Retail Business License #',ARRAY['State Contractor Licensing Board (Gas and Outdoor Construction)','State Revenue Department (Sales Tax and Retail License)','National Fire Protection Association (NFPA 58 — Propane)','U.S. Department of Transportation (DOT — Propane Cylinder Retail and Transport)','Occupational Safety and Health Administration (OSHA)','Local Fire Marshal (Propane Storage and Display)']::text[],ARRAY['Cheapest grills guaranteed','We beat any price no matter what','Licensed gas installer on every job (unless verified per jurisdiction)','100% safe propane storage (absolute safety claims)','Best grills in the world','We will never be undersold']::text[],ARRAY['Natural gas line connections must be performed by a state-licensed contractor. Permits may be required by local jurisdiction.','Propane cylinder exchange and retail are subject to DOT and local fire code regulations. Quantities and storage locations are restricted.','Manufacturer warranty service is subject to registration and authorized dealer status. Terms vary by brand.','Outdoor kitchen installation may require local building permits. Customer is responsible for permit compliance unless contracted otherwise.','Prices and product availability are subject to change. Authorized dealer status does not guarantee pricing matching manufacturer MSRP.']::text[],false,false,false,ARRAY['Do not claim to be the exclusive or only authorized dealer for any brand without verified exclusivity documentation','Do not use competitor brand logos or trademarks in advertising without authorization','Propane sale advertising must comply with local fire marshal signage and promotional restrictions','Do not advertise natural gas conversion services without disclosing licensed contractor requirement','Seasonal sale advertising must comply with state consumer protection truth-in-advertising requirements']::text[])
