INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hawker_centre',true,'NEA Food Stall Operator Licence #',ARRAY['National Environment Agency (NEA)','Singapore Food Agency (SFA)','Majlis Ugama Islam Singapura (MUIS) — for halal certification','Singapore Civil Defence Force (SCDF) — for fire safety','Housing Development Board (HDB) — as premises landlord for applicable centres']::text[],ARRAY['guaranteed food safety','100% clean','no pests ever','approved by all health authorities','certified halal across all stalls','best hygiene in Singapore','government-endorsed superiority']::text[],ARRAY['Individual stall halal certification status varies — check MUIS certification displayed at each stall','Hygiene grades are issued per stall by NEA and are subject to change following inspections','Stallholder tenancy applications are subject to NEA ballot and eligibility criteria','Fire safety regulations under SCDF apply to all operators and stallholders within the premises','Liquor sales within hawker centres are subject to separate licensing requirements under the Liquor Control (Supply and Consumption) Act']::text[],false,false,false,ARRAY['Must not imply blanket halal certification for all stalls without individual MUIS verification','Must not use hygiene grade claims without current NEA-issued grade certificate','Must not advertise liquor promotions without valid Liquor Licence','Fire evacuation and safety notices must be prominently displayed as required by SCDF','Stallholder recruitment advertising must comply with NEA tender and ballot rules']::text[])
