INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:heliport',true,'State Aeronautics Heliport Operating Certificate #',ARRAY['Federal Aviation Administration (FAA)','State Aeronautics Division (varies by state)','U.S. Customs and Border Protection (for international facilities)','Occupational Safety and Health Administration (OSHA) – rooftop operations','Local Zoning and Land Use Authority']::text[],ARRAY['Guaranteed on-time helicopter departure','Safest heliport in the country','FAA approved without qualification','No noise impact on community']::text[],ARRAY['Operations subject to FAA regulations and applicable NOTAMs','Heliport use subject to published operating procedures and local noise abatement requirements','International arrivals require advance CBP user fee airport notification','Fuel pricing subject to change without notice','Rooftop helipad operations subject to structural load limits — consult published TLOF MTOW ratings','IS-BAH certification and NATA accreditation status subject to annual audit renewal']::text[],false,false,false,ARRAY['Cannot claim FAA ''approval'' for heliport design without specifying applicable advisory circular compliance','Cannot advertise customs facilitation services without active CBP user fee designation','Cannot claim IS-BAH certification without current valid stage designation from IBAC','Noise abatement claims must reflect documented and filed local ordinance compliance procedures','EMS response capability claims must reflect actual 24/7 operational staffing — not aspirational']::text[])
