INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hematologist',true,'State Medical License # | NPI: [number]',ARRAY['State Medical Board (jurisdiction-specific)','American Board of Internal Medicine (ABIM)','Drug Enforcement Administration (DEA)','Centers for Medicare and Medicaid Services (CMS)','Clinical Laboratory Improvement Amendments (CLIA) Program','The Joint Commission','Food and Drug Administration (FDA) — chemotherapy drug administration','Office for Civil Rights (HHS) — HIPAA enforcement']::text[],ARRAY['guaranteed cure for leukemia','100% cancer-free','we cure blood cancer','best hematologist in the country','pain-free bone marrow biopsy guaranteed','no side effects from chemotherapy','we guarantee remission','fastest diagnosis in the region']::text[],ARRAY['Individual treatment outcomes vary; no specific results are guaranteed.','This practice is not a substitute for emergency medical care. For life-threatening symptoms, call 911.','HIPAA Notice of Privacy Practices available upon request and posted in office.','Chemotherapy and other treatments carry risks; patients should discuss all options with their physician.','Clinical trial participation is voluntary and subject to eligibility criteria.','CLIA-certified laboratory services comply with federal quality standards.','CMS billing and coding compliance standards are followed for all oncology services.']::text[],false,true,true,ARRAY['Cannot make unsubstantiated claims of superiority over other hematologists or oncologists','Must include ABIM board certification status accurately and not imply certification in uncertified subspecialties','FDA regulations prohibit off-label promotion of chemotherapy drugs in advertising','CMS Anti-Kickback Statute prohibits advertising referral incentives to physicians','State medical board advertising rules require accurate credentialing disclosures','Cannot advertise experimental treatments as approved therapies without regulatory clearance','ASH and ASCO codes of ethics govern claims made in professional advertising']::text[])
