INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:home_improvement_store',true,'State Contractor License # (for installation service partners)',ARRAY['U.S. Consumer Product Safety Commission (CPSC)','U.S. Environmental Protection Agency (EPA) — RRP Rule','Occupational Safety and Health Administration (OSHA)','National Kitchen and Bath Association (NKBA) — voluntary certification body','State contractor licensing boards (per installation service partner jurisdiction)','Americans with Disabilities Act (ADA) — retail layout requirements']::text[],ARRAY['guaranteed lowest price on all items','licensed contractor services provided by store staff','EPA-certified lead paint removal','all renovation work is code compliant']::text[],ARRAY['Installation services are performed by independent licensed contractors, not store employees. Verify contractor license status with your state licensing board.','EPA RRP Rule requires disclosure and certified renovation practices for projects disturbing lead-based paint in pre-1978 homes. Ask an associate for details.','Tool rental equipment is provided as-is. Customer is responsible for proper operation and safety compliance per OSHA standards.','Paint color matching results may vary. A test application on the actual surface is recommended before full application.','Permit requirements for construction projects vary by municipality. Consult your local building department before beginning permitted work.','Product safety warnings and hazardous material handling instructions are provided per CPSC regulations. Read all labels before use.']::text[],false,false,false,ARRAY['Cannot claim store staff are licensed contractors for installation services','Cannot guarantee building code compliance for customer-executed projects','Must display CPSC-required hazardous product labeling prominently at point of sale','EPA RRP disclosure materials must be made available in-store for renovation product purchases','ADA accessibility claims must be substantiated by actual store layout compliance','Cannot imply EPA certification extends to customer renovation work performed with store products']::text[])
