INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hot_tub_repair_service',true,'NICEIC/NAPIT Registration Number',ARRAY['NICEIC (National Inspection Council for Electrical Installation Contracting)','NAPIT (National Association of Professional Inspectors and Testers)','BISHTA (British and Irish Spa and Hot Tub Association)','Health and Safety Executive (HSE) — Health and Safety at Work Act 1974','UK Building Regulations Part P — Electrical Safety in Dwellings']::text[],ARRAY['fully guaranteed results','100% safe electrical repair','no need for a Part P certificate','all repairs done same day no matter what','cheapest hot tub repair guaranteed','we beat any quote']::text[],ARRAY['All electrical work associated with hot tub installation and repair is notifiable under Part P of the Building Regulations where applicable. We are registered with [NICEIC/NAPIT] as competent persons.','Water chemistry advice is provided as general guidance only. Customers should follow manufacturer instructions and seek professional testing if unsure.','Repair guarantees apply to parts and labour supplied by us within the stated guarantee period. Guarantee does not cover misuse, incorrect chemical dosing, or damage caused by third parties.','Public liability insurance is held and a certificate is available on request. Cover does not substitute for the customer''s own property insurance.','Handling of spa chemicals is carried out in accordance with COSHH regulations. Customers are advised to store chemicals safely and follow safety data sheet instructions.']::text[],false,false,false,ARRAY['Must not claim NICEIC or NAPIT registration without current valid membership certificate','Must not use BISHTA logo or claim membership without active annual membership','Must not imply manufacturer authorisation (e.g. ''Jacuzzi Authorised'') without written agreement from the brand','Claims about guarantee periods must reflect the actual written guarantee offered and must comply with Consumer Rights Act 2015','Must not claim emergency same-day availability in advertising if capacity cannot reliably be met']::text[])
