INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:ikan_bakar_restaurant',true,'JAKIM Halal Cert # | Food Premises License #',ARRAY['Jabatan Kemajuan Islam Malaysia (JAKIM) — Halal Certification','Majlis Perbandaran / Dewan Bandaraya — Food Premises Licensing','Kementerian Kesihatan Malaysia (Ministry of Health) — Food Hygiene Regulations 2009','Kementerian Perdagangan Dalam Negeri dan Kos Sara Hidup — Consumer Protection Act 1999']::text[],ARRAY['100% guaranteed halal without valid JAKIM certification','Freshest seafood in Malaysia','Approved by Ministry of Health','No food safety issues ever reported','Government endorsed','Best ikan bakar in the world']::text[],ARRAY['Halal certification issued by JAKIM — certificate number and expiry date displayed at premises','All food handlers hold valid Sijil Pengendali Makanan under Food Hygiene Regulations 2009','Prices inclusive of service displayed per Consumer Protection Act 1999 requirements','Seafood priced by weight — final price confirmed at time of order','Food premises operating under valid license from local municipal council']::text[],false,false,false,ARRAY['Must not display expired JAKIM halal certificate in marketing materials','Pricing in advertisements must comply with Consumer Protection Act 1999 display requirements','Cannot claim halal status without valid and current JAKIM certification','Must not make unsubstantiated superlative claims about food safety or quality in advertising','Promotional materials must reflect current menu pricing — no bait-and-switch pricing']::text[])
