INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:interior_architect_office',true,'State Interior Architecture / Architecture License #',ARRAY['State Architectural Licensing Boards (varies by state — e.g. California Architects Board, Texas Board of Architectural Examiners)','Council for Interior Design Qualification (CIDQ) — NCIDQ Certificate','U.S. Green Building Council / Green Business Certification Inc. (GBCI) — LEED','International WELL Building Institute (IWBI) — WELL AP','International Building Code (IBC) — ICC','Americans with Disabilities Act — U.S. Department of Justice','NFPA (National Fire Protection Association) — NFPA 101 Life Safety Code','Facility Guidelines Institute (FGI) — for healthcare projects','Local Building Departments — permit authority']::text[],ARRAY['guaranteed permit approval','certified architect (unless state-licensed architect)','we guarantee code compliance','cheapest interior design','our designs meet all codes (without jurisdiction-specific review disclaimer)','licensed in all states']::text[],ARRAY['Interior architecture services requiring stamped documents must be performed by or under the responsible supervision of a state-licensed architect or interior architect where required by state law.','ADA compliance review does not substitute for legal counsel; clients are advised to consult an attorney for ADA liability matters.','LEED and WELL certification outcomes depend on third-party review by GBCI and IWBI respectively; certification is not guaranteed.','Healthcare interior projects are subject to FGI Guidelines and local authority having jurisdiction (AHJ) review; compliance is confirmed at permit and occupancy stages.','Permit approval is subject to local building department review and is not guaranteed by the design firm.']::text[],false,false,false,ARRAY['Must not claim architectural licensure in states where the firm does not hold a current active license','Must not use the title ''Architect'' for staff who are not state-licensed architects','NCIDQ and LEED AP credentials must only be attributed to individuals who currently hold those credentials','Award and recognition claims must reference specific named awards with issuing organization','Do not imply LEED or WELL certification for projects unless certification has been officially granted by GBCI or IWBI']::text[])
