INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:internet_shop',false,NULL,ARRAY['Federal Trade Commission (FTC) — consumer protection and CAN-SPAM enforcement','Payment Card Industry Security Standards Council (PCI SSC) — PCI-DSS compliance','Internal Revenue Service (IRS) / State Tax Authorities — sales tax collection and remittance','Information Commissioner''s Office (ICO) / EU Data Protection Authorities — GDPR compliance','Consumer Financial Protection Bureau (CFPB) — BNPL and payment financing oversight','Consumer Product Safety Commission (CPSC) — product safety and labeling standards']::text[],ARRAY['guaranteed lowest price forever','100% fraud-proof payment','we never share your data with anyone','no questions asked refunds always','government-approved online shop','fully immune to data breaches']::text[],ARRAY['Return and refund policy must be clearly displayed before purchase completion','Sales tax calculated at checkout may vary by delivery jurisdiction','BNPL financing subject to approval by third-party provider; terms and interest rates apply','Email marketing communications require explicit opt-in consent; unsubscribe option required in every message','PCI-DSS certification scope and QSA details available upon request','International orders may be subject to import duties, taxes, and customs delays beyond our control','Privacy policy disclosing data collection, use, and retention practices must be accessible from all pages']::text[],false,false,true,ARRAY['Must not make unsubstantiated claims of being the cheapest or best without verifiable data','Email promotions must comply with CAN-SPAM Act including sender identification and opt-out mechanism','Influencer and affiliate promotions must include FTC-mandated disclosure of paid partnerships','BNPL advertising must clearly state APR and terms per CFPB guidance','Product ads must not use misleading before/after pricing that inflates original price','Testimonials and reviews used in advertising must reflect genuine customer experiences per FTC guidelines']::text[])
