INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:invitation_printing_service',false,NULL,ARRAY['Federal Trade Commission (FTC) - Mail and Telephone Order Merchandise Rule','U.S. Copyright Office - Licensed Design Element Compliance','U.S. Postal Service (USPS) - Mailing Standards for Envelope Dimensions and Weight']::text[],ARRAY['guaranteed delivery by [date] without written confirmation','100% color match guarantee without signed proof approval','official licensed design without verified license documentation','fastest printer in the country']::text[],ARRAY['Final delivery dates are estimates and subject to production scheduling; rush orders require written confirmation of availability.','All custom designs are subject to a digital proof approval process before printing commences; the studio is not liable for errors approved by the client.','Licensed design elements used in client projects are the responsibility of the client to clear for commercial use unless the studio provides documented licensing.','Bulk mailing fulfillment timelines are subject to USPS processing schedules and are not guaranteed by the printing studio.','ADA accessibility considerations apply to digital proof formats; clients requiring accessible digital documents should notify the studio at time of order.']::text[],false,false,false,ARRAY['Do not advertise guaranteed same-day printing without confirming production capacity at time of inquiry','Do not claim licensed third-party design elements (Disney, branded IP) are available without documented licensing agreements','Do not imply USPS delivery guarantees for bulk mail fulfillment','Do not use competitor brand names in advertising copy in a disparaging manner','Ensure all advertised prices include applicable setup fees or clearly disclose that setup fees are additional']::text[])
