INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:irish_pub',true,'State Liquor License #',ARRAY['State Alcoholic Beverage Control (ABC) Board','Local Health Department','Local Fire Marshal','State Department of Revenue (Sales Tax)']::text[],ARRAY['All you can drink','Unlimited alcohol','Drink until you drop','We never cut anyone off','No ID required','Minors welcome at the bar','Guaranteed cheapest drinks','We ignore noise complaints']::text[],ARRAY['Must be 21 or older to purchase or consume alcohol','Please drink responsibly','Do not drink and drive — designate a driver or use a rideshare','Occupancy limit strictly enforced per fire code','Food and non-alcoholic beverages available upon request','Management reserves the right to refuse service']::text[],true,false,false,ARRAY['No advertising implying unlimited alcohol consumption','No promotions targeting minors or using imagery appealing primarily to underage persons','No claims of health benefits from alcohol consumption','No advertising during restricted hours per state ABC rules','No misleading happy hour pricing that violates state drink promotion laws','Live music event advertising must include noise ordinance compliance language where required by local ordinance']::text[])
