INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:japanese_confectionery_shop',true,'Food Sanitation Business License #',ARRAY['Japan Consumer Affairs Agency (消費者庁) – Food Labeling Standards Act','Ministry of Health Labour and Welfare – Food Sanitation Law','National Measurement Institute of Japan – Measurement Law (計量法)','Prefectural Health Centre (保健所) – Food Business Permit and Annual Inspections']::text[],ARRAY['guaranteed freshest in the city','medically beneficial','cures or prevents illness','all-natural with no processing','100% allergen-free without lab verification','approved by the Ministry of Health']::text[],ARRAY['All packaged confectionery displays allergen information in compliance with Consumer Affairs Agency regulations','Use-by date and storage conditions are labeled on all products per Food Labeling Standards Act','Weight and quantity labeling complies with the Measurement Law of Japan','Food sanitation business license is held and inspected annually by the prefectural health centre','Namagashi (fresh wagashi) must be consumed within the stated use-by period; refrigeration may be required']::text[],false,false,false,ARRAY['Must not make unsubstantiated health or nutritional claims on confectionery products','Allergen claims must reflect certified testing or clearly disclosed production environment caveats','Weight and quantity stated in advertising must match labeled product per Measurement Law','Product origin and ingredient claims must be verifiable and consistent with Food Labeling Standards Act','Discount or price promotions must clearly state terms per Consumer Affairs Agency guidelines']::text[])
