INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:jewelry_equipment_supplier',true,'Authorized Distributor # / Trade License',ARRAY['U.S. Occupational Safety and Health Administration (OSHA)','Federal Trade Commission (FTC)','U.S. Department of Transportation (DOT) - Hazardous Materials','U.S. Bureau of Industry and Security (BIS) - Export Administration Regulations','Underwriters Laboratories (UL) / CE Marking (EU Directives) for electrical equipment']::text[],ARRAY['Guaranteed safe for all users without training','No OSHA compliance required','All equipment ships internationally without restriction','CE/UL certified — no inspection needed','Chemicals ship with no special handling']::text[],ARRAY['Electrical equipment sold must carry applicable UL (US) or CE (international) certification; verify compliance before use in manufacturing environments.','Machinery sold for manufacturing use may be subject to OSHA equipment safety standards; buyers are responsible for workplace compliance.','Export of certain jewelry manufacturing equipment may require a license under the Export Administration Regulations (EAR); consult BIS before international shipment.','Hazardous chemical components (acids, plating solutions) are subject to DOT hazardous materials shipping regulations; proper labeling and packaging required.','Country-of-origin labeling on imported equipment must comply with FTC regulations; misrepresentation is prohibited.','Equipment warranties and return terms vary by manufacturer; see individual product documentation for coverage details.']::text[],false,false,false,ARRAY['Do not claim equipment is ''OSHA approved'' — OSHA does not approve products, only regulates workplaces','Do not advertise UL or CE certification for equipment lines not formally certified','Do not claim unrestricted international shipping for controlled equipment categories','Do not use misleading country-of-origin claims for imported equipment marketed as domestic','Wholesale pricing and trade terms must not be advertised publicly in ways that violate authorized distributor agreements']::text[])
