INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:judo_club',true,'USA Judo Club Affiliation #',ARRAY['USA Judo (National Governing Body, USOPC recognized)','United States Center for SafeSport','International Judo Federation (via NGB)','State Athletic or Martial Arts Regulatory Bodies (where applicable)','Local Fire Marshal and Building Code Authority']::text[],ARRAY['guaranteed black belt in X months','we guarantee your child''s safety','better than any other judo club','Olympic training center','fully certified in every martial art','injury-free training']::text[],ARRAY['All participants must sign a liability waiver prior to training; minors require guardian signature.','All coaches and volunteers working with minors are SafeSport certified and background checked per USOPC requirements.','Club is affiliated with USA Judo; sanctioned competition requires current USA Judo athlete membership.','Adaptive judo programming is provided as general fitness and recreational activity; consult a physician before participation.']::text[],false,false,false,ARRAY['Cannot claim Olympic affiliation or imply USOPC endorsement without authorization','Cannot use IJF or USA Judo logos without current affiliation in good standing','SafeSport compliance status must remain current before referencing SafeSport certification in advertising','Cannot make comparative superiority claims over other martial arts clubs','Tournament results must be accurately stated and verifiable']::text[])
