INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:kinesiologist',true,'Registered Kinesiologist (RKin) — Registration #',ARRAY['Ontario Kinesiology Association (OKA)','British Columbia Kinesiology Association (BCKA)','Kinesiology Association of Alberta (KAA)','Canadian Kinesiology Alliance (CKA)','British Columbia Kinesiology Act (provincial statute)','WorkSafeBC (authorized provider oversight)','WSIB Ontario (approved provider oversight)']::text[],ARRAY['We diagnose medical conditions','We treat diseases','Guaranteed recovery','Cure for chronic pain','We provide physiotherapy services','We prescribe medication','Our results are guaranteed','Medically approved treatment']::text[],ARRAY['Kinesiology services do not constitute medical diagnosis or treatment','Results may vary; individualized programs are developed based on assessment findings','Practitioners are not physicians; clients with acute medical conditions should consult their doctor','Client health information is protected under PIPEDA and applicable provincial privacy legislation (PHIPA, PIPA)','Informed consent must be obtained prior to all assessments and programming','Scope of practice is defined by the governing body of the applicable province or state; clients should verify their practitioner''s registration status']::text[],false,true,false,ARRAY['Must not claim ability to diagnose medical conditions','Must not use the title ''physiotherapist'' or ''physical therapist'' without separate regulated credentials','Must not advertise WSIB or WorkSafeBC services without confirmed approved provider status','Must comply with provincial advertising standards set by relevant kinesiology association','Must not use testimonials that imply guaranteed clinical outcomes','Extended health insurance billing claims must reflect actual services rendered per insurer agreements']::text[])
