INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:lawn_care_service',true,'State Pesticide Applicator License #',ARRAY['State Department of Agriculture (pesticide applicator licensing)','U.S. Environmental Protection Agency (EPA) — restricted-use pesticide regulations','State Contractor Licensing Board — business registration','OSHA — equipment operation and chemical handling safety standards','State Department of Agriculture — fertilizer and soil amendment product compliance','Local Municipal Environmental or Zoning Authority — chemical application near waterways ordinances']::text[],ARRAY['Guaranteed to eliminate all weeds','100% safe for children and pets immediately after application','We use the same chemicals as natural products','No chemicals used (unless certified organic program)','Permanently eliminates grubs','EPA approved (EPA registers, not approves, pesticides)']::text[],ARRAY['Pesticide applications performed only by state-licensed applicators. License number available upon request.','Keep children and pets off treated areas until dry or as directed on product label — typically 24 to 48 hours.','Fertilizer and pesticide applications comply with local municipal ordinances including buffer zones near waterways.','Results may vary based on grass type, soil condition, weather, and customer watering practices.','Restricted-use pesticides applied only by certified applicators in accordance with EPA label requirements.','This business is licensed and insured. Proof of insurance available upon request.']::text[],false,false,false,ARRAY['Cannot claim pesticides are EPA approved — EPA registers pesticides, approval language is prohibited','Must include re-entry interval (REI) information in post-treatment communications where required by label','Cannot guarantee specific weed elimination percentages without qualifying language','Organic or natural claims must meet applicable FTC Green Guides standards and reflect actual product ingredients','Must not imply immediate pet or child safety post-treatment without specifying re-entry wait time','State-specific pesticide advertising rules may require license number disclosure in certain ad formats']::text[])
