INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:lawn_equipment_rental_service',true,'State Business License #',ARRAY['U.S. Environmental Protection Agency (EPA) — Small Engine Emissions Standards','Occupational Safety and Health Administration (OSHA) — 29 CFR 1910 General Industry','American National Standards Institute / Outdoor Power Equipment Institute (ANSI/OPEI) — Equipment Safety Standards','State Rental Industry Regulatory Agency (jurisdiction-specific)','Americans with Disabilities Act (ADA) — Facility Accessibility']::text[],ARRAY['guaranteed safe for all users','no training required','risk-free rental','our equipment never breaks down','EPA certified operator','OSHA approved for all uses','zero liability for damage']::text[],ARRAY['Renter is responsible for reviewing and accepting all terms in the rental agreement prior to equipment pickup.','Damage waiver does not cover intentional misuse, theft, or loss; see rental contract for full terms.','Operator must follow all safety instructions provided at pickup and as outlined in the equipment manual.','Local noise ordinance restrictions may apply to equipment operation hours; renter is responsible for compliance.','EPA-compliant equipment does not guarantee operator compliance with all local emissions or air quality regulations.','Equipment must be returned in the condition rented, fueled per policy, or additional charges may apply.']::text[],true,false,false,ARRAY['Do not imply professional landscape services are included in equipment rental','Do not claim equipment operation requires no experience or training','Do not advertise pricing without including applicable fees and deposit requirements','Do not use ''certified operator'' language unless staff hold a recognized certification','Do not make environmental claims beyond documented EPA compliance status']::text[])
