INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:leather_goods_manufacturer',true,'ISO 9001 Certificate # | Sedex Member ID | CITES Permit Reference',ARRAY['U.S. Fish and Wildlife Service (CITES enforcement)','European Chemicals Agency (REACH regulation)','California Office of Environmental Health Hazard Assessment (Prop 65)','U.S. Department of Labor Wage and Hour Division (FLSA)','Federal Trade Commission (Country of Origin Labeling)','International Organization for Standardization (ISO 9001)']::text[],ARRAY['100% chemical-free leather','CITES-exempt exotic leather','guaranteed Prop 65 safe without testing','fully organic leather','no chemicals used in tanning','cruelty-free leather (without certification)']::text[],ARRAY['Exotic leather goods are subject to CITES regulations; valid permits required for import/export.','Products sold into California may require Prop 65 warning labels for lead and chromium VI content.','Country of origin must be accurately disclosed on all product labeling per FTC requirements.','REACH-regulated substances in leather tanning chemicals must comply with EU Annex XVII restriction list.','All labor practices comply with the Fair Labor Standards Act; certifications available upon request.']::text[],false,false,false,ARRAY['Must not claim exotic leather is CITES-exempt without current valid permits','Must not use ''organic'' for leather without certified organic tanning documentation','Must not imply Prop 65 compliance without up-to-date substance testing records','Must not claim ethical sourcing without active Sedex or equivalent third-party audit','Environmental or sustainability claims must be substantiated per FTC Green Guides']::text[])
