INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:leather_repair_service',true,'State Business License #',ARRAY['State Department of Consumer Affairs (repair services licensing, varies by state)','OSHA (Occupational Safety and Health Administration — chemical/solvent workshop standards)','EPA (Environmental Protection Agency — dye and solvent disposal regulations)','State Attorney General Consumer Protection Division (written estimate and warranty laws)']::text[],ARRAY['guaranteed to look brand new','permanent repair — will never fail again','we fix all leather types including bonded leather completely','factory-authorized by [luxury brand] without verified written authorization']::text[],ARRAY['Written repair estimate must be provided before work commences in states requiring it (CA BAR, NY, etc.)','Repair outcomes depend on leather type, age, and prior damage — results may vary','Luxury brand authorization claims must reflect verified, current written manufacturer agreements','Solvent and dye disposal performed in compliance with applicable EPA and state environmental regulations','All chemical products used in workshop handled per OSHA 29 CFR 1910.94 ventilation and PPE standards']::text[],false,false,false,ARRAY['Do not claim manufacturer authorization for luxury brands without documented written agreements','Do not guarantee specific color match outcomes in advertising without qualification','Do not advertise as ''licensed cobbler'' in jurisdictions where no such license exists — use ''trained'' or ''certified'' instead','Repair warranty terms advertised must match written warranty policy provided to customers','Price advertising must reflect final all-inclusive pricing or clearly disclose that estimates require item inspection']::text[])
