INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:linoleum_store',true,'Contractor License # / INSTALL Certification #',ARRAY['INSTALL Certification Program (United Brotherhood of Carpenters)','Forbo Flooring Systems (Marmoleum Certified Retailer Program)','FCICA – Flooring Contractors Industry Association','NWFA – National Wood Flooring Association','U.S. Environmental Protection Agency (EPA RRP Rule – asbestos-containing materials)','ASTM International (ASTM F710, ASTM F1066 flooring standards)','ADA – Americans with Disabilities Act (commercial flooring slip resistance)','State/Local Building Code Authority (subfloor installation permits)']::text[],ARRAY['guaranteed asbestos-free removal','completely VOC-free flooring','permanent warranty','EPA-approved removal contractor','ADA certified installation','100% waterproof linoleum']::text[],ARRAY['Older vinyl flooring (pre-1980) may contain asbestos; removal must comply with EPA RRP regulations and applicable state laws.','VOC emission claims are based on product manufacturer data; independent testing may vary.','ADA slip resistance compliance applies to specified commercial products only; residential products are not covered.','Manufacturer warranties are subject to proper subfloor preparation and installation per manufacturer guidelines; improper installation voids warranty.','All estimates are subject to on-site measurement verification; final price may vary based on site conditions.','Consumer protection law requires full written warranty disclosure prior to contract signing.']::text[],false,false,false,ARRAY['Do not claim EPA certification or approval for asbestos removal unless a licensed abatement contractor is engaged.','Do not make unqualified environmental superiority claims without referencing specific certification (e.g. FloorScore, GreenGuard).','Do not use the term ADA approved or ADA certified for products; use ADA compliant slip resistance COF >= 0.6.','Do not advertise price-per-square-foot estimates without a disclaimer that final pricing depends on site conditions and subfloor status.','Do not imply Marmoleum certified retailer status applies to other natural flooring brands not covered by Forbo certification.']::text[])
