INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:local_history_museum',true,'IRS EIN / 501(c)(3) Determination Letter',ARRAY['American Alliance of Museums (AAM) Standards and Best Practices','American Association for State and Local History (AASLH)','IRS Exempt Organizations Division (501(c)(3) compliance)','National NAGPRA Program, National Park Service, U.S. Department of the Interior','State Historic Preservation Office (SHPO)','Institute of Museum and Library Services (IMLS)','Americans with Disabilities Act (ADA) — U.S. Department of Justice','Local Fire Marshal and Building Code Authority']::text[],ARRAY['guaranteed artifact appraisal value','we buy artifacts','investment-grade collectibles','artifact authentication certificate for sale','we can legally export cultural heritage items','NAGPRA does not apply to our collection','all items in our collection have clear title','fully ADA compliant without qualification']::text[],ARRAY['This institution is a 501(c)(3) nonprofit organization. Donations may be tax-deductible to the extent permitted by law — consult your tax advisor.','Artifact donations become the property of the museum and are subject to our Collections Management Policy. The museum does not provide monetary appraisals for donated items.','NAGPRA compliance: This institution inventories and consults with federally recognized tribes regarding Native American human remains and cultural items in accordance with 25 U.S.C. § 3001 et seq.','Admission, hours, and program availability are subject to change. Please verify current information before your visit.','Archival research access may require advance appointment and is subject to collection access policies.']::text[],false,false,false,ARRAY['Must not imply monetary appraisal services for artifacts','Must not advertise artifact purchase or sales to the public','Claims of AAM accreditation must be current and verifiable','Must not use the term ''certified'' for staff unless credential is current and verifiable (e.g., CA credential from SAA)','Promotional claims about accessibility must reflect actual ADA compliance status — no blanket ''fully accessible'' claims without qualification','Fundraising solicitations must comply with state charitable solicitation registration requirements','Use of images depicting Native American cultural items must follow tribal consultation and intellectual property protocols']::text[])
