INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:locksmith',true,'State Locksmith License #',ARRAY['State Licensing Boards for Locksmiths (varies by jurisdiction, e.g., Texas DPS Private Security Bureau, California BSIS, North Carolina Locksmith Licensing Board)','NASTF (National Automotive Service Task Force) for automotive key programming','FTC consumer protection rules on pricing disclosure']::text[],ARRAY['lowest price guaranteed without upfront disclosure','no hidden fees (without written price confirmation)','police-approved locksmith','government-certified locksmith','certified by the state (without naming specific state credential)','fastest locksmith in [city] (unsupported superlative)']::text[],ARRAY['Proof of ownership or authorization required before performing any lockout service','All pricing disclosed upfront before work begins as required by consumer protection laws','State locksmith license number displayed where required by jurisdiction','Business is bonded and insured — proof of coverage available upon request','After-hours and emergency service rates disclosed separately from standard rates']::text[],false,false,false,ARRAY['Must not advertise a price without disclosing all mandatory fees and after-hours surcharges','Must not imply police or government endorsement without documented partnership','Must disclose state license number in advertising where required by state law (e.g., Texas, North Carolina)','Must not use fake address listings to appear local in areas not actually served','Google Local Services Ads require background check verification and license upload before running ads']::text[])
