INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:lumber_store',true,'FSC Chain of Custody Certificate # | EPA TSCA Title VI Cert # | ALSC Grader Certification #',ARRAY['American Lumber Standard Committee (ALSC)','U.S. Environmental Protection Agency (EPA) — TSCA Title VI','Occupational Safety and Health Administration (OSHA)','U.S. Department of Transportation (DOT)','Forest Stewardship Council (FSC)','National Hardwood Lumber Association (NHLA)']::text[],ARRAY['guaranteed lowest price on all lumber','certified structural lumber without grading documentation','formaldehyde-free composite wood (unless independently verified and certified)','FSC certified (without valid chain of custody certificate on file)','OSHA compliant yard (without current inspection documentation)']::text[],ARRAY['Lumber grading is performed in accordance with American Lumber Standard Committee (ALSC) approved grading rules. Grade marks on lumber are authoritative; visual re-inspection by buyer is recommended.','All composite wood products containing formaldehyde-based resins comply with EPA TSCA Title VI emission standards. Certificate available upon request.','Pressure-treated lumber contains chemical preservatives. Follow all EPA and manufacturer handling, use, and disposal guidelines. Not for use in direct contact with drinking water without approved formulation.','Delivery services subject to DOT carrier regulations. Scheduling and load specifications governed by applicable transportation law.','FSC-certified products are available for orders where chain of custody documentation is required. Request FSC invoice documentation at time of order.']::text[],false,false,false,ARRAY['Do not advertise FSC certification status without a current valid FSC chain of custody certificate on file','Do not claim EPA TSCA Title VI compliance for specific products without third-party certifier documentation','Do not use ALSC grade marks or imply grading certification without a certified grader on staff','Do not advertise DOT-compliant delivery without current driver and vehicle compliance records','Avoid absolute superlative pricing claims (e.g. ''cheapest lumber in the state'') without substantiation']::text[])
