INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:marathi_restaurant',true,'Food Safety Certificate #',ARRAY['Local Health Department Food Safety Authority','Food Safety and Standards Authority of India (FSSAI) — if operating in India','State Liquor Control Board (if serving alcohol)','Relevant Halal Certification Body (if halal-certified)','Kosher Certification Agency (if kosher-certified)']::text[],ARRAY['100% safe for all allergies','Guaranteed allergen-free','Certified healthiest Indian food','No MSG guaranteed','Best Indian food in the world','Approved by the government of India']::text[],ARRAY['Menu items may contain peanuts and sesame — please inform staff of allergies before ordering','Spice levels are approximate — request adjustments when ordering','Halal and kosher certifications apply only to designated menu items — ask staff for details','Alcohol is served only to patrons of legal drinking age — valid ID required','Tiffin delivery areas are subject to change — confirm your zone before subscribing']::text[],false,false,false,ARRAY['Do not claim halal or kosher certification without valid current credentials','Do not advertise allergy-safe or allergen-free dishes without documented protocols','Do not use government seals or endorsement imagery unless officially licensed','Liquor advertising must comply with local alcohol advertising laws if applicable','Health claims about specific dishes (e.g., digestive benefits of sol kadhi) must be clearly framed as cultural tradition, not medical advice']::text[])
