INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:marble_contractor',true,'State Contractor License #',ARRAY['State Contractor Licensing Board (jurisdiction-specific, e.g. CSLB in California, DPOR in Virginia)','Occupational Safety and Health Administration (OSHA) — silica dust standards 29 CFR 1926.1153','EPA Renovation, Repair and Painting Rule (RRP) for pre-1978 structures','Local Building and Permitting Departments for structural stone installations','Americans with Disabilities Act (ADA) — flooring slip-resistance and transition standards']::text[],ARRAY['guaranteed lowest price','no permit required','completely safe silica-free cutting','licensed in all states','certified by OSHA (OSHA does not certify contractors)','guaranteed no etching or staining ever','lifetime warranty on all marble surfaces']::text[],ARRAY['Marble is a natural stone and may etch or stain when exposed to acidic substances; regular sealing is strongly recommended.','Building permits may be required for structural stone floor installations; contractor will advise based on local jurisdiction.','Silica dust generated during stone cutting is a serious health hazard; OSHA-compliant wet cutting and PPE are used on all jobsites.','EPA Lead-Safe work practices are required when performing renovation work in structures built prior to 1978.','ADA slip-resistance requirements apply to marble flooring in commercial and public-access spaces; contractor will specify compliant finishes.']::text[],false,false,false,ARRAY['Must display valid state contractor license number in all advertisements per most state contractor licensing laws','Cannot claim OSHA certification — OSHA issues training completion, not contractor certification','Must not misrepresent silica safety compliance or omit required worker protection disclosures','Commercial flooring advertisements must not imply ADA compliance without specifying the applicable finish and installation standard','Must not claim NSI or NTCA credentials without maintaining active membership or designation in good standing']::text[])
