INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:meal_takeaway',true,'Food Service Establishment License #',ARRAY['State Department of Health / State Food Safety Authority','Local County or City Health Department','U.S. Food and Drug Administration (FDA) — Menu Labeling Rule','State Department of Revenue — Prepared Food Sales Tax','Local Fire Marshal — Occupancy and Safety Code']::text[],ARRAY['guaranteed safe for all allergies','100% allergen-free kitchen','certified organic (without USDA certification)','healthiest restaurant in the city','no risk of cross-contamination','approved by the FDA']::text[],ARRAY['Calorie counts are listed per FDA menu labeling requirements. Ask a crew member for full nutrition information.','Allergen information is provided as a guide only. Cross-contact may occur in our kitchen. Guests with severe allergies should inform staff before ordering.','Health Department inspection grade is posted at the premises as required by local ordinance.','Prices and menu items subject to change. Sales tax applied per state and local law on prepared food.','Third-party delivery order accuracy and temperature are subject to the delivery partner''s handling after pickup from our location.']::text[],false,false,false,ARRAY['Cannot claim ''allergen-free'' without verified dedicated allergen-free preparation protocols','Must disclose calorie counts on standard menu items per FDA 21 CFR Part 101','Cannot use ''organic'' labeling without USDA National Organic Program certification','Health inspection grade display must comply with local ordinance formatting requirements','Third-party app promotions must not misrepresent pricing or portion sizes relative to in-store menu','Loyalty program terms must be clearly disclosed including any expiration or blackout conditions']::text[])
