INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:mechanical_plant',true,'State Mechanical Contractor License #',ARRAY['OSHA (29 CFR 1910 General Industry Standards)','ASME Boiler and Pressure Vessel Code (BPVC)','EPA Clean Air Act Section 608 (Refrigerant Management)','National Fire Protection Association (NFPA 70, NFPA 72)','State Mechanical Licensing Boards (jurisdiction-specific)','Local Building and Mechanical Code Authorities Having Jurisdiction (AHJ)']::text[],ARRAY['guaranteed lowest price on all mechanical services','OSHA-approved facility','EPA-exempt refrigerant handling','fully insured against all mechanical liabilities','certified to fix any industrial problem','government-certified to perform all boiler work']::text[],ARRAY['Mechanical contractor license numbers and jurisdictions vary by state; verify current license status with the applicable state licensing board.','ASME boiler and pressure vessel inspections are conducted in accordance with the current edition of the ASME BPVC; scope of inspection varies by equipment type and jurisdiction.','EPA Section 608 certification applies to technicians handling refrigerants; compliance requirements may change; consult the EPA for current regulations.','Energy savings estimates from audits are projections based on current operating conditions and are not guaranteed outcomes.','Emergency response availability is subject to technician dispatch capacity and geographic service area.']::text[],false,false,false,ARRAY['Must not claim government endorsement or approval for mechanical services','Must not imply ASME or NFPA membership confers regulatory authority to override AHJ decisions','Must not advertise emissions compliance guarantees without current EPA documentation','Must not use ''licensed in all states'' without verified multi-state licensure','Must comply with FTC guidelines on energy savings claims in audit advertising']::text[])
