INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:medical_group',true,'State Medical License # | NPI: [NPI Number]',ARRAY['State Medical Board (varies by state, e.g. California Medical Board, Texas Medical Board)','Drug Enforcement Administration (DEA)','Centers for Medicare and Medicaid Services (CMS)','Office for Civil Rights (OCR) – HIPAA Enforcement','National Committee for Quality Assurance (NCQA)','The Joint Commission (JCAHO)','State Department of Insurance (advertising claims)']::text[],ARRAY['guaranteed cure','we cure','100% success rate','best doctors in America (without verified award citation)','no side effects','we accept all insurance (without current verification)','HIPAA-free','we never share your data with anyone']::text[],ARRAY['This medical group is not an emergency services provider. For life-threatening emergencies, call 911 or go to the nearest emergency room.','Insurance network participation is subject to change. Verify your coverage prior to your appointment.','Telehealth services are only available to patients located in states where our physicians hold active licenses.','Prior authorization requirements are determined by your insurer and may affect treatment timelines.','This website is for informational purposes only and does not constitute medical advice.','Patient privacy is protected under HIPAA. Our Notice of Privacy Practices is available upon request.']::text[],false,true,true,ARRAY['Network participation claims must reflect current, verified payer contracts','Quality or outcome claims must cite NCQA, CMS, or HEDIS data with source and date','Physician credential claims must reflect current board certification status','Fee transparency required per CMS No Surprises Act and state insurance laws','Anti-Kickback Statute and Stark Law prohibit advertising that implies or enables improper referral compensation','HIPAA prohibits use of identifiable patient information in testimonials without explicit written authorization','FTC guidelines apply to patient testimonial endorsements — results must be typical or accompanied by disclaimer']::text[])
