INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:medical_lawyer',true,'State Bar License #',ARRAY['State Bar Association (jurisdiction-specific)','American Bar Association Model Rules of Professional Conduct','State Supreme Court Attorney Disciplinary Board','HIPAA Office for Civil Rights (for patient record handling)']::text[],ARRAY['guaranteed results','we will win your case','best lawyer in the country','fastest settlement','no risk whatsoever','certain victory','100% success rate','you will get millions']::text[],ARRAY['Past results do not guarantee a future outcome','Attorney advertising — prior results do not guarantee similar results','This website does not constitute legal advice and does not form an attorney-client relationship','Contingency fee arrangements are subject to a written fee agreement','State-specific statutes of limitations apply — consult an attorney immediately','Medical records handling complies with HIPAA Privacy Rule 45 CFR Parts 160 and 164']::text[],false,true,false,ARRAY['Must comply with state bar rules on attorney advertising (Rule 7.1–7.5 MRPC)','Cannot make false or misleading communications about legal services','Testimonials must not create unjustified expectations of similar results','Must disclose if communications are attorney advertising where required by state rule','Cannot guarantee outcomes or imply specialty certification without accredited board recognition']::text[])
