INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:mexican_grocery_store',true,'State Food Establishment Permit # | Health Dept. Permit # | MSB License # (if applicable)',ARRAY['U.S. Food and Drug Administration (FDA) — food labeling and packaged food standards','USDA Agricultural Marketing Service — fresh produce import standards','USDA Food Safety and Inspection Service (FSIS) — fresh meat retail handling','State Department of Agriculture — meat sales and fresh food retail licensing','Local/County Health Department — food establishment permits and inspections','Financial Crimes Enforcement Network (FinCEN) — Money Services Business registration','State Money Transmitter Regulator (varies by state) — wire transfer and money order services']::text[],ARRAY['USDA-approved','Government certified safe','Guaranteed freshest in the city','No health code violations ever','Lowest remittance fees guaranteed','FDA approved store','Certified organic (without valid USDA organic certification)','Best prices in the state']::text[],ARRAY['All fresh meat products handled in accordance with USDA and state department of agriculture regulations.','Wire transfer and money order services provided under [State] Money Transmitter License #[number]. Fees and exchange rates apply.','Food handler certifications maintained for all staff handling fresh and prepared foods per state law.','Health department inspection records available upon request. Current permit posted at point of sale as required by law.','Packaged food products labeled in compliance with FDA requirements including ingredient lists and allergen disclosures.']::text[],false,false,true,ARRAY['Must not advertise wire transfer exchange rates without disclosing applicable fees per Dodd-Frank Act Remittance Rule (Regulation E).','Cannot claim ''USDA-certified'' or ''USDA-approved'' for meat products without holding a formal USDA grant of inspection.','Must include required fee disclosures in any advertisement for money transfer services.','Health department rating must be accurately represented; inflating or misrepresenting inspection scores is prohibited.','Organic claims for produce or prepared foods require valid USDA National Organic Program certification.']::text[])
