INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:mobile_home_rental_agency',true,'State Real Estate Broker/Property Manager License #',ARRAY['U.S. Department of Housing and Urban Development (HUD) — Manufactured Housing Standards','State Real Estate Commission (jurisdiction-specific)','State Manufactured Housing Regulatory Agency (jurisdiction-specific)','U.S. Department of Housing and Urban Development — Fair Housing and Equal Opportunity Office','Local Municipal Zoning and Land Use Authority','State Attorney General — Landlord-Tenant Division']::text[],ARRAY['guaranteed approval regardless of credit','eviction-free community','no background check required','we are not subject to Fair Housing laws','rent will never increase','HUD-approved community (unless formally designated)','luxury manufactured homes (misleading quality claim without substantiation)']::text[],ARRAY['All rental applications are subject to credit, income, and background screening in compliance with the Fair Housing Act.','Lot rent is subject to increase upon written notice as required by state law. Current notice period: [X days].','This community operates under state landlord-tenant law and all applicable HUD Manufactured Housing Standards.','Equal Housing Opportunity: We do not discriminate on the basis of race, color, national origin, religion, sex, familial status, or disability.','Security deposit terms and conditions are governed by [State] landlord-tenant statutes.','Age-restricted communities: occupancy limited to residents 55 and older per applicable federal housing law.']::text[],false,false,false,ARRAY['Must not imply HUD program endorsement or government-backed status without official designation','Fair Housing logo required on all advertising materials','Cannot advertise discriminatory preferences by protected class in any rental marketing','Lot rent increase advertisements must include applicable notice period requirements','Must not use ''guaranteed'' or ''no questions asked'' language in tenant qualification advertising','Income-based or voucher-acceptance advertising must accurately reflect current program participation status']::text[])
