INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:moravian_church',true,'IRS 501(c)(3) Tax-Exempt Organization | EIN: [XX-XXXXXXX]',ARRAY['Internal Revenue Service (IRS) — 501(c)(3) nonprofit religious exemption','U.S. Department of Justice — RLUIPA (Religious Land Use and Institutionalized Persons Act)','State Attorney General Charitable Trust Division — state charity registration','Moravian Church in America Provincial Elders Conference — denominational oversight']::text[],ARRAY['guaranteed salvation through membership','the only true church','we are endorsed by [government body]','tax-deductible for all donations regardless of benefit received']::text[],ARRAY['This congregation is recognized as a tax-exempt religious organization under IRS Section 501(c)(3). Contributions may be tax-deductible to the extent permitted by law.','All staff and volunteers working with minors are subject to background checks in compliance with our child safety policy.','This facility strives to meet ADA accessibility standards. Individuals requiring accommodations are encouraged to contact the church office in advance.','State charity registration numbers available upon request where required by law.']::text[],false,false,false,ARRAY['Must not imply government endorsement of religious services','Must not guarantee specific spiritual outcomes','Fundraising solicitations must comply with state charitable solicitation registration requirements','Must not misrepresent tax-deductibility of donations that confer personal benefit']::text[])
