INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:motorsports_store',true,'State Motor Vehicle / Powersports Dealer License #',ARRAY['State Motor Vehicle Dealer Licensing Agency (jurisdiction-specific)','U.S. Consumer Product Safety Commission (CPSC)','U.S. Environmental Protection Agency (EPA) — Emissions Standards','U.S. Coast Guard (USCG) — Personal Watercraft Safety Equipment','Consumer Financial Protection Bureau (CFPB) — TILA Financing Disclosures','State Department of Motor Vehicles or Natural Resources (snowmobile registration)']::text[],ARRAY['guaranteed financing approval','no credit check required','EPA-exempt off-road vehicle','safe for all ages without supervision','zero emissions off-road vehicle','street legal without modification']::text[],ARRAY['Financing subject to credit approval. See dealer for complete terms and conditions. Truth in Lending Act disclosures provided at time of financing.','Youth ATVs are labeled with age recommendations per CPSC guidelines. Adult supervision required for all youth riders.','Personal watercraft sold with required U.S. Coast Guard safety equipment. Buyer responsible for compliance with applicable state boating laws.','Snowmobiles must be registered per applicable state law. Trail permits may be required. See dealer for state-specific requirements.','All off-highway vehicles must comply with EPA emissions standards. Modifications that defeat emissions controls may be illegal.','Prices, availability, and financing rates subject to change without notice. See dealer for current inventory and offers.']::text[],false,false,true,ARRAY['All financing advertisements must include APR, term, and required TILA disclosures','Youth ATV advertising must include CPSC-mandated age-appropriateness warnings','PWC advertising must not omit required Coast Guard safety equipment compliance','EPA emissions compliance claims must be accurate and verifiable','State-specific snowmobile trail permit requirements must be disclosed in applicable market advertising','Dealer authorization claims (e.g., ''Authorized Polaris Dealer'') must be currently valid and verifiable']::text[])
