INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:museum_of_zoology',true,'AAM Accreditation # | CITES Permit # | EIN',ARRAY['American Alliance of Museums (AAM)','Convention on International Trade in Endangered Species (CITES) — enforced by USFWS','U.S. Fish and Wildlife Service (USFWS) — Migratory Bird Treaty Act','Internal Revenue Service (IRS) — 501(c)(3) non-profit status','State Attorney General — charitable organization registration','Americans with Disabilities Act (ADA) — U.S. Department of Justice']::text[],ARRAY['100% safe for all animals','live animals available for interaction','we sell wildlife specimens','all specimens legally obtained — no further documentation needed']::text[],ARRAY['All specimens in our collection are held in compliance with CITES and applicable U.S. federal wildlife protection laws.','Bird specimens are held under permits complying with the Migratory Bird Treaty Act (MBTA).','This institution is a registered 501(c)(3) non-profit organization. Donations may be tax-deductible.','Specimen acquisition follows ethical sourcing standards; new donations are subject to legal review before acceptance.','ADA-accessible facilities are available throughout the museum. Contact us for specific accommodation needs.']::text[],false,false,false,ARRAY['Must not imply live animal exhibitions unless specifically offered','Must not advertise purchase or sale of protected species specimens','Must not claim CITES compliance without current certification on file','Conservation claims must be supported by documented programs and partnerships','Educational outcome claims must not overstate or guarantee specific learning results']::text[])
