INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:musical_instrument_rental_service',true,'State Business License #',ARRAY['State Consumer Protection Agencies','State Attorney General Offices (Rental Purchase Act enforcement)','Federal Trade Commission (Truth in Lending Act / TILA disclosures)','State Department of Revenue (sales tax on rental transactions)']::text[],ARRAY['guaranteed ownership','zero interest forever','no contract','free instrument','we beat any price guaranteed','no questions asked returns','legal ownership upon first payment','no fees ever']::text[],ARRAY['Rental agreements are subject to state consumer protection and contract disclosure laws','Rent-to-own contracts may be regulated under state Rental Purchase Act statutes — terms vary by state','Truth in Lending Act (TILA) disclosures apply where rental agreements include financing components','Sales tax on rental payments versus purchase transactions varies by state — consult your tax advisor','Damage waiver is not insurance — coverage terms and exclusions apply as stated in the rental agreement','Rental credits toward purchase are subject to terms and conditions of the individual rental agreement']::text[],false,false,true,ARRAY['Must not misrepresent total cost of ownership under a rent-to-own agreement','Must disclose all fees (maintenance plan, damage waiver, administrative fees) in advertising where pricing is shown','TILA requires clear disclosure of effective APR if the rental includes a financing component','Must not imply rent-to-own is equivalent to a purchase or lease without full disclosure','State-specific Rental Purchase Act regulations may impose additional advertising disclosure requirements']::text[])
