INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:musical_instrument_repair_shop',true,'NAPBIRT Member # / Factory Authorization Certificate #',ARRAY['OSHA – Occupational Safety and Health Administration (solvent and chemical workplace safety)','EPA – Environmental Protection Agency (hazardous waste disposal of chemical dips and solvents)','CITES – Convention on International Trade in Endangered Species (protected tonewoods in antique instruments)','State Consumer Protection Agencies (written estimate requirements before repair work)']::text[],ARRAY['guaranteed to fix any instrument','certified by all manufacturers','OSHA approved shop','we guarantee your instrument will be like new']::text[],ARRAY['Written estimate provided before repair costs exceed applicable state threshold','CITES documentation required for certain antique instruments containing protected materials such as Brazilian rosewood or ivory','Chemical solvents and adhesives handled in compliance with OSHA and EPA regulations','All estimates are subject to change if additional damage is discovered during disassembly']::text[],false,false,false,ARRAY['Do not claim factory authorization for brands without current written authorization on file','Do not imply NAPBIRT certification applies to all staff unless individually certified','Consumer protection laws in most states require written estimates before work begins above a defined dollar threshold – advertising must not contradict this right','Do not use before-and-after imagery implying results typical without disclosure of instrument condition variables']::text[])
