INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:nepalese_restaurant',true,'Food Establishment License #',ARRAY['State/Local Health Department (Food Establishment Licensing Authority)','Local Alcohol Beverage Control Board (if serving tongba or alcoholic beverages)','State Food Safety and Inspection Division']::text[],ARRAY['best Nepali food in the world','guaranteed authentic','only authentic Nepalese restaurant','no allergens in our food','completely allergen-free','approved by the government of Nepal','traditional recipe certified']::text[],ARRAY['Menu items may contain nuts, gluten, or dairy — please inform your server of any allergies before ordering.','Alcohol service (including tongba) is subject to local licensing regulations and age verification requirements.','Health inspection scores are publicly available and updated following each inspection.','Catering menus may vary based on seasonal ingredient availability.']::text[],false,false,false,ARRAY['Must not claim to be the sole or exclusive source of authentic Nepalese food in any region','Allergen claims in advertising must accurately reflect actual menu composition and must not imply allergen-free status without verified testing','Alcohol-related promotions (tongba specials) must comply with state alcohol advertising regulations','Health inspection grade claims in advertising must reflect current verified scores only','Cultural or religious food claims (e.g. halal, kosher, sattvic) must be certified before use in advertising']::text[])
