INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:neurophysiologist',true,'State Medical License # | D.ABNM Credential ID',ARRAY['American Board of Neurophysiologic Monitoring (ABNM)','American Clinical Neurophysiology Society (ACNS)','Centers for Medicare and Medicaid Services (CMS)','The Joint Commission','State Medical Licensing Boards (jurisdiction-specific)','State Health Department — Clinical Neurophysiology Certification Requirements']::text[],ARRAY['guaranteed to prevent nerve damage','100% accurate neuromonitoring','eliminates risk of surgical neurological injury','better than any other neuromonitoring service','fastest response time guaranteed','our monitoring prevents all paralysis','FDA-cleared to cure or prevent neurological deficits','no patient has ever been harmed under our monitoring']::text[],ARRAY['Intraoperative neurophysiological monitoring reduces but does not eliminate the risk of neurological injury during surgery.','All monitoring services are performed under the supervision of a physician credentialed at the participating facility.','Billing for IONM services is subject to CMS guidelines; coverage varies by payer and procedure.','HIPAA-compliant data handling protocols are maintained for all intraoperative patient monitoring data.','State licensure and facility credentialing requirements vary; confirm active credentials for each jurisdiction and facility.','Remote neuromonitoring interpretation is subject to applicable state telemedicine regulations.']::text[],false,true,true,ARRAY['CMS anti-kickback statute prohibits fee-splitting arrangements with referring surgeons or facilities','Stark Law compliance required for any financial relationships with referring physicians','FTC truth-in-advertising rules apply to outcome claims and case volume statistics','State medical board advertising rules prohibit misleading specialty claims without board certification','CMS prohibits billing both the professional and technical component of IONM without appropriate modifier distinction','ACNS and ASNM ethical guidelines restrict testimonial advertising that implies guaranteed surgical outcomes']::text[])
