INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:nuclear_power_plant',true,'NRC Reactor Operating License #',ARRAY['U.S. Nuclear Regulatory Commission (NRC) — 10 CFR Part 50','U.S. Nuclear Regulatory Commission (NRC) — 10 CFR Part 55 Operator Licensing','U.S. Nuclear Regulatory Commission (NRC) — 10 CFR Part 73 Physical Security','U.S. Nuclear Regulatory Commission (NRC) — 10 CFR Part 26 Fitness for Duty','Federal Emergency Management Agency (FEMA) — Radiological Emergency Preparedness Program','U.S. Environmental Protection Agency (EPA) — Radiological Environmental Monitoring','Occupational Safety and Health Administration (OSHA) — 29 CFR 1910.1096 Ionizing Radiation','State Public Utilities Commission (jurisdiction-specific)','State Radiation Control Program (jurisdiction-specific)','Institute of Nuclear Power Operations (INPO) — Performance Standards']::text[],ARRAY['zero radiation risk','completely safe from all radiation','no radioactive releases ever','safer than your dentist''s X-ray (comparative minimization)','no risk to drinking water','government-approved clean','approved by the community','100% accident-proof','no impact on local environment','radiation levels are harmless']::text[],ARRAY['This facility operates under an NRC Reactor Operating License subject to ongoing regulatory oversight and inspection.','Radiological environmental monitoring results are reported annually to the NRC and publicly available via ADAMS.','Emergency planning information for residents within the 10-mile Emergency Planning Zone is distributed annually and available upon request.','All radiation dose rates reported are in compliance with NRC 10 CFR Part 20 occupational and public dose limits.','Spent nuclear fuel is stored on-site in NRC-licensed storage systems pending availability of a federal repository.','Nuclear plant operations are regulated by the U.S. Nuclear Regulatory Commission; safety concerns may be reported directly to the NRC at 1-800-695-7403.']::text[],false,false,false,ARRAY['Cannot claim NRC endorsement of safety performance beyond license-in-good-standing status','Cannot use NRC inspection ratings in advertising without full context and source citation','Cannot make comparative radiation safety claims that minimize or trivialize radiological risk','Must not represent emergency planning zones as guarantees of safety rather than preparedness zones','Environmental monitoring data must reference official REMP report context when cited publicly','Workforce qualification claims must be consistent with current NRC-licensed operator roster','Cannot imply INPO or WANO evaluation scores represent government regulatory approval']::text[])
