INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:obstetrics_gynecology_clinic',true,'State Medical License # | NPI #',ARRAY['American Board of Obstetrics and Gynecology (ABOG)','State Medical Board (jurisdiction-specific)','Centers for Medicare and Medicaid Services (CMS)','The Joint Commission (TJC)','U.S. Department of Health and Human Services — Office for Civil Rights (HIPAA enforcement)','State Department of Health (facility licensure)']::text[],ARRAY['guaranteed safe pregnancy outcome','we will cure your endometriosis','100% effective birth control','pain-free procedure guaranteed','best OB-GYN in the country','no-risk surgery','we guarantee a healthy baby','fastest delivery in the area']::text[],ARRAY['Individual patient outcomes may vary. This content is for informational purposes only and does not constitute medical advice.','HIPAA Notice of Privacy Practices available upon request and posted in clinic.','Informed consent is required before all procedures. Patients have the right to refuse or withdraw consent.','This clinic complies with applicable state reproductive health statutes. Services offered may vary by jurisdiction.','Mandatory reporting of certain communicable diseases is required by law.','Medicare and Medicaid patients: Clinic participation status should be verified prior to scheduling.','Telehealth services are subject to state licensure requirements and may not be available in all locations.']::text[],false,true,true,ARRAY['No claims of guaranteed pregnancy outcomes or fertility success rates without supporting clinical evidence','Hormone therapy advertising must include balanced risk-benefit disclosure per FDA guidance','Any price or fee advertising must comply with state fee-splitting and anti-kickback statutes','Social media content involving patient images requires explicit written HIPAA-compliant authorization','Physician claims such as ''best'' or ''top-rated'' require substantiation and may violate state medical board advertising rules','Testimonials must include disclaimer that results are not typical','No advertising of services that are not actually offered or that misrepresent scope of practice']::text[])
