INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:office_supply_wholesaler',true,'GSA Schedule Contract #',ARRAY['U.S. General Services Administration (GSA)','Environmental Protection Agency (EPA)','Occupational Safety and Health Administration (OSHA)','Federal Trade Commission (FTC)','State Revenue/Tax Authorities (Resale Certificate Compliance)']::text[],ARRAY['lowest price guaranteed on all wholesale orders','all products made in USA','all products contain recycled content','EPA certified products across full catalog','government-approved supplier for all agencies','tax-free for all customers']::text[],ARRAY['GSA Schedule pricing available only to eligible federal, state, and local government entities under applicable ordering procedures.','EPA Safer Choice designation applies only to specific qualifying products; not all distributed products carry this certification.','Safety Data Sheets (SDS) are available for all regulated chemical products distributed under OSHA HazCom 29 CFR 1910.1200.','Tax-exempt transactions require a valid state resale certificate or exemption documentation on file prior to order processing.','Recycled content and Made-in-USA claims apply only to products where verified by manufacturer documentation; FTC Green Guides compliance required.','Net 30 credit terms are subject to credit approval and are not guaranteed for all applicants.']::text[],false,false,false,ARRAY['FTC Green Guides: recycled content and environmental benefit claims must be substantiated and specific to individual products, not categorical','FTC Made-in-USA Rule: all-or-virtually-all standard applies; unqualified USA origin claims prohibited without compliance verification','GSA pricing claims must not imply universal government eligibility or misrepresent schedule terms','Net 30 and credit term offers must not be used as guaranteed marketing claims without credit approval disclosure','OSHA HazCom: SDS availability must be disclosed for any distributed chemical or cleaning products in advertising']::text[])
