INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:oil_refinery',true,'Title V Operating Permit # | EPA Facility ID',ARRAY['U.S. Environmental Protection Agency (EPA) — Clean Air Act MACT and NSPS','EPA Office of Transportation and Air Quality — Renewable Fuel Standard','EPA Office of Emergency Management — SPCC and CERCLA','Occupational Safety and Health Administration (OSHA) — Process Safety Management 29 CFR 1910.119','State Air Quality Management Districts and Environmental Agencies','U.S. Department of Transportation Pipeline and Hazardous Materials Safety Administration (PHMSA)','ASTM International (product quality specifications)','American Petroleum Institute (API) (industry standards and RP compliance)']::text[],ARRAY['zero emissions refinery','perfectly safe operation','no environmental impact','fully carbon-neutral petroleum production','guaranteed no spill risk','EPA-approved without qualification','no hazardous materials on site','cleanest refinery in the country']::text[],ARRAY['This facility operates under a Title V Operating Permit issued by the applicable state air quality agency and is subject to EPA MACT standards under 40 CFR Part 63.','Renewable Identification Numbers (RINs) are generated and reported under EPA Renewable Fuel Standard obligations; RIN claims are subject to EPA verification.','This facility maintains an SPCC Plan as required by 40 CFR Part 112 to prevent oil spills from reaching navigable waters.','Emissions data reported to EPA under the Greenhouse Gas Reporting Program (40 CFR Part 98) are publicly available via EPA GHGRP.','OSHA Process Safety Management requirements (29 CFR 1910.119) govern handling of highly hazardous chemicals at this facility.','CERCLA Section 103 requires immediate notification to the National Response Center for hazardous substance releases above reportable quantities.']::text[],false,false,false,ARRAY['Cannot claim specific emissions reduction percentages without EPA-verified data','Cannot claim RFS compliance status without current EPA registration','Cannot advertise fuel specifications without current ASTM test certification','Cannot use terms implying environmental endorsement by EPA without formal recognition','Product quality claims must be backed by current ASTM laboratory accreditation','Safety award claims must reference the issuing organization and award year']::text[])
