INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:orchestra',true,'ASCAP License # | BMI License # | AFM Local #',ARRAY['American Society of Composers Authors and Publishers (ASCAP)','Broadcast Music Inc. (BMI)','American Federation of Musicians (AFM)','League of American Orchestras','Internal Revenue Service (IRS) — 501c3 nonprofit compliance','State Attorney General Charitable Trust Division','Local Fire Marshal — venue occupancy compliance','Americans with Disabilities Act (ADA) — venue accessibility enforcement']::text[],ARRAY['Grammy Award-winning orchestra','#1 orchestra in the country','guaranteed refunds on all tickets','fully licensed to perform any music without restriction','performing royalty-free classical music']::text[],ARRAY['All performed works are licensed under ASCAP and/or BMI performing rights agreements','The orchestra is a 501c3 nonprofit organization; donations may be tax-deductible to the extent permitted by law','Concert programs and guest artists are subject to change','Venue is subject to fire marshal occupancy limits; ticket quantities are limited','Youth performer programs comply with applicable child labor regulations','ADA-accessible seating is available; contact the box office for accommodation requests']::text[],false,false,false,ARRAY['Cannot claim exclusive performing rights to public domain works without qualification','Must not imply government endorsement unless a formal grant is cited with specificity','Ticket refund and exchange policies must be disclosed at point of sale per consumer protection guidelines','AFM collective bargaining agreement terms cannot be publicly misrepresented in promotional materials','Nonprofit status cannot be used to imply charitable donation status for ticket purchases']::text[])
