INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:organic_store',true,'State Retail Business License #',ARRAY['USDA National Organic Program (NOP)','Federal Trade Commission (FTC) Green Guides','U.S. Consumer Product Safety Commission (CPSC)','Leaping Bunny Program (Cruelty Free International)','ECOCERT / COSMOS Standard','B Lab (B Corporation Certification Body)','State Department of Revenue (Sales Tax Compliance)','EU Cosmetics Regulation Authority (for imported personal care products)']::text[],ARRAY['100% natural with no qualifications','chemical-free','completely safe for all users','government-approved organic formula','clinically proven detox','pesticide-free guaranteed','non-toxic certified by us','environmentally friendly (unqualified claim without substantiation)']::text[],ARRAY['USDA Organic claims apply only to products certified under the National Organic Program; individual product certifications vary','Environmental marketing claims comply with FTC Green Guides; substantiation available upon request','Cruelty-free designation applies only to brands carrying current Leaping Bunny certification; verify at LB directory','Products for children comply with applicable CPSC safety standards; consult product labeling for age suitability','Imported organic personal care products comply with EU Cosmetics Regulation where applicable','B Corporation certification applies to the retail entity; individual supplier B Corp status varies','Zero-waste refill station contents verified organic/eco-certified by supplier documentation','This store does not provide medical, nutritional, or veterinary advice; consult qualified professionals']::text[],false,false,false,ARRAY['Must not make unqualified organic claims for non-USDA-certified products','Must not use terms like chemical-free or toxin-free as absolute claims per FTC Green Guides','Must not imply government endorsement of store environmental practices','Cruelty-free and Leaping Bunny marks may only be used for currently certified brands','B Corp logo usage governed by B Lab brand guidelines and licensing terms','ECOCERT and COSMOS marks require current certification documentation before use in advertising','Children product marketing must not make unsubstantiated safety superiority claims','Biodegradable claims must specify conditions under which biodegradation occurs per FTC guidance']::text[])
