INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:orthodox_church',true,'IRS 501(c)(3) EIN: XX-XXXXXXX | State Nonprofit Registration #',ARRAY['Internal Revenue Service (IRS) — 501(c)(3) tax-exempt status','State Attorney General Charitable Trust Division — nonprofit governance','Assembly of Canonical Orthodox Bishops of the USA — canonical oversight','Relevant Orthodox Jurisdiction (Archdiocese/Metropolis/Diocese) — ecclesiastical authority','Local Municipal Zoning Board — religious assembly property use']::text[],ARRAY['Guaranteed salvation','We are the one true Church exclusively','Endorsed by [politician or political party]','Certified therapist or licensed counselor on staff (unless separately licensed)','Non-denominational Orthodox','We accept all communion regardless of canonical membership']::text[],ARRAY['Holy Communion is administered only to canonically Orthodox Christians in good standing','Inquirers and catechumens are warmly welcomed to attend services but are dismissed before the Liturgy of the Faithful','All clergy are canonically ordained within a recognized Orthodox jurisdiction under the Assembly of Canonical Orthodox Bishops of the USA','Youth programs operate under a diocesan-approved Safe Church policy; all staff working with minors are background-checked','This parish is a registered 501(c)(3) nonprofit religious organization; donations may be tax-deductible to the extent permitted by law','Marriage ceremonies are performed in accordance with Orthodox canonical requirements; please contact the priest to discuss eligibility']::text[],false,false,false,ARRAY['Must not imply canonical legitimacy of non-canonical Orthodox groups','Must not use political endorsement language in any advertising or social media','Must not advertise sacraments as open to all regardless of canonical standing without disclaimer','Must not make therapeutic or psychological health claims for spiritual counseling without licensed-provider disclosure','Charitable fundraising advertising must comply with state charitable solicitation registration requirements where applicable']::text[])
