INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:painter',true,'State Contractor License #',ARRAY['State Contractor Licensing Board (jurisdiction-specific, e.g. CSLB in California, DPOR in Virginia)','U.S. Environmental Protection Agency (EPA) — RRP Rule enforcement','Occupational Safety and Health Administration (OSHA) — ladder, scaffold, and hazmat safety','Local Municipal Business Licensing Authority']::text[],ARRAY['guaranteed lowest price','EPA certified (without specifying RRP Firm certification)','fully licensed (without displaying actual license number)','we remove all lead paint (abatement without proper licensure claim)','non-toxic paint (without verified low-VOC product specification)','best painter in [city] (unsubstantiated superlative)']::text[],ARRAY['State contractor license number must be displayed on all contracts, proposals, and advertising per state law','EPA RRP certification number and firm name must be provided to clients prior to disturbing painted surfaces in pre-1978 structures','Proof of general liability and workers compensation insurance available upon request','All pricing estimates are non-binding until a written contract is executed','Lead paint work performed under EPA RRP Rule 40 CFR Part 745 compliance protocols']::text[],false,false,false,ARRAY['Cannot claim EPA lead-safe certification without current EPA RRP Firm certification on file','Cannot advertise as licensed contractor in jurisdictions where license has lapsed or is pending renewal','Cannot guarantee color match outcomes in advertising without qualifying language','OSHA safety compliance claims must reflect actual current training certifications of crew','Superlative claims (e.g. #1 painter) require substantiation with verifiable third-party source']::text[])
