INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:paisa_restaurant',true,'Health Permit # / Liquor License #',ARRAY['Local/County Health Department','State Alcoholic Beverage Control Board','Local Fire Marshal (occupancy limits)']::text[],ARRAY['Best Colombian food in the world','Certified authentic by the Colombian government','All-natural ingredients with no allergens','Medically approved cuisine','Award-winning without verifiable citation','Guaranteed freshest ingredients']::text[],ARRAY['Menu items may contain allergens including gluten, dairy, shellfish, and tree nuts — please notify staff of dietary restrictions','Alcohol service subject to valid state liquor license; ID required for all alcohol purchases','Occupancy limits posted per local fire code and strictly enforced','Health department inspection reports available upon request']::text[],true,false,false,ARRAY['Cannot advertise alcohol service without including jurisdiction-required alcohol responsibility messaging','Must not imply health department endorsement beyond displaying inspection grade','Food allergen claims in advertising must align with actual menu ingredient disclosures','Catering advertisements must not guarantee specific staffing ratios without contractual backing']::text[])
