INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:pet_microchip_scanning_station',true,'State Animal Shelter / Animal Control Permit #',ARRAY['USDA Animal and Plant Health Inspection Service (APHIS) — Animal Welfare Act','State Veterinary Medical Board (where scanning is co-located with licensed vet facility)','State Department of Agriculture — Animal Industry Division (shelter licensing)','Local Municipal Animal Control Authority','American Animal Hospital Association (AAHA) — voluntary accreditation']::text[],ARRAY['Guaranteed to find your pet''s owner','We implant microchips','Your pet is definitely microchipped','We can access all registries instantly','Microchip guarantees return of your pet','Government-mandated reunification service']::text[],ARRAY['Microchip scanning is free and does not include implantation services. For implantation, please contact a licensed veterinarian.','A microchip number is only useful if registered in a searchable database. Registration is a separate step from implantation.','Pet owner contact information from registry lookups is handled in accordance with applicable privacy regulations and registry terms of service.','Scanning stations affiliated with animal shelters may be subject to state laws requiring microchip scanning before euthanasia of stray animals.','Results of a registry lookup depend on whether the pet''s owner completed registration with a participating registry. Unregistered chips may return no owner information.']::text[],false,false,false,ARRAY['Must not imply that scanning station provides veterinary medical services or diagnosis','Must not claim to access registries in real-time without verifying current system integrations','Must not use found pet owner personal information for any purpose other than reunification','Must not advertise guaranteed reunification outcomes','Social media posts featuring found pets must comply with applicable shelter hold period requirements before public disclosure of owner identity']::text[])
