INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:pet_trainer',true,'CPDT-KA Certificate # | CBCC-KA Certificate # (where applicable)',ARRAY['Certification Council for Professional Dog Trainers (CCPDT)','International Association of Animal Behavior Consultants (IAABC)','American Kennel Club (AKC) for CGC Evaluator authorization','U.S. Department of Justice (ADA) for service dog task training guidelines','Local municipality animal services for boarding permits']::text[],ARRAY['guaranteed results in X days','we cure aggression','certified by the government','licensed behaviorist (without veterinary behaviorist credentials)','we can certify your dog as a service animal','100% success rate','punishment-free means no consequences','we use alpha/dominance techniques to fix your dog']::text[],ARRAY['Certification through CCPDT is voluntary; no federal licensure is required for dog trainers in the United States.','Trainer is not a licensed veterinary behaviorist; dogs with severe aggression or suspected neurological issues should be evaluated by a veterinarian.','Service dog task training complies with ADA guidelines; trainer does not issue legal service animal certifications or ID cards.','Board-and-train facilities operating overnight animal boarding may require local animal boarding permits per municipal code.','Liability waivers are required prior to handling client animals.','Individual training results vary based on dog temperament, owner consistency, and behavior history.']::text[],false,false,false,ARRAY['Must not claim government licensure or certification that does not exist at the federal level','Must not guarantee specific behavioral outcomes within a fixed timeframe','Must not imply ability to legally certify emotional support animals or psychiatric service dogs','Must not use misleading dominance or alpha-based framing in advertising claims','AKC CGC evaluator status must not be represented as a general government accreditation','Service dog training advertising must not imply issuance of legal service animal documentation']::text[])
