INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:piano_repair_service',true,'RPT Certification # (Piano Technicians Guild)',ARRAY['Piano Technicians Guild (PTG) — Registered Piano Technician credential body','U.S. Environmental Protection Agency (EPA) — solvent and chemical disposal regulations','Occupational Safety and Health Administration (OSHA) — shop workplace safety standards','State consumer protection agencies — written repair estimate disclosure requirements']::text[],ARRAY['Guaranteed to restore original factory tone','We are the only certified piano technician in [city]','Our repairs come with a lifetime guarantee','Manufacturer-authorised service centre (unless formally authorised)']::text[],ARRAY['Written repair estimates must be provided before work commences in states with consumer protection requirements','Disposal of chemical solvents and finishing compounds must comply with applicable EPA and local hazardous waste regulations','RPT designation is granted by the Piano Technicians Guild and does not constitute a government-issued professional licence','Results of restoration may vary depending on instrument age, prior damage history, and wood condition']::text[],false,false,false,ARRAY['Do not claim manufacturer authorisation (e.g. Steinway Authorised) without documented manufacturer relationship','Do not use before/after testimonials that imply guaranteed outcomes','Avoid superlative claims (e.g. best piano technician) without substantiation','Ensure all advertised price ranges reflect actual service cost floors and are not misleading under FTC guidelines']::text[])
