INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:plant_nursery',true,'UK Plant Passport Operator Registration No.',ARRAY['Animal and Plant Health Agency (APHA)','UK Health and Safety Executive (HSE) — pesticide regulation','Environment Agency — water abstraction licensing','Trading Standards — plant labelling and consumer protection','Defra — Invasive Alien Species Regulation enforcement']::text[],ARRAY['100% guaranteed to grow','completely pest and disease free','safe for all wildlife regardless of placement','approved for all soil types without amendment','guaranteed to survive all UK winters','pesticide-free nursery (unless certified organic)']::text[],ARRAY['Plants are subject to seasonal availability and may differ from images shown','Plant passports are required for the movement of regulated plant species — customers must comply with applicable restrictions','Pesticide products are only sold to certified users where required by law','Invasive non-native species are not stocked in compliance with the Invasive Alien Species (Enforcement and Permitting) Order 2019','All plant prices are inclusive of VAT at the applicable rate','Mail order plants are dispatched at the optimal time for the species — delivery dates may vary by season']::text[],false,false,false,ARRAY['Must not claim plants are free from all pests or diseases','Must not imply phytosanitary certification is a guarantee of plant health post-purchase','Cannot advertise restricted invasive species for sale','Pesticide product advertising must comply with HSE and CRD regulations','Plant passport labelling must comply with The Plant Health (Amendment etc.) (EU Exit) Regulations 2020','Must not make misleading claims about hardiness ratings outside USDA/RHS zone definitions']::text[])
