INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:portrait_studio',false,NULL,ARRAY['U.S. Copyright Office (Copyright Act of 1976 — image ownership and print release obligations)','Federal Trade Commission (FTC) — testimonial and endorsement disclosure rules','California Privacy Protection Agency (CPPA) — CCPA compliance for client image data','EU Data Protection Authorities — GDPR compliance for international client data','State-level child protection statutes — minor photography consent and model release requirements by jurisdiction']::text[],ARRAY['Guaranteed best photos in town','Award-winning — unless specific named award is cited and verifiable','Professional photographer — without credentials or verifiable portfolio evidence if used as a superlative claim','Your images are fully owned by you — without a print release document and copyright assignment agreement','We own the copyright unless client contract specifies otherwise — must be explicitly disclosed']::text[],ARRAY['Copyright in photographs is retained by the photographer unless explicitly assigned in writing per the U.S. Copyright Act','A signed model release or parental/guardian consent form is required for photography of minors and for any commercial use of images','Client image data including gallery access information is stored in compliance with applicable data privacy laws including CCPA and GDPR','Background music used in slideshow or video products must be properly licensed; unlicensed use of copyrighted music is prohibited','Print release terms including permitted uses (personal printing, social media, etc.) must be disclosed to clients prior to session booking']::text[],false,false,false,ARRAY['FTC requires clear disclosure when reviews or testimonials are incentivized or given by clients who received discounted sessions','Before-and-after retouching comparisons must not imply medical or physical transformation outcomes','Images of minors must not be used in advertising without documented parental or guardian consent','Competitive comparison advertising (e.g. ''better than Studio X'') must be factually substantiated','Session pricing advertised must reflect all mandatory fees; session fee and print minimums must not be concealed in fine print']::text[])
