INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:portuguese_restaurant',true,'Liquor License # | Health Permit #',ARRAY['State Alcoholic Beverages Control Board','Local Health Department / Public Health Authority','National Restaurant Association (ServSafe)','Americans with Disabilities Act (ADA) Enforcement via DOJ']::text[],ARRAY['best restaurant in the world','award-winning cuisine (without verifiable award citation)','guaranteed freshest ingredients','no allergens present','100% gluten-free kitchen','certified organic (without USDA certification)','Michelin-starred (without Michelin citation)']::text[],ARRAY['Menu items may contain allergens including nuts, shellfish, gluten, dairy, and eggs — please inform your server of any dietary restrictions.','Wine and spirits service is available to guests 21 years of age or older. Valid ID required.','Health inspection grade is posted at the restaurant entrance as required by local health authority.','Catering and private event pricing subject to change; final pricing confirmed upon signed contract.']::text[],true,false,false,ARRAY['Alcohol advertising must comply with state alcoholic beverages control board regulations and must not target underage audiences','Health and safety claims must be substantiated by current health inspection records','Award and accolade claims must reference specific verifiable awards with dates','Allergen-safe claims require documented kitchen protocols and cannot be absolute guarantees']::text[])
