INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:producteur_de_foie_gras',true,'Prefectoral Authorization No. / Numéro d''agrément préfectoral',ARRAY['Direction Départementale de la Protection des Populations (DDPP)','Institut National de l''Origine et de la Qualité (INAO)','Comité Interprofessionnel du Foie Gras (CIFOG)','European Food Safety Authority (EFSA) — EU Regulation 1099/2009 on animal protection at time of killing','Direction Générale de l''Alimentation (DGAL) — French Ministry of Agriculture']::text[],ARRAY['cruelty-free foie gras','humane force-feeding','foie gras certified organic','guaranteed pain-free gavage','foie gras with no animal welfare concerns','no regulatory restrictions apply']::text[],ARRAY['Foie gras production is regulated under EU Council Directive 98/58/EC and national French law. This farm operates under a valid prefectoral authorization.','Product origin and traceability are guaranteed under French law. IGP and Label Rouge designations are awarded and monitored by INAO and the relevant certification body.','Cold chain integrity is the responsibility of the carrier once the parcel leaves the farm. Consumers should verify temperature on receipt.','Force-feeding (gavage) is a regulated practice under French agricultural law and is subject to veterinary oversight.']::text[],false,false,false,ARRAY['Must not imply EU-wide legal equivalence for force-feeding practices — regulations vary by member state','Cannot claim ''organic'' or ''bio'' status without certified AB label','Cannot use ''AOC'' designation without active INAO certification','Must display origin labeling (département of production) on all retail packaging per French law','Online shipping advertising must reference cold chain compliance and delivery time limits for perishable goods','Cannot claim ''ethical'' or ''humane'' production as an absolute claim without qualified context']::text[])
