INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:professional_organizer',true,'Business License # (State/Municipality)',ARRAY['NAPO Board of Certification (CPO credential)','Institute for Challenging Disorganization (ICD specialist credential)','KonMari Media Inc. (KonMari Consultant certification)','State and local business licensing authorities (varies by jurisdiction)','Local waste management and disposal regulatory bodies']::text[],ARRAY['Guaranteed to cure hoarding disorder','Licensed mental health professional','Therapy or counseling services','We are bonded and insured (unless verified)','Eliminate clutter permanently','Results guaranteed']::text[],ARRAY['Professional organizing is not a substitute for licensed mental health treatment. Hoarding disorder cases may require coordination with a licensed therapist or psychologist.','Disposal and donation of client items follows applicable local waste management regulations and client-approved disposal plans.','Client privacy and confidentiality is maintained under a signed agreement. Items, photos, and project details are not shared without written client consent.','Business licensing requirements vary by state and municipality. License status is verified at the local level.','CPO credential is awarded and maintained by the NAPO Board of Certification and requires ongoing continuing education hours for renewal.']::text[],false,false,false,ARRAY['Do not claim licensure as a mental health professional or therapist','Do not guarantee specific decluttering outcomes or permanent results','Do not advertise disposal services that conflict with local waste ordinances','Do not use before/after photos of client spaces without written client consent','Do not misrepresent credential status — only use CPO title if actively certified by NAPO Board of Certification']::text[])
