INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:promotional_products_supplier',false,NULL,ARRAY['U.S. Consumer Product Safety Commission (CPSC) — CPSIA enforcement','California Office of Environmental Health Hazard Assessment (OEHHA) — Prop 65','U.S. Copyright Office and USPTO — trademark and copyright for licensed logos','PPAI (Promotional Products Association International) — voluntary Code of Ethics']::text[],ARRAY['guaranteed safe for all ages without CPSIA testing documentation','Prop 65 warning-free for all California shipments','licensed logo reproduction without trademark clearance','100% brand color match guaranteed without PMS specification confirmation']::text[],ARRAY['Items distributed to children may require CPSIA third-party testing and a Children''s Product Certificate (CPC). Ask your account representative for compliance documentation.','Products containing certain chemicals shipped to California may require Prop 65 warnings. We will notify you if your order triggers this requirement.','Use of licensed, trademarked, or copyrighted logos requires clearance from the rights holder. Client assumes responsibility for providing authorization documentation.','Digital proofs are for color and layout approval only; slight variations may occur in final production due to substrate and imprint method differences.']::text[],false,false,false,ARRAY['Do not claim CPSIA compliance for specific products without product-level test documentation','Do not guarantee exact Pantone or PMS color reproduction on all substrates without qualification','Do not advertise use of licensed or trademarked logos without confirming client authorization','Do not imply Prop 65 exemption without reviewing the specific materials in the order','Eco-friendly or sustainable claims must be substantiated by specific material or certification evidence — avoid vague greenwashing language']::text[])
