INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:protected_area',true,'Federal/State Permit Authorization #',ARRAY['National Park Service (NPS)','US Fish and Wildlife Service (USFWS)','Bureau of Land Management (BLM)','US Army Corps of Engineers (Clean Water Act Section 404)','US Environmental Protection Agency (Clean Water Act)','State Department of Natural Resources (DNR)','Land Trust Alliance (Accreditation)','National Association for Interpretation (CIG Certification)']::text[],ARRAY['guaranteed wildlife sighting','no permit required','open 24 hours year-round','no restrictions apply','fully off-road accessible','hunting permitted','no Leave No Trace rules here','commercial activity freely allowed']::text[],ARRAY['All backcountry and commercial activities require a valid permit issued by the managing agency prior to entry.','Visitors must comply with Leave No Trace principles as adopted in area regulations.','Endangered and threatened species protections under the Endangered Species Act are enforced within protected boundaries.','Commercial photography and filming require prior written permit approval; unauthorized commercial use is prohibited.','Seasonal area closures may apply for wildlife nesting, fire conditions, or resource protection — check current conditions before visiting.','All land use decisions are subject to National Environmental Policy Act review requirements.','Activities near waterways are subject to Clean Water Act compliance requirements.','Visitor facilities are required to meet ADA accessibility standards — contact the visitor center for specific accommodations.']::text[],false,false,false,ARRAY['Cannot advertise hunting or trapping activities within protected boundaries','Cannot imply permit-free commercial access','Cannot guarantee wildlife encounters in promotional materials','Cannot advertise motorized off-road vehicle access where prohibited','Must include permit requirement disclosures in all commercial activity promotions','Ranger certification and staff credentials must not be misrepresented in marketing materials']::text[])
