INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:pueblan_restaurant',true,'Food Service Establishment Permit #',ARRAY['Local Health Department (food service establishment permit and inspection grading)','State Alcoholic Beverage Control Board (mezcal, pulque, and agave spirit service license)','Local Fire Marshal (occupancy and fire safety certificate for dining room and event space)','State or County Food Safety Authority (food handler certification for kitchen staff)']::text[],ARRAY['#1 Mexican restaurant in [city]','Guaranteed authentic Pueblan recipe','The only real mole in [city]','Award-winning chef']::text[],ARRAY['Health inspection grade must be visibly posted on premises and disclosed upon request','Allergen notice: nogada sauce contains walnuts (tree nuts); available upon request for all dishes','Alcohol service available only to guests 21+ (or applicable local legal drinking age); valid ID required','Chiles en nogada is a seasonal dish; availability subject to ingredient sourcing from Puebla region producers']::text[],true,false,false,ARRAY['Alcohol advertising must comply with state and local beverage control authority regulations and cannot target minors','Health or nutritional claims about menu items must be substantiated and comply with FTC and FDA guidelines where applicable','''Authentic'' and ''traditional'' claims should be qualified by sourcing or institutional recognition to avoid deceptive advertising findings','Seasonal dish availability claims in advertising must be accurate and updated to reflect current menu status']::text[])
