INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:radiator_shop',true,'State Automotive Repair Facility License #',ARRAY['State Bureau of Automotive Repair (BAR) or equivalent state automotive repair licensing authority','U.S. Environmental Protection Agency (EPA) — coolant recycling and hazardous waste disposal','Occupational Safety and Health Administration (OSHA) — metalworking and welding shop safety standards','State Attorney General Consumer Protection Division — pricing transparency and repair authorization','National Automotive Radiator Service Association (NARSA) — voluntary industry standards body']::text[],ARRAY['guaranteed lowest price','factory authorized repair','OEM certified repair','lifetime guarantee on all radiators']::text[],ARRAY['Prices are estimates only; final cost may vary based on inspection findings. Written authorization required before repairs begin per state consumer protection law.','Used coolant is recycled or disposed of in compliance with EPA regulations. Documentation available upon request.','ASE certification applies to individual technicians and does not imply endorsement by ASE of the business entity.','NARSA membership is a voluntary industry association and does not constitute a government license or guarantee of work quality.','Hazardous materials including used coolant and metalworking byproducts are handled in compliance with applicable state and federal hazardous waste regulations.']::text[],false,false,false,ARRAY['Must not advertise EPA certification without verified documentation of compliant coolant disposal program','Must not claim ASE certification for the shop as an entity; certification is individual technician-level','Must not guarantee repair outcomes on corroded or severely damaged radiators without inspection caveat','Pricing advertised must reflect actual available pricing per state consumer protection and pricing transparency laws','Must not use misleading before/after comparisons without verified documentation of the specific work performed']::text[])
