INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:rare_book_store',true,'ABAA Member # | ASA Credential #',ARRAY['Antiquarian Booksellers Association of America (ABAA) — voluntary trade self-regulation and ethics code','International League of Antiquarian Booksellers (ILAB) — international trade ethics standards','American Society of Appraisers (ASA) — appraiser credentialing and ethics','Internal Revenue Service (IRS) — qualified appraisal standards under Treasury Reg. 1.170A-17 and Rev. Proc. 66-49','U.S. Fish and Wildlife Service — CITES enforcement for books with protected animal-derived materials','State tax authorities — sales tax collection compliance','State consumer protection agencies — authenticity representation standards']::text[],ARRAY['guaranteed investment return on rare books','certified authentic by [store name]','IRS-approved appraisal','appraise for any value you need','museum quality guaranteed','authenticates all signatures without independent verification']::text[],ARRAY['Appraisals are opinions of value based on market evidence at the time of the appraisal and do not guarantee sale price.','IRS qualified appraisals for charitable donations must meet Treasury Regulation 1.170A-17 requirements; consult a tax advisor.','Books containing binding materials derived from protected species may be subject to CITES import/export restrictions.','Condition descriptions follow standard antiquarian trade terminology (Fine, Very Good, Good, Fair, Poor); buyers should request additional photographs for high-value purchases.','State sales tax is collected in applicable jurisdictions; remote buyers are responsible for any applicable use tax in their jurisdiction.','ABAA membership does not constitute a government license but indicates adherence to the Association''s voluntary code of ethics.']::text[],false,false,true,ARRAY['Must not claim appraisal values without qualified appraiser credentials','Must not guarantee authenticity of signatures without third-party authentication documentation','Must not imply IRS endorsement of appraisal services','Must not advertise CITES-restricted materials for export without required permits','Condition claims in advertising must use recognized trade grading standards and be consistent with actual item condition','Cannot use ''investment advice'' framing without appropriate financial advisory disclosures']::text[])
