INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:record_company',false,NULL,ARRAY['Copyright Royalty Board (CRB)','SoundExchange','Recording Industry Association of America (RIAA)','American Society of Composers Authors and Publishers (ASCAP)','Broadcast Music Inc (BMI)','SESAC','Federal Trade Commission (FTC) — truth-in-lending for advance structures','California Consumer Privacy Act (CCPA) enforcement authority','EU General Data Protection Regulation (GDPR) supervisory authorities']::text[],ARRAY['guaranteed record deal','guaranteed Billboard chart placement','we will make you famous','#1 hit guarantee','risk-free advance','no recoupment required','we own nothing of your music','sign today and keep all your royalties']::text[],ARRAY['Advances are recoupable against future royalty earnings; artists should review recoupment terms carefully before signing','Mechanical royalty rates are set by the Copyright Royalty Board and may be updated periodically; label contracts must reflect current statutory rates','Digital performance royalties for sound recordings are collected by SoundExchange; artists and labels must register separately to receive their respective shares','This label collects and processes artist and fan personal data subject to GDPR and CCPA; a privacy policy is required and must be made available','Truth-in-lending disclosures are required when any advance is structured as a loan instrument under applicable state or federal law','Recording contracts are legally binding agreements; artists are encouraged to seek independent legal counsel before signing']::text[],false,false,true,ARRAY['Cannot guarantee chart performance or streaming numbers in promotional materials','Cannot describe royalty advances as ''free money'' or omit recoupment terms in any artist-facing advertising','FTC endorsement guidelines require disclosure when artist testimonials involve compensated relationships','Sync licensing fees quoted in advertising must be accurate and not misleading to music supervisors or buyers','CCPA and GDPR require opt-in consent for email marketing to EU and California residents']::text[])
