INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:refrigerator_store',false,NULL,ARRAY['U.S. Environmental Protection Agency – Energy Star Program','Federal Trade Commission – Energy Guide Labeling Rule (16 CFR Part 305)','Consumer Financial Protection Bureau – Truth in Lending Act (Regulation Z)','State Sales Tax Authorities','State Environmental Agencies – Appliance Recycling Regulations','U.S. Department of Justice – ADA Title III Retail Compliance']::text[],ARRAY['Guaranteed lowest price','We beat any competitor price guaranteed','Interest-free financing (without full TILA disclosure)','EPA approved (store-level claim)','Certified energy savings of X% (without verified data)','All refrigerants are eco-friendly']::text[],ARRAY['Energy Guide labels must be displayed on all applicable refrigerators per FTC 16 CFR Part 305','Financing offers must include APR, terms, and required TILA disclosures at point of sale','Haul-away and recycling of old appliances must comply with applicable state environmental regulations','Sales tax collected and remitted in accordance with applicable state laws','Extended warranty and protection plan terms and exclusions must be disclosed to buyers prior to purchase']::text[],false,false,true,ARRAY['All advertised financing terms must comply with Regulation Z trigger term disclosure requirements','Energy Star claims in advertising must apply only to EPA-certified models','Energy Guide estimated annual operating cost figures must not be modified or misrepresented in ads','Price advertising must reflect final price or clearly disclose exclusions and conditions']::text[])
