INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:reiki_therapist',false,NULL,ARRAY['Federal Trade Commission (FTC) — health benefit claims in advertising','International Association of Reiki Professionals (IARP) — voluntary professional code of ethics','National Center for Complementary and Integrative Health (NCCIH) — research and guidance body','State consumer protection agencies — unlicensed healthcare practice oversight']::text[],ARRAY['Reiki treats [any named medical condition]','Reiki cures cancer','Reiki diagnoses illness','Reiki is a substitute for medical treatment','Reiki prescribes or replaces medication','Clinically proven to heal','Guaranteed results from Reiki','Reiki heals disease']::text[],ARRAY['Reiki is a complementary wellness practice and is not a substitute for professional medical care, diagnosis, or treatment.','Reiki practitioners are not licensed medical providers and do not diagnose or treat medical conditions.','Always consult your physician or qualified healthcare provider for medical concerns.','Results from Reiki sessions vary and are not guaranteed.','This practice complies with informed consent requirements; clients will be asked to sign a consent form prior to their first session.','If intake forms collect personal health information, this practice adheres to applicable HIPAA privacy guidelines.']::text[],false,true,false,ARRAY['No claims that Reiki treats, cures, or prevents any specific disease or medical condition','No testimonials implying medical outcomes without FTC-compliant disclaimers','No use of before-and-after health claims without evidence substantiation','Health benefit advertising must include disclaimer that Reiki is not a licensed medical practice','No comparison advertising claiming superiority over conventional medical treatments','Social media health claims must comply with FTC endorsement guidelines']::text[])
