INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:religious_book_store',true,'State Retail Business License #',ARRAY['State Department of Revenue (Sales Tax Registration)','State Secretary of State (Business Registration)','ADA — U.S. Department of Justice (Accessibility)','FTC — Federal Trade Commission (Endorsements and Testimonials)','U.S. Copyright Office (Scripture and Curriculum Reproduction)']::text[],ARRAY['Guaranteed to strengthen your faith','Only authorized source for God''s word','Scripture-based investment guaranteed to return blessings','Endorsed by God','Official Bible of [denomination] — sole source','Copyright-free scripture you can reprint freely']::text[],ARRAY['Sales tax collected and remitted in accordance with state law','Scripture quotations used in marketing materials are subject to publisher copyright; permissions obtained','Testimonials and endorsements on this profile reflect individual experiences; results may vary','This store is an independent retailer and is not officially affiliated with any denomination unless explicitly stated','ADA accommodations available; contact store for specific accessibility needs']::text[],false,false,false,ARRAY['FTC guidelines require clear disclosure of any material connection between the store and authors or publishers featured in endorsements','Copyright law prohibits reproduction of scripture passages beyond fair use without publisher permission','Claims of denominational endorsement must be supported by documented authorization from the named body','Marketing claims about product efficacy for spiritual outcomes must not be absolute or misleading','State consumer protection laws apply to pricing, discount claims, and sale representations']::text[])
