INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:religious_goods_store',true,'State Retail Sales Tax Permit #',ARRAY['State Department of Revenue (retail sales tax)','U.S. Customs and Border Protection (import tariff classification)','Federal Trade Commission (product authenticity advertising claims)','Consumer Product Safety Commission (candle and wax goods safety)','Americans with Disabilities Act (ADA) — retail storefront accessibility']::text[],ARRAY['Guaranteed Vatican-blessed','Officially endorsed by the Holy See','Certified sacred by the Pope','Guaranteed to have miraculous properties','Church-mandated purchase required']::text[],ARRAY['Sales tax collected in accordance with applicable state law.','Import duties and tariffs may apply to internationally sourced goods.','Product authenticity claims are based on distributor documentation; we do not represent direct Vatican endorsement.','Candle products comply with CPSC safety standards; always follow safe burning guidelines.','Religious goods are sold for devotional and liturgical use; no miraculous or supernatural efficacy is claimed or implied.']::text[],false,false,false,ARRAY['FTC regulations prohibit false or misleading claims regarding Vatican approval or papal endorsement without verifiable documentation.','Authenticity claims for ecclesiastical art must be supported by provenance documentation.','Imported goods advertising must comply with U.S. Customs country-of-origin labeling requirements.','Candle product advertising must not make safety claims inconsistent with CPSC standards.','Do not imply exclusive diocesan or archdiocese endorsement without written authorization.']::text[])
