INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:research_and_product_development',true,'ISO 9001 Certificate # | USPTO Patent Agent Registration # | FDA Establishment Registration # (if applicable)',ARRAY['U.S. Patent and Trademark Office (USPTO)','U.S. Food and Drug Administration (FDA) — for medical device and pharma-adjacent R&D','Bureau of Industry and Security (BIS), U.S. Department of Commerce — EAR compliance','Directorate of Defense Trade Controls (DDTC), U.S. Department of State — ITAR compliance','International Organization for Standardization (ISO) via accredited certification bodies','National Science Foundation (NSF) and National Institutes of Health (NIH) — grant compliance']::text[],ARRAY['guaranteed patent approval','FDA-approved research process','certified to guarantee market success','risk-free product development','we guarantee your product will succeed','legally guaranteed IP protection','100% regulatory approval rate','government-endorsed innovation firm']::text[],ARRAY['Patent filing support does not constitute legal advice; consult a licensed patent attorney for legal representation.','Regulatory pathway analysis is advisory only; FDA, CE, and other regulatory outcomes are determined by the applicable regulatory authority.','Export control classification opinions (EAR/ITAR) should be verified with qualified export counsel before implementation.','NDAs and trade secret protocols do not guarantee absolute protection under all jurisdictions; legal review is recommended.','ISO 9001 certification applies to quality management processes and does not guarantee product performance or regulatory approval.','Grant funding assistance does not guarantee award of federal grants.']::text[],false,false,false,ARRAY['Must not imply guaranteed patent issuance or USPTO approval outcomes','Must not imply FDA approval or clearance of client products as a direct result of services','Must not misrepresent ITAR/EAR compliance status as definitive legal clearance without counsel','Must not claim affiliation with government agencies (NSF, NIH, DOD) beyond documented grant or contract relationships','Must not advertise services as legal services unless a licensed attorney is providing them','Marketing for defense-related R&D services must comply with applicable procurement integrity and advertising rules']::text[])
