INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:resume_service',true,'Professional Certification: CPRW / NCRW / CARW',ARRAY['Professional Association of Resume Writers & Career Coaches (PARW/CC)','National Resume Writers Association (NRWA)','Career Directors International (CDI)','Federal Trade Commission (FTC) — advertising and endorsement guidelines','California Privacy Protection Agency (CPPA) — CCPA enforcement','Information Commissioner''s Office (ICO) — GDPR enforcement for EU-subject data']::text[],ARRAY['Guaranteed to get you hired','100% interview guarantee','We guarantee job placement','Certified to get you a job','Our resumes guarantee callbacks','We promise employment results']::text[],ARRAY['Results may vary. Professional resume writing services improve document quality but cannot guarantee employment outcomes or interview invitations.','Client data collected for resume writing purposes is handled in accordance with applicable privacy law including CCPA and GDPR where applicable.','Our writers do not fabricate employment history, credentials, titles, or educational qualifications. All content is based on information provided by the client.','Testimonials reflect individual client experiences and are not representative of guaranteed results for all clients.']::text[],false,false,false,ARRAY['FTC Endorsement Guides require that testimonials reflect honest opinions and typical results or must disclose atypical nature','No claims of guaranteed employment outcomes, placement rates, or salary increases in advertising copy','Interview callback rate claims must be qualified as self-reported and not guaranteed','No use of specific employer or recruiter names in advertising without written permission','Success metrics such as days to job offer must be disclosed as individual results and not typical outcomes']::text[])
