INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:retaining_wall_supplier',true,'State Landscape Contractor License #',ARRAY['National Concrete Masonry Association (NCMA)','Interlocking Concrete Pavement Institute (ICPI)','ASTM International (material compliance)','State Contractor Licensing Boards (varies by jurisdiction)','International Building Code — adopted by local municipalities','OSHA (29 CFR 1926 Subpart P — Excavations, applicable to installer customers)']::text[],ARRAY['guaranteed to pass inspection','engineered for all soil types without site assessment','no permit required for any height','certified structural engineer on staff','our walls will never fail','OSHA compliant installation included']::text[],ARRAY['Retaining walls exceeding 4 feet in height (measured from bottom of footing) may require a building permit in most jurisdictions — consult your local building department before construction.','Product load-bearing and structural ratings are based on ASTM laboratory testing under standard conditions; site-specific soil, drainage, and surcharge conditions may vary and should be evaluated by a qualified engineer.','Authorized distributor status is granted by individual manufacturers and applies only to products from those specific brands.','State contractor licensing requirements for construction activities vary by jurisdiction; purchasers are responsible for ensuring compliance with applicable laws.','Material quantity estimates provided are for planning purposes only and may not account for all site-specific variables.']::text[],false,false,false,ARRAY['Do not claim structural engineering services without a licensed PE on staff','Do not imply products eliminate the need for permits or professional design review','Do not guarantee specific compressive strength performance in field conditions beyond ASTM-tested values','Do not represent manufacturer authorized distributor status for brands not under active agreement','Do not use ''certified installer'' or ''licensed installer'' language — this is a supply business, not a contractor']::text[])
