INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:sand_plant',true,'State Surface Mining Permit #',ARRAY['Mine Safety and Health Administration (MSHA)','U.S. Environmental Protection Agency (EPA) — NPDES Clean Water Act','State Surface Mining Regulatory Agency (jurisdiction-specific, e.g., state DNR or DMME)','Occupational Safety and Health Administration (OSHA)','State Air Quality Agency (Title V / state operating permit programs)']::text[],ARRAY['guaranteed lowest price on any sand','OSHA-exempt facility','no dust hazard on site','environmentally impact-free mining','fully reclaimed upon extraction','MSHA violation-free guaranteed','safest silica exposure levels in the industry','no permit required for this operation']::text[],ARRAY['Silica sand contains crystalline silica. Prolonged inhalation may cause silicosis, lung cancer, or other serious lung disease. Follow all applicable OSHA exposure limits per 29 CFR 1910.1053.','All product specifications subject to in-situ variability. Gradation and quality data represent typical values from current stockpile; buyer should verify with COA for each shipment.','Delivery availability and scheduling subject to production capacity, weather, and haul-route conditions.','All operations conducted under state surface mining permit and applicable federal MSHA regulations. Permit numbers available upon request.','Stormwater discharges managed under EPA NPDES permit. Contact facility for current permit status.']::text[],false,false,false,ARRAY['Must not claim regulatory compliance superiority over competitors without documented evidence','Must not represent MSHA inspection outcomes as endorsements or approvals','Cannot use ''certified'' to describe products unless referencing a specific named standard (e.g., ASTM C33, API RP 19C)','Silica dust health claims in advertising must not minimize or trivialize OSHA-recognized hazards','Environmental claims (e.g., ''eco-friendly mining'') require substantiation tied to specific permits and practices']::text[])
