INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:sanitation_service',true,'State Solid Waste Hauler License #',ARRAY['U.S. Environmental Protection Agency (EPA) — RCRA and Hazardous Waste Programs','U.S. Department of Transportation (DOT) — Hazardous Materials Transportation','State Environmental Quality / Solid Waste Management Agency (jurisdiction-specific)','Occupational Safety and Health Administration (OSHA) — Bloodborne Pathogen and Worker Safety Standards','U.S. EPA — Clean Air Act Mobile Source Emissions Program','Local Municipal Authority — Franchise Agreement Administration']::text[],ARRAY['guaranteed cheapest rates','we dispose of all waste legally','all waste accepted','no questions asked disposal','we take any hazardous material']::text[],ARRAY['Hazardous waste disposal is regulated under RCRA; improper disposal may result in federal penalties.','Medical waste must be handled in accordance with applicable state regulations and OSHA bloodborne pathogen standards.','All waste manifests are maintained per EPA e-Manifest requirements for regulated waste streams.','Municipal service availability subject to active franchise agreement with local government authority.','DOT hazardous materials transportation requires current certification; certificates available upon request.']::text[],false,false,false,ARRAY['Cannot claim EPA or DOT certification without maintaining current active credentials','Must not imply unlimited hazardous waste acceptance without disclosing generator classification limits','Cannot advertise medical waste services without valid state biomedical waste transporter permit','Roll-off rental pricing advertised must include all applicable tipping fee disclosures','Cannot use ''eco-friendly'' or ''green'' claims without substantiated diversion rate data']::text[])
