INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:saw_mill',true,'State Forestry Commission Operating License #',ARRAY['State Forestry Division / State Forestry Commission','U.S. Environmental Protection Agency (EPA) — Air Quality Division','U.S. Fish and Wildlife Service (Lacey Act enforcement)','Occupational Safety and Health Administration (OSHA)','National Hardwood Lumber Association (NHLA) — Grading Rules Authority','Forest Stewardship Council (FSC) — Chain of Custody Certification Body','Local Zoning and Land Use Authority']::text[],ARRAY['100% organic lumber','government certified pest-free','legally harvested — guaranteed','no environmental impact','OSHA approved sawmill','certified wildlife-safe operation']::text[],ARRAY['Lumber sold green (unseasoned) may shrink, check, or warp during drying — kiln drying recommended for interior applications.','Board footage estimates are calculated at time of scaling and may vary by up to 5% from final yield.','FSC Chain of Custody certification number available upon request for qualifying orders.','Lacey Act compliance documentation provided for all imported or exotic timber species.','Dust and air emissions managed under EPA-issued air quality operating permit — permit number available on request.','On-site portable milling availability subject to travel radius and seasonal scheduling — confirm availability before booking.']::text[],false,false,false,ARRAY['Must not claim FSC certification without displaying valid FSC certificate ID and expiry','Must not claim NHLA grading certification without a credentialed grader on staff','Lacey Act sourcing must be documentable for any species claimed as legally harvested','EPA air quality permit must be current before advertising kiln drying operations','State forestry operating license must be active before advertising commercial milling services','Do not advertise specific board foot yields without a disclaimer on estimated versus actual yield']::text[])
