INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:scale_supplier',true,'NTEP Certificate of Conformance #',ARRAY['National Conference on Weights and Measures (NCWM) — NTEP Program','International Organization of Legal Metrology (OIML)','U.S. Food and Drug Administration (FDA) — for food and pharmaceutical sector scales','Occupational Safety and Health Administration (OSHA) — installation safety','U.S. Customs and Border Protection — import/export of weighing instruments']::text[],ARRAY['guaranteed legal for trade without NTEP certification','certified accurate without calibration','FDA approved scale','OSHA certified installation','OIML approved without valid conformity declaration']::text[],ARRAY['Scales used in commercial trade must carry a valid NTEP Certificate of Conformance and be registered with the applicable state weights and measures authority.','Scales used in food or pharmaceutical production must comply with applicable FDA regulations; consult your regulatory affairs team before procurement.','Installation of industrial floor scales must comply with OSHA 29 CFR 1910 general industry standards; professional installation recommended.','RoHS compliance declarations are product-specific; confirm conformity documentation for each SKU prior to import or resale.','OIML certificates are model-specific and do not automatically confer legal-for-trade status in all jurisdictions; verify local requirements.']::text[],false,false,false,ARRAY['Do not claim scales are ''legal for trade'' unless the specific model holds a current NTEP Certificate of Conformance','Do not use ''FDA approved'' — correct usage is ''FDA compliant'' or ''suitable for FDA-regulated environments''','Do not claim calibration services without disclosing whether offered in-house or via third-party accredited laboratory','Advertising of OIML-certified products must reference the specific conformity declaration number and issuing body','Do not imply scales meet all international standards without specifying applicable certification scope']::text[])
