INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:seafood_farm',true,'State Aquaculture Permit # | Fish Culture License #',ARRAY['U.S. Food and Drug Administration (FDA) — 21 CFR Part 123 Seafood HACCP','U.S. Environmental Protection Agency (EPA) — Clean Water Act NPDES Permit Program','NOAA Fisheries — Aquaculture Leasing for Coastal and Federal Waters','U.S. Department of Agriculture (USDA) — Organic Aquaculture Certification via Accredited Certifiers','State Department of Agriculture — Aquaculture Permits and Annual Inspection Program','State Environmental Quality / Fish and Wildlife Agency — Fish Culture Licensing']::text[],ARRAY['100% safe seafood guaranteed','no risk of contamination','better than wild-caught in every way','FDA approved facility','government endorsed','parasite-free guaranteed','antibiotic-free without certification to back the claim','pesticide-free without certification']::text[],ARRAY['Seafood products are produced under an active HACCP plan in compliance with FDA 21 CFR Part 123.','State aquaculture permit and fish culture license are maintained current and available for inspection.','Organic certification claims apply only to species and production lots covered under the active USDA-accredited organic certificate.','EPA NPDES discharge permit compliance is maintained; effluent monitoring records available upon request.','Coastal or tidal operations are conducted under valid NOAA Fisheries aquaculture lease.','Consumers with shellfish allergies should consult a healthcare provider before purchase.']::text[],false,false,false,ARRAY['Cannot claim organic certification unless the specific production lot is covered by a current USDA-accredited organic certificate','Cannot use ''FDA approved'' — FDA registers facilities but does not approve individual seafood products','BAP and GlobalG.A.P. certification claims must match the current certificate scope and expiry','Sustainability claims must be substantiated by a recognized third-party certification or audit','Health benefit claims about seafood must not imply disease prevention or treatment','Cannot advertise species availability that is not currently in stock or in active harvest season']::text[])
