INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:septic_system_service',true,'Plumber/Drainer Licence #',ARRAY['State Environment Protection Authority (EPA) — service agent approval','State Plumbing Regulatory Authority (e.g. NSW Fair Trading, VBA, QBCC)','Local Council — development approval and compliance reporting','Australian Building Codes Board — plumbing standards reference']::text[],ARRAY['EPA certified system','guaranteed to pass council inspection','fully licensed and certified in all states','no permit required','safe to discharge untreated effluent','council approved without DA','septic approved for any property type']::text[],ARRAY['All onsite wastewater systems must be designed, installed and serviced in accordance with AS/NZS 1547:2012 and applicable state EPA guidelines.','Council development approval is required before installing or replacing any onsite wastewater management system.','Service agents must hold current EPA approval in the relevant state jurisdiction. Licences are subject to renewal.','Mandatory service logbooks must be maintained for all AWTS units in accordance with state EPA requirements.','Effluent setback distances must comply with state EPA guidelines and council conditions of approval.','System failure or overflow must be reported to the relevant council or EPA authority as required by state legislation.']::text[],false,false,false,ARRAY['Must not imply EPA approval covers jurisdictions where the business is not registered','Must not guarantee council approval outcomes','Must not claim exclusive or proprietary treatment technology unless manufacturer-verified','Service cost estimates advertised must include disclaimer that final price depends on site assessment','Emergency response time claims must reflect actual average response capability']::text[])
