INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:shipping_company',true,'USDOT # | MC- # | FMC OTI License #',ARRAY['Federal Motor Carrier Safety Administration (FMCSA)','U.S. Department of Transportation (DOT)','Federal Maritime Commission (FMC)','U.S. Customs and Border Protection (CBP)','Transportation Security Administration (TSA)','International Air Transport Association (IATA)','Environmental Protection Agency (EPA) — SmartWay']::text[],ARRAY['guaranteed lowest freight rates','100% on-time delivery guaranteed','no freight claims ever','damage-free shipping guaranteed','fully insured against all cargo loss','FMCSA-approved carrier (FMCSA does not endorse carriers)','CBP-certified customs broker (CBP licenses, not certifies)']::text[],ARRAY['Carrier liability is limited under 49 U.S.C. § 14706 (Carmack Amendment); additional cargo insurance is available and recommended for high-value shipments.','International shipments are subject to the laws and regulations of the countries of origin and destination, including applicable customs duties and import restrictions.','Hazardous materials shipments must comply with 49 CFR and applicable IATA/ICAO regulations; shipper is responsible for proper classification and packaging.','Freight rates quoted are estimates and subject to change based on fuel surcharges, accessorial charges, and final shipment dimensions/weight.','FMCSA safety ratings and CSA scores are publicly available at safer.fmcsa.dot.gov.']::text[],false,false,false,ARRAY['Must not claim FMCSA or CBP ''approval'' or ''endorsement''','Must not guarantee specific transit times without contractual SLA backing','Must not advertise hazmat transport capabilities without current 49 CFR certification','Must not advertise customs brokerage services without active CBP broker license','Must disclose fuel surcharges and accessorial fees in rate advertising','Must not use ''bonded and insured'' language without specifying applicable coverage limits']::text[])
