INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:shoe_repair_shop',true,'Local Business License #',ARRAY['Occupational Safety and Health Administration (OSHA)','U.S. Environmental Protection Agency (EPA)','State and Local Business Licensing Authorities','Consumer Protection Agencies (State Attorney General Offices)']::text[],ARRAY['guaranteed permanent repair','medical-grade orthotics','resoling voids manufacturer warranty','EPA-certified disposal']::text[],ARRAY['Repair outcomes may vary depending on shoe construction, material condition, and age of footwear.','Pricing estimates provided in-store after assessment; final cost may differ from initial quote.','Orthotic insole fitting is not a substitute for medical advice from a licensed podiatrist or physician.','Solvent and adhesive use in our workshop complies with applicable OSHA and EPA regulations.','Manufacturer warranty implications of third-party repair are the responsibility of the customer.']::text[],false,false,false,ARRAY['Do not claim medical or therapeutic benefits for orthotic fittings without podiatric referral context','Do not imply manufacturer endorsement unless authorized repair status is current and documented','Do not advertise specific solvent brand names with environmental claims unless EPA-certified','Pricing advertised must reflect actual charged rates per consumer protection transparency laws','Do not claim ''lifetime guarantee'' on repairs without written warranty terms available to consumers']::text[])
