INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:shooting_event_area',true,'State Range Operating Permit #',ARRAY['Bureau of Alcohol Tobacco Firearms and Explosives (ATF)','State Firearms Range Operating Authority (jurisdiction-specific)','Local Municipal Zoning and Land Use Authority','Environmental Protection Agency (lead remediation requirements)','National Shooting Sports Foundation (Range Source Program voluntary)','Occupational Safety and Health Administration (workplace safety at ranges)']::text[],ARRAY['100% safe range environment','no risk of injury','guaranteed safe','ATF approved facility','government certified match']::text[],ARRAY['All participants must sign a liability waiver before engaging in any shooting activity','Range safety rules must be followed at all times — violations may result in disqualification or removal','This facility operates under state and local firearms range permits — contact us for current compliance status','Lead exposure risk exists at all shooting ranges — participants should wash hands and face thoroughly after shooting','Youth participants require written parental or guardian consent before participation']::text[],true,false,false,ARRAY['Cannot claim government endorsement or ATF certification of match operations','Must not advertise guaranteed prize payouts without disclosure of terms','Cannot imply that participation in matches confers legal concealed carry qualification','Event advertising must not target individuals prohibited from firearm possession','Youth program advertising must include parental consent requirement notice']::text[])
