INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:sightseeing_tour_agency',true,'Tourism Operator License #',ARRAY['State or Municipal Tourism Licensing Authority','Commercial Vehicle Licensing Division — State Department of Transportation','Local Fire Marshal (Capacity Compliance)','State Consumer Protection Office (Refund and Cancellation Disclosures)','Americans with Disabilities Act (ADA) — U.S. Department of Justice']::text[],ARRAY['guaranteed lowest price','100% safe tours','no cancellations ever','unlimited capacity','government endorsed','officially endorsed by the city','insurance not required','ADA compliant by default without documentation']::text[],ARRAY['Tour capacity limits apply per vehicle and are enforced by local fire marshal regulations.','Passenger liability insurance is maintained in accordance with applicable state mandates.','Cancellation and refund policies are disclosed at time of booking in compliance with consumer protection law.','ADA-accessible accommodations are available upon advance request — contact us to confirm availability for your tour date.','Shore excursion schedules are subject to cruise ship departure times — operators are not responsible for missed departures due to ship schedule changes.','Eco-certification claims reflect third-party verified certifications — details available upon request.']::text[],false,false,false,ARRAY['Cannot claim official government endorsement or municipal affiliation without formal designation','Cannot guarantee full refunds without disclosed policy terms','Cannot advertise unlimited group sizes contrary to fire marshal capacity approvals','Must disclose booking fees and surcharges in advertised pricing','Cannot misrepresent accessibility features — ADA accommodation claims must reflect documented compliance']::text[])
