INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:skateboard_shop',true,'State Retail Business License #',ARRAY['U.S. Consumer Product Safety Commission (CPSC)','ASTM International (for F1492 and related protective gear standards)','State Department of Revenue / Business Licensing Authority','City or County Business License Office']::text[],ARRAY['safest skateboard equipment on the market','CPSC approved (approval not issued; use CPSC compliant or certified)','guaranteed safe for all ages','injury-proof protective gear','endorsed by CPSC','meets all safety standards (must specify which standard by name)']::text[],ARRAY['All helmets and protective gear sold meet applicable CPSC and ASTM certification requirements. Protective gear reduces risk but does not eliminate it.','Skateboarding involves inherent risk of injury. Proper protective gear is strongly recommended for all riders, especially youth.','Youth protective gear sales comply with applicable state child product safety laws. Parents should verify fit and certification prior to use.','Product safety compliance is verified at time of purchase from authorized distributors. Customers should inspect gear before each use.']::text[],false,false,false,ARRAY['May not claim CPSC ''approval'' — CPSC certifies standards compliance, not individual products','Must not use unqualified absolute safety claims for helmets or pads','Sponsored skater imagery must not imply endorsement of safety claims','Youth-targeted advertising must comply with COPPA for digital channels','Do not imply that all brands carried are exclusively or officially endorsed by the shop without authorization documentation']::text[])
