INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:south_asia_restaurant',true,'Food Service Permit #',ARRAY['Local/County Health Department (Food Service Permit Authority)','State Alcoholic Beverage Control Board (if serving alcohol)','FDA (Food Safety Modernization Act)','Recognized Halal Certifying Authority (e.g. IFANCA, ISNA, HFA) if halal claimed']::text[],ARRAY['100% allergen-free','Guaranteed nut-free kitchen','Certified organic (without valid certification)','Healthiest Indian food','FDA approved restaurant']::text[],ARRAY['Halal certification is verified by [Certifying Body Name]; certificate available upon request','Menu items may contain or be prepared in proximity to tree nuts, peanuts, and gluten; guests with allergies should inform staff','Alcohol service subject to valid state liquor license','Health Department inspection grade posted at premises as required by law','Prices and menu items subject to change without notice']::text[],false,false,false,ARRAY['Halal claims in advertising must be supported by a valid, current, and named certifying authority certificate','Allergen-free claims must not be made unless kitchen is certified allergen-free by a recognized body','Liquor/alcohol promotions must comply with state ABC advertising rules including no targeting of minors','Health claims about specific dishes (e.g. ''cures diabetes'') are prohibited under FTC and FDA guidelines','Any use of ''authentic'' or ''traditional'' must be supportable by documented regional sourcing or chef credentials']::text[])
