INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:souvenir_store',true,'Retail Business License #',ARRAY['State Department of Revenue (sales tax)','U.S. Federal Trade Commission (truth in advertising, country of origin labeling)','U.S. Customs and Border Protection (country of origin marking, 19 U.S.C. 1304)','State and Local Business Licensing Authority','Americans with Disabilities Act (ADA) Enforcement via U.S. Department of Justice']::text[],ARRAY['100% locally made (unless all items verified)','Certified authentic (without third-party verification)','Handmade by local artisans (applied to mass-produced imported items)','Original one-of-a-kind (applied to factory-produced multiples)','All-natural materials (without substantiation)','Guaranteed lowest price on souvenirs']::text[],ARRAY['Country of origin must be clearly labeled on all imported merchandise per FTC and U.S. Customs regulations','Handmade or locally made claims must be accurate and verifiable; false claims violate FTC truth in advertising standards','Sales tax is collected and remitted per applicable state and local jurisdiction requirements','ADA-accessible entrance and facilities available; contact store for specific accommodation needs','Wholesale and bulk pricing available by arrangement; standard retail pricing applies to individual sales']::text[],false,false,false,ARRAY['Cannot claim products are locally made or handmade without verifiable sourcing documentation','Cannot use country of origin claims that misrepresent manufacturing location','Must not advertise a price as a sale price unless a bona fide prior regular price existed','Testimonials and reviews used in advertising must reflect honest customer opinions and comply with FTC endorsement guidelines','Environmental or sustainability claims (e.g., eco-friendly, green) must be substantiated per FTC Green Guides']::text[])
