INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:spine_surgeon',true,'State Medical License # | NPI: [number]',ARRAY['State Medical Board (varies by jurisdiction)','American Board of Orthopaedic Surgery (ABOS)','American Board of Neurological Surgery (ABNS)','Centers for Medicare and Medicaid Services (CMS)','Drug Enforcement Administration (DEA)','North American Spine Society (NASS) — professional standards','Scoliosis Research Society (SRS) — professional standards','CDC Surgical Site Infection Prevention Guidelines']::text[],ARRAY['guaranteed results','cure your back pain','100% success rate','pain-free after surgery','best spine surgeon in the country','surgery is the only option','no risk procedure','permanent fix']::text[],ARRAY['Individual surgical outcomes vary; consult your physician for advice specific to your condition.','Board certification status and license information should be verified with the issuing state medical board and ABOS/ABNS.','Implant and device manufacturer financial relationships are disclosed as required under the Physician Payments Sunshine Act.','This practice complies with HIPAA privacy regulations; patient health information is protected.','Referral relationships involving ownership interests in surgical facilities are disclosed in compliance with the Stark Law (42 U.S.C. § 1395nn).','Informed consent is required before all surgical procedures; patients have the right to seek a second opinion.']::text[],false,true,true,ARRAY['Must not claim board certification not yet achieved or lapsed','Must not imply guaranteed surgical outcomes or cure','Must disclose financial relationships with device manufacturers per Sunshine Act','Must not advertise services in states where the surgeon is not licensed','Testimonials must reflect genuine patient experiences and not be incentivized','Medicare and Medicaid anti-kickback statute prohibits compensation for referrals','All advertising must comply with state medical board advertising rules (e.g., no misleading superiority claims)','Must not use before/after imagery in a misleading or unrepresentative way']::text[])
