INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:squash_club',true,'England Squash Affiliation Number',ARRAY['England Squash','World Squash Federation (WSF)','Professional Squash Association (PSA)','Local Authority Health and Safety Executive','UK Information Commissioner''s Office (GDPR)']::text[],ARRAY['guaranteed fitness results','world-class coaching','professional-standard courts (unless WSF certified)','safest club in the UK','certified injury-free training']::text[],ARRAY['England Squash affiliated club — affiliation number displayed on request','Junior programmes operate under England Squash safeguarding and child protection policies','Public liability insurance maintained in accordance with England Squash affiliation requirements','Member personal data stored and processed in accordance with UK GDPR','First aid trained staff on premises during all court opening hours','Coaching qualifications held by individual coaches — verify on request']::text[],false,false,false,ARRAY['Must not claim PSA or WSF endorsement without verified written agreement','Coaching qualification claims must reflect the individual coach''s actual certified level','Junior programme advertising must reference safeguarding policy compliance','Cannot imply England Squash ranking or grading without valid affiliation and registered results','Social media advertising targeting under-18s must comply with England Squash safeguarding guidelines']::text[])
