INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:state_archive',false,NULL,ARRAY['State Legislature via enabling public records statute','National Archives and Records Administration (NARA) for federal records schedules','State courts for sealed records and expungement orders','U.S. Department of Health and Human Services (HIPAA) for health information in records','State Attorney General office enforcing Freedom of Information and public records laws']::text[],ARRAY['guaranteed same-day record retrieval','complete genealogy research performed on your behalf','all records available online','unrestricted access to all government records','we can obtain sealed or expunged records for you','HIPAA-protected health records available upon request']::text[],ARRAY['Access to records containing personal health information is restricted under HIPAA and applicable state privacy law.','Sealed, expunged, or court-restricted records are not available without a valid court order.','Certified copies carry legal standing only when issued with the official state seal and authorized signature.','Records requests are subject to applicable fees and processing times per state statute.','This archive operates under the state Public Records Act; certain records are exempt from public disclosure.','Federal records held in custody are subject to applicable federal retention schedules and access restrictions.']::text[],false,true,false,ARRAY['Must not imply unrestricted access to records exempt by statute','Must not promise legal outcomes from records obtained at the archive','Must not advertise access to juvenile, sealed, or expunged records','Must comply with state ethics rules governing use of official seal in advertising','Must not imply endorsement by NARA, courts, or other government bodies without formal agreement']::text[])
