INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:state_park',true,'State Park Facility Permit #',ARRAY['State Department of Natural Resources','State Fish and Wildlife Agency','State Environmental Conservation Agency','Americans with Disabilities Act (ADA) Enforcement - DOJ','Leave No Trace Center for Outdoor Ethics','State Fire Marshal']::text[],ARRAY['guaranteed wildlife sightings','always open','no permit required','campfires always permitted','swimming at your own risk with no lifeguard disclaimer','no fees required','hunting without a license','fishing without a state license']::text[],ARRAY['State park fees and hours are subject to change without notice. Check the official state DNR website before visiting.','All visitors must comply with applicable state park use regulations and permit requirements.','Fires are subject to burn bans and fire restrictions. Check current fire status before your visit.','Fishing and hunting require valid state licenses and compliance with all state wildlife regulations.','All trail users are encouraged to follow Leave No Trace principles to protect natural resources.','ADA-accessible facilities are available. Contact the park for specific accessibility information before your visit.','Wildlife is wild and unpredictable. Maintain safe distances at all times.']::text[],false,false,false,ARRAY['Cannot guarantee wildlife encounters or specific species sightings in promotional materials','Cannot advertise facility availability without referencing that reservations are required and capacity is limited','Cannot imply that camping is free or that day-use fees do not apply','Cannot advertise campfire availability during active burn bans or fire restrictions','Must include ADA accessibility information in all facility advertising where applicable','Cannot use language suggesting the park is always open without noting seasonal or emergency closure provisions']::text[])
