INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:steel_construction_company',true,'State Contractor License #',ARRAY['American Institute of Steel Construction (AISC) — Fabricator and Erector Certification Programs','Occupational Safety and Health Administration (OSHA) — 1926 Subpart R Steel Erection Standards','American Welding Society (AWS) — D1.1 Structural Welding Code','International Building Code (IBC) — Chapter 22 Steel Design Requirements','State Contractor Licensing Boards (jurisdiction-specific)','EPA — NPDES Stormwater Permit Program for Construction Site Disturbance']::text[],ARRAY['guaranteed lowest price on any steel project','AISC certified — satisfaction guaranteed','OSHA-exempt','our welds have never failed','licensed in all 50 states','no permit required for this structure']::text[],ARRAY['AISC Certification scope is limited to the specific category(ies) listed on the current certificate. Verify status at aisc.org.','All structural steel work must comply with applicable building codes and be permitted by the authority having jurisdiction.','Welding performed under approved Welding Procedure Specifications per AWS D1.1; third-party inspection available upon request.','State contractor license required for structural work; license number and jurisdiction available upon request.','OSHA 1926 Subpart R compliance is the responsibility of the controlling contractor and the steel erector jointly.']::text[],false,false,false,ARRAY['Do not claim AISC certification categories beyond those listed on the current certificate','Do not imply PE-of-record services unless a licensed structural engineer is on staff or under contract','Do not guarantee compliance with local codes without referencing the authority having jurisdiction','Do not use EMR or safety statistics in advertising without current documentation on file','Avoid superlative safety claims (e.g. zero accidents ever) without verifiable third-party documentation']::text[])
