INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:stereo_repair_service',true,'ETA CET Certification # / IPC Credential ID',ARRAY['ETA International (Electronics Technicians Association)','IPC – Association Connecting Electronics Industries','U.S. Environmental Protection Agency (EPA) – RoHS and e-waste rules','Occupational Safety and Health Administration (OSHA) – electrical safety standards','Federal Trade Commission (FTC) – warranty and written estimate rules','State Environmental Agency – e-waste recycling regulations (jurisdiction-specific)']::text[],ARRAY['Guaranteed to fix any stereo','We can repair any device no matter what','All repairs are permanent','Your warranty is void if you use anyone else','We are factory authorized for all brands','Lowest price guaranteed on all repairs']::text[],ARRAY['Written repair estimate provided before work begins; customer approval required prior to service','Post-repair warranty terms (labor and parts) disclosed in writing at time of device return','E-waste and scrapped components disposed of in compliance with applicable state regulations','FTC Warranty Rules: use of non-OEM parts disclosed when applicable','OSHA electrical safety protocols maintained on all repair benches; customers are not permitted in active work areas']::text[],false,false,false,ARRAY['Do not claim manufacturer authorization for brands where no formal authorization exists','Do not guarantee specific repair outcomes for equipment not yet evaluated','Do not advertise price matching without a verified matching policy in place','Repair estimate advertising must reflect actual average costs and include disclosure that final price may vary after diagnosis','Environmental disposal claims must reflect actual certified e-waste partner relationships']::text[])
