INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:stylist',true,'State Cosmetology Establishment License #',ARRAY['State Cosmetology Board (jurisdiction-specific, e.g. California Board of Barbering and Cosmetology)','OSHA (Occupational Safety and Health Administration) for chemical handling and sanitation standards']::text[],ARRAY['guaranteed results','permanent hair repair','medically treats scalp conditions','FDA-approved hair treatment','licensed trichologist']::text[],ARRAY['All chemical services are performed by state-licensed cosmetologists.','Results may vary based on hair type, condition, and history of chemical services.','Clients with known allergies or sensitivities should notify the stylist prior to chemical services.','Chemical disposal complies with applicable OSHA and local environmental regulations.','Salon premises comply with ADA accessibility requirements.']::text[],false,false,false,ARRAY['Cannot claim medical or therapeutic benefits for scalp or hair treatments without clinical substantiation.','Cannot use the title ''Trichologist'' without accredited certification from a recognized trichology body (e.g. International Association of Trichologists).','Cannot imply permanent or guaranteed outcomes from chemical services such as keratin treatments or color correction.','Must not advertise specific product claims (e.g. ''formaldehyde-free'') without verified product documentation on file.','Promotional pricing must comply with state consumer protection truth-in-advertising laws.']::text[])
