INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:surf_lifesaving_club',true,'SLSA Affiliation #',ARRAY['Surf Life Saving Australia (SLSA)','State Branch Surf Life Saving Bodies (e.g. SLSNSW, SLSQ, SLSWA, SLSSA, SLSV, SLST)','Local Government Council Beach Management Agreements','Australian Volunteer Protection legislation (state-based)','Working With Children Check Authorities (state-based)']::text[],ARRAY['guaranteed rescue response','professional lifeguard service','certified to swim here anytime','we monitor all beach areas at all times','24/7 patrol coverage','our beach is always safe']::text[],ARRAY['Patrol coverage is seasonal and limited to flagged patrol hours only — always swim between the flags','Volunteer patrollers are not professional lifeguards employed by council — councils may operate separate paid lifeguard services','Bronze medallion and first aid certifications must be recertified on the SLSA-mandated cycle to remain valid','Working With Children Check compliance is required for all coaches and staff involved in youth programs','The club operates under Surf Life Saving Australia policies and state branch governance — not a commercial rescue service']::text[],false,false,false,ARRAY['Must not imply guaranteed emergency response beyond patrol hours','Must not compare volunteer club patrol standards to professional paid lifeguard council services','Must not make claims about beach safety levels without reference to patrol season dates and hours','Nipper program advertising must comply with state Working With Children Check disclosure requirements','Membership and training fee advertising must disclose that SLSA affiliation fees apply separately where applicable']::text[])
