INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:tabascan_restaurant',true,'Health Permit #',ARRAY['Local Health Department','State Alcohol Beverage Control Board','FDA (for imported regional ingredients)','ADA (Americans with Disabilities Act)']::text[],ARRAY['The only authentic Tabascan restaurant','Certified by the Mexican government','Guaranteed food safety','Officially endorsed by Tabasco state','All-natural with no additives','100% organic without certification','Healthiest Mexican food']::text[],ARRAY['Alcohol service subject to state licensing requirements and age verification','Menu items containing imported ingredients are FDA-compliant','Catering services subject to local health permit jurisdiction','ADA-accessible facilities available; contact restaurant for specific accommodation needs','Seasonal menus subject to ingredient availability']::text[],true,false,false,ARRAY['Alcohol advertising must comply with state beverage control regulations','Cannot claim official government endorsement or certification from Mexican federal or state authorities','Must not imply medical or health claims for chaya or other traditional ingredients without substantiation','Event catering promotions must not guarantee specific cultural authenticity certifications not held']::text[])
