INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:tai_chi_school',true,'Instructor Certification # (ATCQA or equivalent)',ARRAY['American Tai Chi and Qigong Association (ATCQA)','National Qigong Association (NQA)','State Business Licensing Authority (jurisdiction-specific)','State Attorney General — Consumer Protection (for health claims)']::text[],ARRAY['cures disease','treats medical conditions','replaces medical treatment','guaranteed health results','medically proven to heal','eliminates chronic illness','FDA approved']::text[],ARRAY['Tai chi and qigong are movement arts and wellness practices; they are not a substitute for professional medical advice, diagnosis, or treatment. Consult your physician before beginning any new physical activity program.','Participation involves physical movement; instructor liability waiver must be signed prior to first class.','Minors under 18 must have a signed parental or guardian consent form on file.','ADA accessibility accommodations available upon request; contact us in advance to confirm your needs.','Therapeutic benefit claims are based on published research literature and do not constitute medical advice.']::text[],false,false,false,ARRAY['Health and therapeutic benefit claims must cite peer-reviewed research sources and include health disclaimer language','Marketing to Parkinson''s or arthritis patients must not imply medical treatment or cure','Corporate wellness marketing must not guarantee specific employee health outcomes','Minor-focused advertising must not be targeted without parental consent pathways','Online class advertising must clearly disclose technology requirements and refund policy']::text[])
