INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:traditional_market',true,'Municipal Business License # / Health Permit #',ARRAY['Local Municipal Government Business Licensing Authority','Local Health Department (Food Safety and Environmental Health Division)','State Department of Agriculture (Certified Farmers Market Program)','Local Zoning and Planning Department']::text[],ARRAY['100% organic guaranteed','all vendors are certified','government approved quality','best prices guaranteed','no health risks']::text[],ARRAY['All food vendors are required to hold current local health department permits. Shoppers should verify individual vendor certifications on request.','Market operating hours and vendor availability are subject to seasonal change. Check market website or social media for current schedule.','Vendor space availability is subject to permit approval and zoning compliance. Contact market management for current availability.','The market does not guarantee the organic or pesticide-free status of produce unless individually vendor-certified and labelled.']::text[],false,false,false,ARRAY['Must not claim ''all organic'' unless market holds certified organic designation','Must not represent individual vendor health certifications as market-wide guarantees','Event promotion must accurately state vendor participation and not imply exclusivity of goods','Pricing claims must reflect actual current vendor pricing and not constitute false advertising under local consumer protection law']::text[])
