INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:unfinished_furniture_store',false,NULL,ARRAY['Consumer Product Safety Commission (CPSC)','Forest Stewardship Council (FSC)','Environmental Protection Agency (EPA) — VOC regulations via state implementation plans','State Attorneys General — Truth in Advertising enforcement','Americans with Disabilities Act (ADA) — showroom accessibility']::text[],ARRAY['100% non-toxic finish included','Guaranteed FSC certified if certification not current','Solid wood construction (if any component is veneer or particleboard)','Lowest prices guaranteed','Safe for all uses without finishing','Environmentally friendly (without substantiation)']::text[],ARRAY['Wood is a natural material; grain color and character vary by piece','FSC certification claims are valid only while chain-of-custody certificate is current','Finishing products containing VOCs may be restricted in some states — check local regulations before purchase','Furniture stability anchoring hardware recommended per CPSC guidelines for tip-over prevention','Custom and special order items may be non-returnable — confirm terms at time of order','All wood species and construction descriptions reflect manufacturer specifications']::text[],false,false,false,ARRAY['Wood species must be accurately identified — misrepresenting species type violates FTC truth-in-advertising rules','FSC certification claims require current valid chain-of-custody certificate number on file','VOC content claims for finishing products must reflect actual product formulations per EPA and applicable state rules','Furniture stability claims must not contradict CPSC testing and labeling standards','Sustainability claims (eco-friendly, green, natural) must be substantiated per FTC Green Guides']::text[])
