INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:university_library',false,NULL,ARRAY['U.S. Department of Education (FERPA enforcement)','U.S. Copyright Office (Copyright Act compliance)','Americans with Disabilities Act — U.S. Department of Justice','State Attorney General or public records authority (if state university subject to public records laws)','Creative Commons licensing framework (not a regulator but a binding compliance framework for digital content sharing)']::text[],ARRAY['guaranteed access to any journal or article','unlimited copyright reproduction','we can photocopy any item for you without restriction','full text available for all resources','no restrictions on borrowing']::text[],ARRAY['Student borrowing records are protected under the Family Educational Rights and Privacy Act (FERPA) and will not be disclosed without consent except as permitted by law.','Interlibrary loan reproduction is governed by the Copyright Act; requests must comply with the CONTU Guidelines and Section 108 limitations.','Digital content shared under Creative Commons licenses is subject to the specific terms of each license; commercial reuse may be restricted.','Physical and digital collections accessibility accommodations are available in compliance with ADA requirements; contact the library for assistance.','Remote database access is restricted to currently enrolled students, faculty, and staff of the university as required by vendor license agreements.']::text[],false,false,false,ARRAY['Must not imply unlimited or unrestricted access to licensed third-party databases beyond what licenses permit','Must not represent ILL reproduction as copyright-free or without limits','Must not use student names or borrowing histories in promotional materials without explicit written consent under FERPA','Must not claim ALA accreditation for the library itself — accreditation applies to library science degree programs, not library facilities','Must not guarantee fulfillment turnaround times for ILL without reflecting actual service-level data']::text[])
