INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:uyghur_cuisine_restaurant',true,'Halal Certification # | Health Permit #',ARRAY['Local/County Health Department (Food Safety Division)','FDA (imported spice and specialty ingredient compliance)','State Alcoholic Beverage Control Board (if alcohol served)','Recognized Halal Certifying Body (e.g. ISNA Halal Certification, local halal council)']::text[],ARRAY['100% guaranteed halal without valid certification','Certified organic without USDA certification','The only authentic Uyghur restaurant in [city]','We cure or prevent any dietary condition']::text[],ARRAY['Halal certification is maintained by [Certifying Body Name] and is subject to annual renewal. Certificate available upon request.','Menu items containing gluten (noodles, bread products) are prepared in a shared kitchen environment. Guests with celiac disease should advise staff.','Allergen information is available for all menu items. Please inform your server of any dietary restrictions before ordering.','Catering services subject to minimum order requirements and advance booking. Contact restaurant for details.']::text[],false,false,false,ARRAY['Do not claim halal status in advertising without displaying current certification number and expiry','Allergen claims must be substantiated and menu-specific, not blanket statements','Do not use protected cultural or religious terms (halal, uyghur) in misleading contexts','Imported spice ingredients must comply with FDA labeling requirements before promotional claims about origin are made','Any alcohol service must comply with state liquor license advertising rules']::text[])
