INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:vacation_home_rental_agency',true,'Real Estate Broker / Property Manager License #',ARRAY['State Real Estate Commission (jurisdiction-specific)','Vacation Rental Management Association (VRMA)','State Department of Revenue - Lodging Tax Authority','Local Municipality STR Permit Authority','U.S. Department of Housing and Urban Development (Fair Housing Act)']::text[],ARRAY['guaranteed rental income','we guarantee occupancy rates','best price guaranteed for owners','no fees ever','unlimited bookings guaranteed','highest income in the market']::text[],ARRAY['Income projections are estimates only and are not guaranteed.','Management services are subject to a signed property management agreement.','Short-term rental permits are the responsibility of the property owner; agency may assist but cannot guarantee permit approval.','Security deposits are held in a regulated trust account in accordance with applicable state law.','Lodging tax obligations vary by municipality; owners are advised to consult a tax professional.','Fair housing laws apply to all guest screening and vetting practices.']::text[],false,false,true,ARRAY['Cannot guarantee specific rental income or occupancy rates in advertising','Must disclose management fee structures when advertising specific financial outcomes','Must not represent unlicensed staff as licensed brokers or property managers','Cannot use guest reviews to imply discriminatory screening preferences','Must include applicable license number in advertising where required by state law','Cannot advertise ADA compliance without documented accessibility audit']::text[])
