INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:video_arcade',true,'Amusement Device Permit # / Business License #',ARRAY['State or Local Business Licensing Authority','Local Fire Marshal / Fire Safety Inspector','State Alcoholic Beverage Control Board (barcade format)','Local Building and Safety Department (Certificate of Occupancy)','Americans with Disabilities Act (ADA) Enforcement — U.S. Dept of Justice','IAAPA Global Safety Standards (voluntary industry standard)']::text[],ARRAY['guaranteed to win prizes','jackpot payout','cash redemption for tickets','gambling','no age restrictions apply']::text[],ARRAY['Age restrictions and parental supervision policies apply; please review before visiting','Alcohol service available only to guests 21+ with valid ID; applicable only at barcade locations','Prize redemption tickets have no cash value and may not be exchanged for cash','Maximum occupancy limits are enforced per fire safety regulations','ADA accommodations available; contact venue in advance for specific accessibility needs']::text[],true,false,false,ARRAY['Must not advertise ticket redemption as a lottery, sweepstakes, or gambling activity','Alcohol advertising must comply with state ABC advertising rules for barcade formats','Must not imply guaranteed prizes or cash value for redemption tickets','Birthday party pricing must clearly disclose what is and is not included in packages','Capacity promotions must not exceed fire-code posted occupancy limits']::text[])
