INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:video_equipment_repair_service',true,'State Business License #',ARRAY['Federal Communications Commission (FCC)','U.S. Environmental Protection Agency (EPA) — e-waste and hazardous materials','Occupational Safety and Health Administration (OSHA)','IPC — Association Connecting Electronics Industries (J-STD-001)','Manufacturer authorization bodies: Sony, Canon, Panasonic']::text[],ARRAY['Guaranteed to fix any camera','We will not void your warranty','Original manufacturer parts always used','Certified by the manufacturer (without valid current authorization)','100% success rate on all repairs','Better than factory repair']::text[],ARRAY['Third-party repair services may affect manufacturer warranty — customers should confirm coverage before authorizing repairs','Electronic components disposed of in compliance with EPA e-waste regulations','Repair estimates are preliminary and subject to change upon full diagnostic teardown','IPC and ETA certifications subject to renewal — confirm current status upon request','Authorized service center status is brand-specific and model-specific — confirm applicability before service']::text[],false,false,false,ARRAY['Must not claim manufacturer authorization without current valid credentials','Must not imply warranty preservation guarantees without written manufacturer confirmation','FCC regulations prohibit reassembly modifications that alter device radio frequency characteristics','EPA mandates proper disclosure of e-waste handling procedures in customer-facing materials','Must not use manufacturer logos or trademarks in advertising without explicit licensing agreement']::text[])
