INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:video_game_store',true,'Secondhand Dealer License #',ARRAY['State Department of Consumer Affairs (varies by state)','State Police or Sheriff secondhand dealer registry (varies by state)','Payment Card Industry Security Standards Council (PCI DSS)','Entertainment Software Rating Board (ESRB) Retailer Compliance Program']::text[],ARRAY['We buy any game at the best price guaranteed','Guaranteed trade-in values online are final','All pre-owned games work perfectly','No questions asked on all trade-ins','We accept all consoles regardless of condition']::text[],ARRAY['Trade-in values are estimates only and subject to in-store inspection and final approval','Pre-owned games and consoles are sold as-is unless covered by store warranty policy','ESRB-rated M (Mature 17+) and AO (Adults Only) titles require valid government-issued ID for purchase','Store credit is non-refundable and subject to store terms and conditions','Secondhand dealer transactions may be reported to local law enforcement per state secondhand dealer statutes']::text[],true,false,false,ARRAY['Must not advertise M or AO rated game content in materials directed at minors','Trade-in price advertisements must include disclaimer that prices are subject to change and in-store verification','Cannot guarantee specific WATA or VGA grades on items not yet professionally graded','Must comply with FTC Used Goods disclosure requirements for pre-owned sales advertising','State secondhand dealer laws may restrict advertising of serial-numbered goods without disclosure']::text[])
