INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:video_production_service',true,'FAA Part 107 Remote Pilot Certificate #',ARRAY['Federal Aviation Administration (FAA) — drone operations under Part 107','SAG-AFTRA — talent union agreements for signatory productions','FTC — endorsement and sponsored content disclosure requirements','U.S. Copyright Office — music sync and master licensing compliance','Local/State Film Offices — public location filming permit requirements']::text[],ARRAY['We guarantee your video will go viral','#1 video production company in [city] (unverified superlative)','Risk-free production (no liability implied)','Unlimited revisions included (unless contractually specified)']::text[],ARRAY['FAA Part 107 certification required for all commercial drone operations; certificate number available upon request','All talent appearances require signed release documentation prior to distribution','Music used in productions is licensed via sync agreements; clients are responsible for platform-specific licensing beyond contracted use','Sponsored or paid content must include FTC-compliant disclosure in final deliverable','Film permits are required for public location shoots; production company or client is responsible for securing applicable permits','SAG-AFTRA minimum rates apply to signatory productions; non-union productions are not covered under this agreement']::text[],false,false,false,ARRAY['Cannot claim award status without verifiable, named award and year','Cannot imply broadcaster or streaming platform relationships without documented credits','Drone footage must disclose FAA certification status in any advertising that promotes aerial services','FTC requires clear disclosure of any client incentive offered in exchange for testimonials or reviews']::text[])
