INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:volvo_dealer',true,'State Motor Vehicle Dealer License #',ARRAY['State Department of Motor Vehicles / Motor Vehicle Dealer Licensing Board (jurisdiction-specific)','Federal Trade Commission (FTC) — Used Car Rule and TILA enforcement','Volvo Cars USA — Franchise Agreement Standards','National Highway Traffic Safety Administration (NHTSA) — Recall compliance','Environmental Protection Agency (EPA) — Fuel Economy Labeling','Consumer Financial Protection Bureau (CFPB) — Auto Lending Disclosures']::text[],ARRAY['guaranteed credit approval','best price in the state','lowest price guaranteed','we beat any deal','factory direct pricing','no fees','zero dealer markup on all vehicles','free car with purchase']::text[],ARRAY['All advertised prices exclude tax, title, license, and dealer fees unless otherwise stated','Financing subject to credit approval through participating lenders','EPA fuel economy estimates are for comparison purposes; actual mileage will vary','CPO vehicles are subject to prior sale; inventory subject to change','Lease payments based on MSRP with approved credit through Volvo Financial Services; mileage restrictions apply','Federal EV tax credit eligibility subject to buyer income limits and vehicle MSRP caps under IRS Section 30D','FTC Used Car Buyers Guide must be displayed on all used vehicles offered for sale','Lemon Law rights vary by state; consult your state''s consumer protection statutes']::text[],false,false,true,ARRAY['Truth in Lending Act (TILA) requires APR and total finance charge disclosure in financing ads','Regulation M requires full lease disclosure including capitalized cost, residual, and money factor in lease ads','FTC Used Car Rule mandates Buyers Guide display on all used vehicles','EPA labeling must appear on all new vehicle window stickers and online listings','State dealer advertising regulations may prohibit bait-and-switch pricing; specific state rules apply','CFPB guidance prohibits discriminatory pricing language in auto lending promotions','Volvo Cars USA co-op advertising guidelines govern use of brand marks and model imagery']::text[])
