INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:watch_store',true,'State Secondhand Dealer License #',ARRAY['Federal Trade Commission (FTC) – Jewelry and Watch Advertising Guidelines','FTC – Used and Pre-Owned Goods Disclosure Requirements','State-level Secondhand Dealer Licensing Authorities (varies by state)','Magnuson-Moss Warranty Act (administered by FTC)','U.S. Customs and Border Protection – Import Compliance for Internationally Sourced Timepieces']::text[],ARRAY['Rolex Authorized Dealer (unless formally contracted)','Certified Pre-Owned Rolex (trademark restricted to Rolex AD network)','Swiss Made movement (unless movement meets Swiss legal threshold)','Guaranteed authentic (absolute guarantee claims without documented verification process)','Investment-grade timepiece (unsubstantiated financial return claims)','Original manufacturer parts (unless parts are OEM-verified)']::text[],ARRAY['Pre-owned watches are sold as-is unless otherwise stated; condition disclosed at time of sale','Service estimates are non-binding; final charges confirmed upon movement inspection','Watch appraisals reflect fair market value at date of appraisal and may not reflect current market conditions','Import duties and taxes are the responsibility of the buyer for internationally sourced pieces','Warranty on serviced watches covers workmanship only; parts subject to separate warranty terms','State secondhand dealer license number displayed as required by applicable state law']::text[],false,false,false,ARRAY['Brand-name use in advertising must comply with trademark holder guidelines (e.g., Rolex, Omega, Patek Philippe)','Authorized service center designation may only be claimed if active manufacturer contract is in place','Pre-owned watch descriptions must accurately state condition, age, and any non-original parts','Movement origin (Swiss Made, Japanese, etc.) must meet legal standards before use in advertising','Price claims including ''retail value'' or ''MSRP'' must reflect accurate current manufacturer pricing','Anti-counterfeiting: advertising must not imply authenticity without documented verification']::text[])
