INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:water_skiing_club',true,'USA Water Ski Club Certification #',ARRAY['USA Water Ski and Wake Sports','American Water Ski Association (AWSA)','U.S. Coast Guard — Boating Safety Division','State Boating Authority (jurisdiction-specific)','State Environmental / Waterway Authority (jurisdiction-specific)']::text[],ARRAY['guaranteed to make you a competitive skier','safest water sport','no risk of injury','certified professional water skier instructors on staff unless credential verified','results guaranteed']::text[],ARRAY['All members and guests must sign a liability waiver prior to participation','Club pull boat operation complies with applicable U.S. Coast Guard safety regulations','Personal flotation devices are required for all participants under 13 and recommended for all','Water conditions and session availability are subject to change without notice','Tournament registration requires active USA Water Ski membership']::text[],false,false,false,ARRAY['Must not claim AWSA or USA Water Ski endorsement beyond affiliated club status','Certified driver and judge counts must reflect currently credentialed staff only','Safety claims must be substantiated and not imply elimination of inherent sport risks','Tournament sanctioning status must be current and verified before advertising']::text[])
