INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:water_softening_equipment_supplier',true,'State Plumbing Contractor License #',ARRAY['Water Quality Association (WQA) — Certified Water Specialist credentialing','NSF International — NSF/ANSI 44 product certification body','State Plumbing Licensing Boards (jurisdiction-specific)','State Water Resources Control Boards (brine discharge regulation, e.g. California SWRCB)','Texas Commission on Environmental Quality (TCEQ) for TX brine and softener restrictions','U.S. Environmental Protection Agency (EPA) — salt discharge to septic and surface water rules']::text[],ARRAY['Removes all contaminants from your water','Guarantees elimination of all health risks','Approved by the EPA','Completely eliminates hard water forever with no maintenance','Certified to treat lead or bacteria']::text[],ARRAY['NSF/ANSI 44 certification applies to specific listed product models only — confirm model certification before purchase','Salt discharge from water softeners may be regulated or restricted in your municipality or state — consult local regulations before installation','Water softeners are not drinking water treatment devices and do not remove bacteria, viruses, or heavy metals','Plumbing permit may be required for new softener installation — contact your local building department','Potassium chloride use does not guarantee compliance with low-sodium dietary requirements — consult a physician']::text[],false,false,false,ARRAY['Do not imply NSF or WQA certification of uncertified product models','Do not advertise that salt-free conditioners are equivalent to certified ion exchange softeners in hardness removal','Do not claim brine discharge is always environmentally safe — restrictions vary by jurisdiction','Do not represent California or Texas market availability without confirming current local ordinance compliance','Do not imply the business holds a plumbing contractor license if only a supply-and-advise role is performed without licensed contractor on staff']::text[])
