INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:wholesale_grocer',true,'State Food Warehouse License #',ARRAY['U.S. Food and Drug Administration (FDA) — FSMA','USDA Agricultural Marketing Service (AMS) — Organic Program','State Department of Agriculture — Food Warehouse Licensing and Inspections','NSF International — Food Safety Certification','Safe Quality Food Institute (SQFI) — SQF Audit Program']::text[],ARRAY['guaranteed lowest wholesale prices','FDA approved facility','USDA approved distributor','all-natural with no additives (without substantiation)','certified organic (without valid NOP certificate)','best prices guaranteed']::text[],ARRAY['This facility operates under an FDA FSMA food safety plan. Contact us for compliance documentation.','USDA Organic handler certification number available upon request. Valid certificate on file.','State food warehouse license number displayed per applicable state regulation.','Cold storage temperature logs maintained per FDA 21 CFR requirements and available for trade account audit.','SQF certification scope and audit score available to qualified trade buyers upon request.']::text[],false,false,false,ARRAY['Do not claim USDA organic status without displaying valid NOP certificate number','Do not use ''FDA approved'' — FDA does not approve food facilities; use ''FDA registered'' or ''FSMA compliant''','Do not advertise specific pricing without including applicable MOQ and trade account qualification requirements','HACCP and SQF claims must reference current certified plan versions — do not cite expired certifications','State inspection scores must reflect the most recent official inspection — do not display outdated scores']::text[])
