INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:wind_turbine_builder',true,'State Contractor License #',ARRAY['OSHA (Occupational Safety and Health Administration) - 1926 Subpart R and Subpart N','International Electrotechnical Commission (IEC) - IEC 61400 Wind Turbine Standards','National Fire Protection Association (NFPA) - NFPA 70 National Electrical Code','State Contractor Licensing Boards (jurisdiction-specific)','U.S. Army Corps of Engineers and State Environmental Agencies (site disturbance permits)']::text[],ARRAY['guaranteed lowest price on turbine installation','OSHA-free job site','no permits required','fastest turbine erection in the industry without compromise','fully compliant without inspections']::text[],ARRAY['All construction work performed in compliance with applicable state contractor licensing requirements.','Crane and rigging operations conducted in accordance with OSHA 1926 Subpart N regulations.','Turbine installation performed in compliance with IEC 61400 design and safety standards.','Electrical installation complies with NFPA 70 National Electrical Code requirements.','Environmental site disturbance activities conducted under applicable federal and state permits.','OEM authorized installer designation is model- and manufacturer-specific; verify applicable turbine makes.']::text[],false,false,false,ARRAY['Must not claim OSHA compliance without documentation; cite specific subparts','Must not imply OEM authorization for turbine models not covered by active credential','Must not advertise certifications that have lapsed without renewal documentation','Safety statistics (TRIR, EMR) must reflect verified, current data periods','Must not use the term ''licensed'' in states where the business does not hold active contractor license']::text[])
