INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:window_cleaning_service',true,'State Contractor License #',ARRAY['State Contractor Licensing Board (jurisdiction-specific)','OSHA — Occupational Safety and Health Administration','EPA — Environmental Protection Agency (Lead RRP Rule)','ANSI — American National Standards Institute (IWCA I-14.1)']::text[],ARRAY['guaranteed lowest price','safest in the industry','OSHA approved','EPA certified process','licensed and insured in all 50 states','we eliminate all fall risk','lead-safe guaranteed','no chance of property damage']::text[],ARRAY['State contractor license number must be displayed on all contracts, invoices, and advertising where required by state law.','Liability insurance certificate of insurance available upon request for commercial accounts.','High-rise and rope access work performed in compliance with ANSI IWCA I-14.1 and OSHA 1910.28 fall protection standards.','Work on pre-1978 buildings may require EPA RRP lead paint safe work practices — disclose status to customers prior to service.','Scheduling is subject to weather conditions; rescheduling policy applies for unsafe outdoor working conditions.']::text[],false,false,false,ARRAY['Must not claim government endorsement or OSHA ''approval'' — OSHA certifies training completion only, not business practices.','Must not imply sole or exclusive IWCA membership confers superiority over unlicensed competitors without substantiation.','Insurance and license claims must reflect current, verifiable coverage and registration.','EPA lead paint compliance claims must reflect actual current RRP certification status.','Price guarantees must include all material terms and expiration conditions per FTC guidelines.']::text[])
